(351393,39044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La criatura ... por la cueva oscura cuando la salida se hizo visible.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'La criatura caminaba por la cueva oscura cuando la salida se hizo visible.'::text),
(351392,39044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La créature ... dans la grotte sombre quand la sortie est devenue visible.'::text,'marchait'::text,'marcha'::text,'a marché'::text,'La créature marchait dans la grotte sombre quand la sortie est devenue visible.'::text),
(351395,39044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıkış görünür hale geldiğinde yaratık karanlık mağarada ...'::text,'yürüyordu'::text,'yürüdü'::text,'yürümüş'::text,'Çıkış görünür hale geldiğinde yaratık karanlık mağarada yürüyordu.'::text),
(351396,39044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lény ... a sötét barlangon át, amikor feltűnt a kijárat.'::text,'haladt'::text,'átment'::text,'átment'::text,'A lény haladt a sötét barlangon át, amikor feltűnt a kijárat.'::text),
(351399,39045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Pferd ... seit ungefähr einer Minute auf den Ausgang zu.'::text,'läuft'::text,'läuft gerade'::text,'läuft'::text,'Das Pferd läuft seit ungefähr einer Minute auf den Ausgang zu.'::text),
(351403,39045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кінь ... до виходу вже приблизно хвилину.'::text,'іде'::text,'іде'::text,'ходить'::text,'Кінь іде до виходу вже приблизно хвилину.'::text),
(351402,39045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El caballo ... hacia la salida aproximadamente un minuto.'::text,'lleva caminando'::text,'está caminando'::text,'camina'::text,'El caballo lleva caminando hacia la salida aproximadamente un minuto.'::text),
(351401,39045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cheval ... vers la sortie depuis environ une minute.'::text,'marche'::text,'est en train de marcher'::text,'marche'::text,'Le cheval marche vers la sortie depuis environ une minute.'::text),
(351404,39045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'At yaklaşık bir dakikadır çıkışa doğru ...'::text,'yürüyor'::text,'yürüyor'::text,'yürür'::text,'At yaklaşık bir dakikadır çıkışa doğru yürüyor.'::text),
(351405,39045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ló körülbelül egy perce ... a kijárat felé.'::text,'halad'::text,'halad'::text,'megy'::text,'A ló körülbelül egy perce halad a kijárat felé.'::text),
(351408,39046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Pferd erreichte den Ausgang und ... hinaus auf den schwarzen Strand.'::text,'trat'::text,'trat gerade'::text,'ist getreten'::text,'Das Pferd erreichte den Ausgang und trat hinaus auf den schwarzen Strand.'::text),
(351412,39046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кінь дістався виходу і ... на чорний пляж.'::text,'вийшов'::text,'виходив'::text,'вийшов'::text,'Кінь дістався виходу і вийшов на чорний пляж.'::text),
(351411,39046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El caballo llegó a la salida y ... a la playa negra.'::text,'salió'::text,'estaba saliendo'::text,'ha salido'::text,'El caballo llegó a la salida y salió a la playa negra.'::text),
(351410,39046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cheval a atteint la sortie et ... sur la plage noire.'::text,'est sorti'::text,'sortait'::text,'est sorti'::text,'Le cheval a atteint la sortie et est sorti sur la plage noire.'::text),
(351413,39046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'At çıkışa ulaştı ve siyah kumsala ...'::text,'çıktı'::text,'çıkıyordu'::text,'çıkmış'::text,'At çıkışa ulaştı ve siyah kumsala çıktı.'::text),
(351414,39046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ló elérte a kijáratot, és ... a fekete strandra.'::text,'kilépett'::text,'éppen kilépett'::text,'kilépett'::text,'A ló elérte a kijáratot, és kilépett a fekete strandra.'::text),
(351417,39047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Pferd ist heute zweimal durch diesen Höhlenausgang ...'::text,'gegangen'::text,'gegangen'::text,'geht'::text,'Das Pferd ist heute zweimal durch diesen Höhlenausgang gegangen.'::text),
(351421,39047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кінь сьогодні двічі ... через цей вихід із печери.'::text,'пройшов'::text,'проходив'::text,'проходить'::text,'Кінь сьогодні двічі пройшов через цей вихід із печери.'::text),
(351420,39047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El caballo ... por esta salida de la cueva dos veces hoy.'::text,'ha pasado'::text,'ha estado pasando'::text,'pasa'::text,'El caballo ha pasado por esta salida de la cueva dos veces hoy.'::text),
(351419,39047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cheval ... par cette sortie de la grotte deux fois aujourd''hui.'::text,'est passé'::text,'est passé'::text,'passe'::text,'Le cheval est passé par cette sortie de la grotte deux fois aujourd''hui.'::text),
(351422,39047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'At bugün bu mağara çıkışından iki kez ...'::text,'geçti'::text,'geçiyordu'::text,'geçer'::text,'At bugün bu mağara çıkışından iki kez geçti.'::text),
(351423,39047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ló ma kétszer ... át ezen a barlangkijáraton.'::text,'ment'::text,'járt'::text,'megy'::text,'A ló ma kétszer ment át ezen a barlangkijáraton.'::text),
(351435,39049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, morgen um die Zeit ... wir wieder durch den Höhlenausgang, ohne Witz.'::text,'reiten'::text,'reiten'::text,'reiten'::text,'Digga, morgen um die Zeit reiten wir wieder durch den Höhlenausgang, ohne Witz.'::text),
(351439,39049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, завтра в цей час ми знову ... через той вихід із печери, без приколів.'::text,'їхатимемо'::text,'проїдемо'::text,'їдемо'::text,'Йоу, завтра в цей час ми знову їхатимемо через той вихід із печери, без приколів.'::text),
(351438,39049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, mañana a esta hora ... otra vez por esa salida de la cueva, en serio.'::text,'estaremos cabalgando'::text,'cabalgaremos'::text,'cabalgamos'::text,'Oye, mañana a esta hora estaremos cabalgando otra vez por esa salida de la cueva, en serio.'::text),
(351437,39049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, demain à cette heure-ci, on ... encore par cette sortie de grotte, sans mentir.'::text,'sera en train de passer'::text,'passera'::text,'passe'::text,'Yo, demain à cette heure-ci, on sera en train de passer encore par cette sortie de grotte, sans mentir.'::text),
(351440,39049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte yine o mağara çıkışından ..., yemin ederim.'::text,'geçiyor olacağız'::text,'geçeceğiz'::text,'geçiyoruz'::text,'Kanka, yarın bu saatte yine o mağara çıkışından geçiyor olacağız, yemin ederim.'::text),
(351441,39049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor megint azon a barlangkijáraton ..., komolyan.'::text,'lovagolunk át'::text,'átlovagolunk'::text,'lovagolunk át'::text,'Tesó, holnap ilyenkor megint azon a barlangkijáraton lovagolunk át, komolyan.'::text),
(351444,39050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Bro, hier ist es zu dunkel, ich ... jetzt sofort zum Ausgang.'::text,'gehe'::text,'werde gehen'::text,'gehe'::text,'Nee, Bro, hier ist es zu dunkel, ich gehe jetzt sofort zum Ausgang.'::text),
(351448,39050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, брате, тут надто темно, я ... до виходу просто зараз.'::text,'піду'::text,'йтиму'::text,'іду'::text,'Не, брате, тут надто темно, я піду до виходу просто зараз.'::text),
(351447,39050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, bro, aquí está demasiado oscuro, ... hacia la salida ahora mismo.'::text,'iré'::text,'estaré yendo'::text,'voy'::text,'Nah, bro, aquí está demasiado oscuro, iré hacia la salida ahora mismo.'::text),
(351446,39050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, il fait trop sombre ici, je ... vers la sortie tout de suite.'::text,'vais'::text,'serai en train d''aller'::text,'vais'::text,'Non frérot, il fait trop sombre ici, je vais vers la sortie tout de suite.'::text),
(351449,39050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, burası çok karanlık, hemen şimdi çıkışa ...'::text,'gideceğim'::text,'gidiyor olacağım'::text,'giderim'::text,'Yok kanka, burası çok karanlık, hemen şimdi çıkışa gideceğim.'::text),
(351450,39050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, túl sötét van itt, most azonnal ... a kijárathoz.'::text,'megyek'::text,'menni fogok'::text,'megyek'::text,'Nem, tesó, túl sötét van itt, most azonnal megyek a kijárathoz.'::text),
(351453,39051,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Ausgang bei Flut blockiert ..., streicht das Protokoll die Ausritte um 14 Uhr.'::text,'ist'::text,'war'::text,'sein wird'::text,'Wenn der Ausgang bei Flut blockiert ist, streicht das Protokoll die Ausritte um 14 Uhr.'::text),
(351457,39051,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вихід ... заблокований під час припливу, протокол скасовує поїздки о 14:00.'::text,''::text,'був'::text,'буде'::text,'Якщо вихід заблокований під час припливу, протокол скасовує поїздки о 14:00.'::text),
(351456,39051,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la salida ... bloqueada con la marea alta, el protocolo cancela los paseos de las 14:00.'::text,'está'::text,'estaba'::text,'estará'::text,'Si la salida está bloqueada con la marea alta, el protocolo cancela los paseos de las 14:00.'::text),
(351455,39051,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la sortie ... bloquée à marée haute, le protocole annule les balades de 14 h.'::text,'est'::text,'était'::text,'sera'::text,'Si la sortie est bloquée à marée haute, le protocole annule les balades de 14 h.'::text),
(351458,39051,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıkış yüksek gelgitte kapalı ..., protokol saat 14.00''teki turları iptal eder.'::text,'ise'::text,'idiyse'::text,'olacaksa'::text,'Çıkış yüksek gelgitte kapalı ise, protokol saat 14.00''teki turları iptal eder.'::text),
(351459,39051,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kijárat dagálykor el ... zárva, a protokoll törli a 14 órás lovaglásokat.'::text,'van'::text,'volt'::text,'lesz'::text,'Ha a kijárat dagálykor el van zárva, a protokoll törli a 14 órás lovaglásokat.'::text),
(351462,39052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir ritten in ... hinein, und niemand konnte den Ausgang sehen!'::text,'völlige Dunkelheit'::text,'eine völlige Dunkelheit'::text,'die völligen Dunkelheiten'::text,'Wir ritten in völlige Dunkelheit hinein, und niemand konnte den Ausgang sehen!'::text),
(351466,39052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ми в''їхали в ..., і ніхто не бачив виходу!'::text,'повну темряву'::text,'повну темряву'::text,'повні темряви'::text,'Ми в''їхали в повну темряву, і ніхто не бачив виходу!'::text),
(351465,39052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Entramos en ... y nadie podía ver la salida!'::text,'una oscuridad total'::text,'una oscuridad total'::text,'las oscuridades totales'::text,'¡Entramos en una oscuridad total y nadie podía ver la salida!'::text),
(351464,39052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nous sommes entrés à cheval dans ..., et personne ne voyait la sortie !'::text,'une obscurité totale'::text,'une obscurité totale'::text,'les obscurités totales'::text,'Nous sommes entrés à cheval dans une obscurité totale, et personne ne voyait la sortie !'::text),
(351467,39052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... girdik ve kimse çıkışı göremedi!'::text,'Zifiri karanlığa'::text,'Bir zifiri karanlığa'::text,'Zifiri karanlıklara'::text,'Zifiri karanlığa girdik ve kimse çıkışı göremedi!'::text),
(351468,39052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belovagoltunk ..., és senki sem látta a kijáratot!'::text,'teljes sötétségbe'::text,'egy teljes sötétségbe'::text,'a teljes sötétségekbe'::text,'Belovagoltunk teljes sötétségbe, és senki sem látta a kijáratot!'::text),
(351480,39054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir ... gefühlt eine Ewigkeit im Dunkeln, bevor der Ausgang auftauchte!'::text,'waren geritten'::text,'sind geritten'::text,'ritten'::text,'Wir waren geritten gefühlt eine Ewigkeit im Dunkeln, bevor der Ausgang auftauchte!'::text),
(351484,39054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ми ... в темряві, здавалося, цілу вічність, перш ніж з''явився вихід!'::text,'їхали'::text,'їхали'::text,'їхали'::text,'Ми їхали в темряві, здавалося, цілу вічність, перш ніж з''явився вихід!'::text),
(351483,39054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nosotros ... en la oscuridad lo que pareció una eternidad antes de que apareciera la salida!'::text,'habíamos estado cabalgando'::text,'hemos estado cabalgando'::text,'estábamos cabalgando'::text,'¡Nosotros habíamos estado cabalgando en la oscuridad lo que pareció una eternidad antes de que apareciera la salida!'::text),
(351482,39054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nous ... dans le noir pendant ce qui semblait une éternité avant que la sortie n''apparaisse !'::text,'avions chevauché'::text,'avons chevauché'::text,'chevauchions'::text,'Nous avions chevauché dans le noir pendant ce qui semblait une éternité avant que la sortie n''apparaisse !'::text),
(351485,39054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıkış görünmeden önce karanlıkta sonsuzluk gibi gelen bir süre ...!'::text,'at sürmüştük'::text,'at sürüyoruz'::text,'at sürüyorduk'::text,'Çıkış görünmeden önce karanlıkta sonsuzluk gibi gelen bir süre at sürmüştük!'::text),
(351486,39054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy örökkévalóságnak tűnő ideig ... a sötétben, mielőtt feltűnt a kijárat!'::text,'lovagoltunk'::text,'lovagoltunk'::text,'lovagoltunk'::text,'Egy örökkévalóságnak tűnő ideig lovagoltunk a sötétben, mielőtt feltűnt a kijárat!'::text),
(344235,38249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wolf noch näher heranschleicht, ... die Henne ihre Küken in Sicherheit.'::text,'bringt'::text,'würde bringen'::text,'brachte'::text,'Wenn der Wolf noch näher heranschleicht, bringt die Henne ihre Küken in Sicherheit.'::text),
(344239,38249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вовк підкрадеться ще ближче, курка ... своїх курчат геть.'::text,'забере'::text,'забрала б'::text,'забрала'::text,'Якщо вовк підкрадеться ще ближче, курка забере своїх курчат геть.'::text),
(344238,38249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el lobo se acerca más a hurtadillas, la gallina ... a sus pollitos.'::text,'se llevará'::text,'se llevaría'::text,'se llevó'::text,'Si el lobo se acerca más a hurtadillas, la gallina se llevará a sus pollitos.'::text),
(344237,38249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le loup s''approche encore en rampant, la poule ... ses poussins.'::text,'emmènera'::text,'emmènerait'::text,'a emmené'::text,'Si le loup s''approche encore en rampant, la poule emmènera ses poussins.'::text),
(344240,38249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurt biraz daha sinsice yaklaşırsa, tavuk civcivlerini ...'::text,'götürecek'::text,'götürürdü'::text,'götürdü'::text,'Kurt biraz daha sinsice yaklaşırsa, tavuk civcivlerini götürecek.'::text),
(344241,38249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a farkas még közelebb lopakodik, a tyúk ... a csibéit.'::text,'elviszi'::text,'elvinné'::text,'elvitte'::text,'Ha a farkas még közelebb lopakodik, a tyúk elviszi a csibéit.'::text),
(344244,38250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Würde der Wolf einen Schritt näher schleichen, ... die Henne kreischend in den Wald!'::text,'rennte'::text,'wird rennen'::text,'rannte'::text,'Würde der Wolf einen Schritt näher schleichen, rennte die Henne kreischend in den Wald!'::text),
(344248,38250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вовк підкрався на крок ближче, курка ... з криком у ліс!'::text,'втекла б'::text,'втече'::text,'втекла'::text,'Якби вовк підкрався на крок ближче, курка втекла б з криком у ліс!'::text),
(344247,38250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el lobo se acercara un paso más, la gallina ... gritando al bosque!'::text,'huiría'::text,'huirá'::text,'huyó'::text,'¡Si el lobo se acercara un paso más, la gallina huiría gritando al bosque!'::text),
(344246,38250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le loup s''approchait d''un pas de plus, la poule ... en hurlant dans la forêt !'::text,'s''enfuirait'::text,'s''enfuira'::text,'s''enfuit'::text,'Si le loup s''approchait d''un pas de plus, la poule s''enfuirait en hurlant dans la forêt !'::text),
(344249,38250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurt bir adım daha sinsice yaklaşsaydı, tavuk çığlık atarak ormana ...!'::text,'kaçardı'::text,'kaçacak'::text,'kaçtı'::text,'Kurt bir adım daha sinsice yaklaşsaydı, tavuk çığlık atarak ormana kaçardı!'::text),
(344250,38250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a farkas még egy lépéssel közelebb lopakodna, a tyúk sikítva ... az erdőbe!'::text,'rohanna'::text,'rohan majd'::text,'rohant'::text,'Ha a farkas még egy lépéssel közelebb lopakodna, a tyúk sikítva rohanna az erdőbe!'::text),
(344253,38251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Küken ... vom heranschleichenden Wolf, und die Henne ahnt nichts! Ein Albtraum!'::text,'werden beobachtet'::text,'beobachten'::text,'beobachteten'::text,'Die Küken werden beobachtet vom heranschleichenden Wolf, und die Henne ahnt nichts! Ein Albtraum!'::text),
(344257,38251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За курчатами ... вовк, що підкрадається, а курка й гадки не має! Жах!'::text,'стежить'::text,'стежать'::text,'стежив'::text,'За курчатами стежить вовк, що підкрадається, а курка й гадки не має! Жах!'::text),
(344256,38251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los pollitos ... por el lobo sigiloso y la gallina no tiene ni idea! ¡Una pesadilla!'::text,'están siendo vigilados'::text,'están vigilando'::text,'vigilaron'::text,'¡Los pollitos están siendo vigilados por el lobo sigiloso y la gallina no tiene ni idea! ¡Una pesadilla!'::text),
(344255,38251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les poussins ... par le loup qui rampe, et la poule n''en a aucune idée ! Un cauchemar !'::text,'sont observés'::text,'observent'::text,'ont observé'::text,'Les poussins sont observés par le loup qui rampe, et la poule n''en a aucune idée ! Un cauchemar !'::text),
(344258,38251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civcivler sinsice yaklaşan kurt tarafından ... ve tavuğun hiç haberi yok! Tam bir kâbus!'::text,'izleniyor'::text,'izliyor'::text,'izledi'::text,'Civcivler sinsice yaklaşan kurt tarafından izleniyor ve tavuğun hiç haberi yok! Tam bir kâbus!'::text),
(344259,38251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibéket ... a lopakodó farkas, és a tyúknak fogalma sincs róla! Rémálom!'::text,'figyeli'::text,'figyelik'::text,'figyelte'::text,'A csibéket figyeli a lopakodó farkas, és a tyúknak fogalma sincs róla! Rémálom!'::text),
(344262,38252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wolf ... mit gesenktem Kopf auf die Vögel zu, wie es für Wölfe typisch ist.'::text,'schleicht'::text,'wird geschlichen'::text,'schleichend'::text,'Der Wolf schleicht mit gesenktem Kopf auf die Vögel zu, wie es für Wölfe typisch ist.'::text),
(344266,38252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вовк ... до птахів з низько опущеною головою, як це типово роблять вовки.'::text,'підкрадається'::text,'підкрадається'::text,'підкрадання'::text,'Вовк підкрадається до птахів з низько опущеною головою, як це типово роблять вовки.'::text),
(344265,38252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lobo ... hacia las aves con la cabeza baja, como suelen hacer los lobos.'::text,'se acerca sigilosamente'::text,'es acercado sigilosamente'::text,'acercándose sigilosamente'::text,'El lobo se acerca sigilosamente hacia las aves con la cabeza baja, como suelen hacer los lobos.'::text),
(344264,38252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le loup ... vers les oiseaux la tête basse, comme le font typiquement les loups.'::text,'rampe'::text,'est rampé'::text,'rampant'::text,'Le loup rampe vers les oiseaux la tête basse, comme le font typiquement les loups.'::text),
(344267,38252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurt, kurtların tipik olarak yaptığı gibi, başı eğik şekilde kuşlara doğru ...'::text,'sinsice ilerler'::text,'sinsice ilerletilir'::text,'sinsice ilerleyerek'::text,'Kurt, kurtların tipik olarak yaptığı gibi, başı eğik şekilde kuşlara doğru sinsice ilerler.'::text),
(344268,38252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A farkas lehajtott fejjel ... a madarak felé, ahogy az a farkasokra jellemző.'::text,'lopakodik'::text,'lopakodik'::text,'lopakodva'::text,'A farkas lehajtott fejjel lopakodik a madarak felé, ahogy az a farkasokra jellemző.'::text),
(344271,38253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tier ... auf der Jagd sein, während es vorwärtsschleicht, obwohl das nicht sicher ist.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Das Tier könnte auf der Jagd sein, während es vorwärtsschleicht, obwohl das nicht sicher ist.'::text),
(344275,38253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Істота ... полювати, коли підкрадається вперед, хоча це не точно.'::text,'може'::text,'мусить'::text,'не може'::text,'Істота може полювати, коли підкрадається вперед, хоча це не точно.'::text),
(344274,38253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La criatura ... estar cazando mientras avanza sigilosamente, aunque no es seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'La criatura podría estar cazando mientras avanza sigilosamente, aunque no es seguro.'::text),
(344273,38253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La créature ... être en train de chasser en avançant à pas de loup, bien que ce ne soit pas certain.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'La créature pourrait être en train de chasser en avançant à pas de loup, bien que ce ne soit pas certain.'::text),
(344276,38253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Canlı sinsice ilerlerken avlanıyor ..., gerçi bu kesin değil.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Canlı sinsice ilerlerken avlanıyor olabilir, gerçi bu kesin değil.'::text),
(344277,38253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az állat ... vadászik, ahogy előrelopakodik, bár ez nem biztos.'::text,'talán'::text,'biztosan'::text,'biztosan nem'::text,'Az állat talán vadászik, ahogy előrelopakodik, bár ez nem biztos.'::text),
(344280,38254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tier, ... langsam auf die Vögel zuschleicht, hält den Kopf dicht am Boden.'::text,'das'::text,'das'::text,'dessen'::text,'Das Tier, das langsam auf die Vögel zuschleicht, hält den Kopf dicht am Boden.'::text),
(344284,38254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Істота, ... повільно підкрадається до птахів, тримає голову близько до землі.'::text,'яка'::text,'яка'::text,'чия'::text,'Істота, яка повільно підкрадається до птахів, тримає голову близько до землі.'::text),
(344283,38254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La criatura, ... se acerca lentamente a las aves, mantiene la cabeza cerca del suelo.'::text,'que'::text,'que'::text,'cuya'::text,'La criatura, que se acerca lentamente a las aves, mantiene la cabeza cerca del suelo.'::text),
(344282,38254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La créature, ... s''approche lentement des oiseaux, garde la tête près du sol.'::text,'qui'::text,'qui'::text,'dont'::text,'La créature, qui s''approche lentement des oiseaux, garde la tête près du sol.'::text),
(344285,38254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuşlara doğru yavaşça ... sokulan canlı, başını yere yakın tutuyor.'::text,''::text,NULL::text,NULL::text,'Kuşlara doğru yavaşça sokulan canlı, başını yere yakın tutuyor.'::text),
(344286,38254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az állat, ... lassan a madarak felé lopakodik, a fejét a földhöz közel tartja.'::text,'amely'::text,'amely'::text,'amelynek'::text,'Az állat, amely lassan a madarak felé lopakodik, a fejét a földhöz közel tartja.'::text),
(344289,38255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, der Wolf ... langsam vorwärts, also war er nicht schnell.'::text,'schleiche'::text,'schleicht'::text,'sei geschlichen'::text,'Er sagte, der Wolf schleiche langsam vorwärts, also war er nicht schnell.'::text),
(344293,38255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що вовк ... вперед повільно, тож він ішов не швидко.'::text,'підкрадався'::text,'підкрадається'::text,'підкрався'::text,'Він сказав, що вовк підкрадався вперед повільно, тож він ішов не швидко.'::text),
(344292,38255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el lobo ... despacio hacia delante, así que no iba rápido.'::text,'avanzaba sigilosamente'::text,'avanza sigilosamente'::text,'ha avanzado sigilosamente'::text,'Dijo que el lobo avanzaba sigilosamente despacio hacia delante, así que no iba rápido.'::text),
(344291,38255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que le loup ... lentement vers l''avant, donc il n''allait pas vite.'::text,'rampait'::text,'rampe'::text,'a rampé'::text,'Il a dit que le loup rampait lentement vers l''avant, donc il n''allait pas vite.'::text),
(344294,38255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurdun yavaşça ileri ... söyledi, yani hızlı gitmiyormuş.'::text,'süzüldüğünü'::text,'süzülür'::text,'süzülmüş'::text,'Kurdun yavaşça ileri süzüldüğünü söyledi, yani hızlı gitmiyormuş.'::text),
(344295,38255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a farkas lassan ... előre, tehát nem ment gyorsan.'::text,'lopakodik'::text,'lopakodik'::text,'lopakodott'::text,'Azt mondta, hogy a farkas lassan lopakodik előre, tehát nem ment gyorsan.'::text),
(344298,38256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Wolf ... ein Welpe, deshalb schlich er nicht wie ein großer Wolf.'::text,'war früher'::text,'wäre'::text,'war es gewohnt'::text,'Dieser Wolf war früher ein Welpe, deshalb schlich er nicht wie ein großer Wolf.'::text),
(344302,38256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей вовк ... цуценям, тому не підкрадався, як великий вовк.'::text,'колись був'::text,'був би'::text,'звик бути'::text,'Цей вовк колись був цуценям, тому не підкрадався, як великий вовк.'::text),
(344301,38256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este lobo ... un cachorro, así que no se acercaba sigilosamente como un lobo grande.'::text,'antes era'::text,'sería'::text,'estaba acostumbrado a ser'::text,'Este lobo antes era un cachorro, así que no se acercaba sigilosamente como un lobo grande.'::text),
(344300,38256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce loup ... un louveteau, donc il ne rampait pas comme un grand loup.'::text,'était autrefois'::text,'serait'::text,'avait l''habitude d''être'::text,'Ce loup était autrefois un louveteau, donc il ne rampait pas comme un grand loup.'::text),
(344303,38256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kurt ..., o yüzden büyük bir kurt gibi sinsice ilerlemiyordu.'::text,'eskiden bir yavruydu'::text,'bir yavru olurdu'::text,'bir yavru olmaya alışkındı'::text,'Bu kurt eskiden bir yavruydu, o yüzden büyük bir kurt gibi sinsice ilerlemiyordu.'::text),
(344304,38256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a farkas ..., ezért nem lopakodott úgy, mint egy nagy farkas.'::text,'régen kölyök volt'::text,'kölyök lenne'::text,'hozzá volt szokva, hogy kölyök legyen'::text,'Ez a farkas régen kölyök volt, ezért nem lopakodott úgy, mint egy nagy farkas.'::text),
(344316,38258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wolf schleicht sich an die Küken heran, ...?'::text,'oder'::text,'oder'::text,'echt'::text,'Der Wolf schleicht sich an die Küken heran, oder?'::text),
(344320,38258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вовк підкрадається до курчат, ...?'::text,'так'::text,'так'::text,'справді'::text,'Вовк підкрадається до курчат, так?'::text),
(344319,38258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lobo se acerca sigilosamente a los pollitos, ¿...?'::text,'verdad'::text,'verdad'::text,'en serio'::text,'El lobo se acerca sigilosamente a los pollitos, ¿verdad?'::text),
(344318,38258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le loup s''approche des poussins en rampant, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'vraiment'::text,'Le loup s''approche des poussins en rampant, n''est-ce pas ?'::text),
(344321,38258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurt civcivlere doğru sinsice ilerliyor, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Kurt civcivlere doğru sinsice ilerliyor, değil mi?'::text),
(344322,38258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A farkas a csibék felé lopakodik, ...?'::text,'ugye'::text,'ugye'::text,'tényleg'::text,'A farkas a csibék felé lopakodik, ugye?'::text),
(344325,38259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schleichende Wolf wandte den Blick nicht von den Küken ab, und die Henne ...'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Der schleichende Wolf wandte den Blick nicht von den Küken ab, und die Henne auch nicht.'::text),
(344329,38259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вовк, що підкрадався, не відводив погляду від курчат, і ... курка.'::text,'не відводила й'::text,'відводила й'::text,'не була й'::text,'Вовк, що підкрадався, не відводив погляду від курчат, і не відводила й курка.'::text),
(344328,38259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lobo sigiloso no apartó la vista de los pollitos, y la gallina ...'::text,'tampoco'::text,'también'::text,'tampoco'::text,'El lobo sigiloso no apartó la vista de los pollitos, y la gallina tampoco.'::text),
(344327,38259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le loup rampant n''a pas quitté les poussins des yeux, et la poule ...'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Le loup rampant n''a pas quitté les poussins des yeux, et la poule non plus.'::text),
(344330,38259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinsice ilerleyen kurt gözünü civcivlerden ayırmadı, tavuk da ...'::text,'ayırmadı'::text,'ayırdı'::text,'değildi'::text,'Sinsice ilerleyen kurt gözünü civcivlerden ayırmadı, tavuk da ayırmadı.'::text),
(344331,38259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lopakodó farkas nem vette le a szemét a csibékről, és a tyúk ...'::text,'sem'::text,'is'::text,'sem'::text,'A lopakodó farkas nem vette le a szemét a csibékről, és a tyúk sem.'::text),
(339555,37729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verfolgungsjagd ... ungefähr eine Minute, bevor die Brücke nachgab.'::text,'hatte gedauert'::text,'hat gedauert'::text,'dauerte'::text,'Die Verfolgungsjagd hatte gedauert ungefähr eine Minute, bevor die Brücke nachgab.'::text),
(339559,37729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Погоня ... приблизно хвилину, перш ніж міст провалився.'::text,'тривала'::text,'тривала'::text,'тривала'::text,'Погоня тривала приблизно хвилину, перш ніж міст провалився.'::text),
(339558,37729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La persecución ... aproximadamente un minuto antes de que el puente cediera.'::text,'llevaba'::text,'lleva'::text,'duraba'::text,'La persecución llevaba aproximadamente un minuto antes de que el puente cediera.'::text),
(339557,37729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poursuite ... environ une minute avant que le pont ne cède.'::text,'avait duré'::text,'a duré'::text,'durait'::text,'La poursuite avait duré environ une minute avant que le pont ne cède.'::text),
(339560,37729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köprü çökmeden önce kovalamaca yaklaşık bir dakikadır ...'::text,'sürüyordu'::text,'sürüyor'::text,'sürüyordu'::text,'Köprü çökmeden önce kovalamaca yaklaşık bir dakikadır sürüyordu.'::text),
(339561,37729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üldözés körülbelül egy perce ..., amikor a híd leszakadt.'::text,'tartott'::text,'tart'::text,'tartott'::text,'Az üldözés körülbelül egy perce tartott, amikor a híd leszakadt.'::text),
(339564,37730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis das Weibchen die andere Seite erreicht, wird die Verfolgungsjagd endgültig ...'::text,'vorbei sein'::text,'enden'::text,'gerade enden'::text,'Bis das Weibchen die andere Seite erreicht, wird die Verfolgungsjagd endgültig vorbei sein.'::text),
(339568,37730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки самка дістанеться іншого боку, погоня ... остаточно.'::text,'закінчиться'::text,'закінчиться'::text,'закінчуватиметься'::text,'Поки самка дістанеться іншого боку, погоня закінчиться остаточно.'::text),
(339567,37730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la hembra llegue al otro lado, la persecución ... definitivamente.'::text,'habrá terminado'::text,'terminará'::text,'estará terminando'::text,'Para cuando la hembra llegue al otro lado, la persecución habrá terminado definitivamente.'::text),
(339566,37730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que la femelle atteigne l''autre côté, la poursuite ... pour de bon.'::text,'sera terminée'::text,'se terminera'::text,'sera en train de se terminer'::text,'D''ici à ce que la femelle atteigne l''autre côté, la poursuite sera terminée pour de bon.'::text),
(339569,37730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dişi karşı tarafa ulaştığında kovalamaca tamamen ...'::text,'bitmiş olacak'::text,'bitecek'::text,'bitiyor olacak'::text,'Dişi karşı tarafa ulaştığında kovalamaca tamamen bitmiş olacak.'::text),
(339570,37730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a nőstény átér a túloldalra, az üldözés végleg ...'::text,'véget ér'::text,'véget ér'::text,'éppen véget ér'::text,'Mire a nőstény átér a túloldalra, az üldözés végleg véget ér.'::text),
(339573,37731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Jagd die Brücke erreicht, wird der Wolf der Henne schon eine Stunde lang ...'::text,'gefolgt sein'::text,'folgen'::text,'folgen'::text,'Bis die Jagd die Brücke erreicht, wird der Wolf der Henne schon eine Stunde lang gefolgt sein.'::text),
(339577,37731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки погоня дістанеться мосту, вовк ... курку вже годину.'::text,'переслідуватиме'::text,'переслідуватиме'::text,'переслідуватиме'::text,'Поки погоня дістанеться мосту, вовк переслідуватиме курку вже годину.'::text),
(339576,37731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la persecución llegue al puente, el lobo ... a la gallina durante una hora.'::text,'habrá estado siguiendo'::text,'estará siguiendo'::text,'seguirá'::text,'Para cuando la persecución llegue al puente, el lobo habrá estado siguiendo a la gallina durante una hora.'::text),
(339575,37731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la poursuite atteindra le pont, le loup ... la poule depuis une heure.'::text,'aura suivi'::text,'suivra'::text,'suivra'::text,'Quand la poursuite atteindra le pont, le loup aura suivi la poule depuis une heure.'::text),
(339578,37731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovalamaca köprüye ulaştığında kurt bir saattir tavuğu ...'::text,'takip ediyor olacak'::text,'takip ediyor olacak'::text,'takip edecek'::text,'Kovalamaca köprüye ulaştığında kurt bir saattir tavuğu takip ediyor olacak.'::text),
(339579,37731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az üldözés eléri a hidat, a farkas már egy órája ... a tyúkot.'::text,'követi'::text,'követi majd'::text,'követi majd'::text,'Mire az üldözés eléri a hidat, a farkas már egy órája követi a tyúkot.'::text),
(339582,37732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wolf schneller gewesen wäre, ... die Verfolgungsjagd auf der Brücke geendet.'::text,'hätte'::text,'würde'::text,'endete'::text,'Wenn der Wolf schneller gewesen wäre, hätte die Verfolgungsjagd auf der Brücke geendet.'::text),
(339586,37732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вовк був швидшим, погоня ... на мосту.'::text,'закінчилася б'::text,'закінчилася б'::text,'закінчилася'::text,'Якби вовк був швидшим, погоня закінчилася б на мосту.'::text),
(339585,37732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el lobo hubiera sido más rápido, la persecución ... en el puente.'::text,'habría terminado'::text,'terminaría'::text,'terminó'::text,'Si el lobo hubiera sido más rápido, la persecución habría terminado en el puente.'::text),
(339584,37732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le loup avait été plus rapide, la poursuite ... sur le pont.'::text,'se serait terminée'::text,'se terminerait'::text,'s''est terminée'::text,'Si le loup avait été plus rapide, la poursuite se serait terminée sur le pont.'::text),
(339587,37732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurt daha hızlı olsaydı, kovalamaca köprüde ...'::text,'bitmiş olurdu'::text,'biterdi'::text,'bitti'::text,'Kurt daha hızlı olsaydı, kovalamaca köprüde bitmiş olurdu.'::text),
(339588,37732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a farkas gyorsabb lett volna, az üldözés a hídon ...'::text,'ért volna véget'::text,'érne véget'::text,'ért véget'::text,'Ha a farkas gyorsabb lett volna, az üldözés a hídon ért volna véget.'::text),
(339591,37733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Brücke nicht gebrochen wäre, ... die Verfolgungsjagd jetzt noch im Gange.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Wenn die Brücke nicht gebrochen wäre, wäre die Verfolgungsjagd jetzt noch im Gange.'::text),
(339595,37733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби міст не зламався, погоня ... і зараз.'::text,'тривала б'::text,'тривала б'::text,'триватиме'::text,'Якби міст не зламався, погоня тривала б і зараз.'::text),
(339594,37733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el puente no se hubiera roto, la persecución ... en marcha ahora mismo.'::text,'seguiría'::text,'habría seguido'::text,'seguirá'::text,'Si el puente no se hubiera roto, la persecución seguiría en marcha ahora mismo.'::text),
(339593,37733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le pont ne s''était pas cassé, la poursuite ... encore en cours maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si le pont ne s''était pas cassé, la poursuite serait encore en cours maintenant.'::text),
(339596,37733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köprü kırılmasaydı, kovalamaca şu an hâlâ ...'::text,'sürüyor olurdu'::text,'sürmüş olurdu'::text,'sürecek'::text,'Köprü kırılmasaydı, kovalamaca şu an hâlâ sürüyor olurdu.'::text),
(339597,37733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a híd nem szakadt volna le, az üldözés most is ...'::text,'tartana'::text,'tartott volna'::text,'tartani fog'::text,'Ha a híd nem szakadt volna le, az üldözés most is tartana.'::text),
(339600,37734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verfolgungsjagd soll im Morgengrauen ..., als der Wolf die Henne zum ersten Mal sah.'::text,'begonnen haben'::text,'beginnen'::text,'beginnend'::text,'Die Verfolgungsjagd soll im Morgengrauen begonnen haben, als der Wolf die Henne zum ersten Mal sah.'::text),
(339604,37734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що погоня ... на світанку, коли вовк уперше побачив курку.'::text,'почалася'::text,'починається'::text,'початок'::text,'Кажуть, що погоня почалася на світанку, коли вовк уперше побачив курку.'::text),
(339603,37734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la persecución ... al amanecer, cuando el lobo vio por primera vez a la gallina.'::text,'empezó'::text,'empieza'::text,'empezando'::text,'Se dice que la persecución empezó al amanecer, cuando el lobo vio por primera vez a la gallina.'::text),
(339602,37734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que la poursuite ... à l''aube, quand le loup a vu la poule pour la première fois.'::text,'a commencé'::text,'commence'::text,'commençant'::text,'On dit que la poursuite a commencé à l''aube, quand le loup a vu la poule pour la première fois.'::text),
(339605,37734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovalamacanın, kurt tavuğu ilk gördüğünde, şafakta ... söyleniyor.'::text,'başladığı'::text,'başlayacağı'::text,'başlaması'::text,'Kovalamacanın, kurt tavuğu ilk gördüğünde, şafakta başladığı söyleniyor.'::text),
(339606,37734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag az üldözés hajnalban ..., amikor a farkas először meglátta a tyúkot.'::text,'kezdődött'::text,'kezdődik'::text,'kezdődve'::text,'Állítólag az üldözés hajnalban kezdődött, amikor a farkas először meglátta a tyúkot.'::text),
(339609,37735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne beschuldigte den Wolf, die Verfolgungsjagd ... zu haben. Ein leicht ungeplanter Morgenspaziergang.'::text,'begonnen'::text,'beginnen'::text,'begann'::text,'Die Henne beschuldigte den Wolf, die Verfolgungsjagd begonnen zu haben. Ein leicht ungeplanter Morgenspaziergang.'::text),
(339613,37735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка звинуватила вовка в тому, що він ... погоню. Трохи незапланована ранкова прогулянка.'::text,'почав'::text,'почати'::text,'почав'::text,'Курка звинуватила вовка в тому, що він почав погоню. Трохи незапланована ранкова прогулянка.'::text),
(339612,37735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina acusó al lobo de ... la persecución. Un paseo matutino ligeramente improvisado.'::text,'empezar'::text,'empezar'::text,'empezó'::text,'La gallina acusó al lobo de empezar la persecución. Un paseo matutino ligeramente improvisado.'::text),
(339611,37735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule a accusé le loup de ... la poursuite. Une balade matinale légèrement imprévue.'::text,'avoir lancé'::text,'lancer'::text,'a lancé'::text,'La poule a accusé le loup de avoir lancé la poursuite. Une balade matinale légèrement imprévue.'::text),
(339614,37735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk, kovalamacayı ... için kurdu suçladı. Biraz plansız bir sabah yürüyüşü.'::text,'başlattığı'::text,'başlatmak'::text,'başlattı'::text,'Tavuk, kovalamacayı başlattığı için kurdu suçladı. Biraz plansız bir sabah yürüyüşü.'::text),
(339615,37735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk azzal vádolta a farkast, hogy ... az üldözést. Kicsit nem tervezett reggeli séta.'::text,'elkezdte'::text,'elkezdeni'::text,'elkezdte'::text,'A tyúk azzal vádolta a farkast, hogy elkezdte az üldözést. Kicsit nem tervezett reggeli séta.'::text),
(339627,37737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaum ... begonnen, als die Brücke unter dem Wolf nachgab.'::text,'hatte die Jagd'::text,'die Jagd hatte'::text,'hat die Jagd'::text,'Kaum hatte die Jagd begonnen, als die Brücke unter dem Wolf nachgab.'::text),
(339631,37737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно ... почалася, як міст під вовком провалився.'::text,'погоня'::text,'погоня'::text,'погоня'::text,'Щойно погоня почалася, як міст під вовком провалився.'::text),
(339630,37737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apenas ... cuando el puente cedió bajo el lobo.'::text,'había empezado la persecución'::text,'la persecución había empezado'::text,'empezó la persecución'::text,'Apenas había empezado la persecución cuando el puente cedió bajo el lobo.'::text),
(339629,37737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À peine ... commencé que le pont a cédé sous le loup.'::text,'la poursuite avait-elle'::text,'la poursuite avait'::text,'la poursuite a-t-elle'::text,'À peine la poursuite avait-elle commencé que le pont a cédé sous le loup.'::text),
(339632,37737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... başlamıştı ki köprü kurdun altında çöktü.'::text,'Kovalamaca daha yeni'::text,'Kovalamaca daha yeni'::text,'Kovalamaca daha yeni'::text,'Kovalamaca daha yeni başlamıştı ki köprü kurdun altında çöktü.'::text),
(339633,37737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alig ... el, amikor a híd leszakadt a farkas alatt.'::text,'kezdődött az üldözés'::text,'az üldözés kezdődött'::text,'kezdődött az üldözés'::text,'Alig kezdődött az üldözés el, amikor a híd leszakadt a farkas alatt.'::text),
(339636,37738,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Verfolgungsjagd brachte die Henne ihre Küken dazu, sich an ihren Flügeln gut ...'::text,'festzuhalten'::text,'festhalten'::text,'festgehalten'::text,'Während der Verfolgungsjagd brachte die Henne ihre Küken dazu, sich an ihren Flügeln gut festzuhalten.'::text),
(339640,37738,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час погоні курка змусила курчат міцно ... за її крила.'::text,'триматися'::text,'триматися'::text,'трималися'::text,'Під час погоні курка змусила курчат міцно триматися за її крила.'::text),
(339639,37738,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Durante la persecución, la gallina hizo que sus pollitos ... fuerte a sus alas.'::text,'se agarraran'::text,'se agarraran'::text,'agarrados'::text,'Durante la persecución, la gallina hizo que sus pollitos se agarraran fuerte a sus alas.'::text),
(339638,37738,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant la poursuite, la poule a fait en sorte que ses poussins ... fermement à ses ailes.'::text,'s''accrochent'::text,'s''accrochent'::text,'accrochés'::text,'Pendant la poursuite, la poule a fait en sorte que ses poussins s''accrochent fermement à ses ailes.'::text),
(339641,37738,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovalamaca sırasında tavuk, civcivlerinin kanatlarına sıkıca ... sağladı.'::text,'tutunmasını'::text,'tutunmasını'::text,'tutunmuş'::text,'Kovalamaca sırasında tavuk, civcivlerinin kanatlarına sıkıca tutunmasını sağladı.'::text),
(339642,37738,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üldözés alatt a tyúk elérte, hogy a csibéi szorosan ... a szárnyaiba.'::text,'kapaszkodjanak'::text,'kapaszkodjanak'::text,'kapaszkodtak'::text,'Az üldözés alatt a tyúk elérte, hogy a csibéi szorosan kapaszkodjanak a szárnyaiba.'::text),
(339645,37739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne wünscht sich vermutlich, dass die Verfolgungsjagd auf festem Boden statt auf einer Brücke ...'::text,'stattgefunden hätte'::text,'stattfand'::text,'stattfinden würde'::text,'Die Henne wünscht sich vermutlich, dass die Verfolgungsjagd auf festem Boden statt auf einer Brücke stattgefunden hätte.'::text),
(339649,37739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка, імовірно, хотіла б, щоб погоня ... на твердій землі, а не на мосту.'::text,'відбулася'::text,'відбулася'::text,'відбувалася'::text,'Курка, імовірно, хотіла б, щоб погоня відбулася на твердій землі, а не на мосту.'::text),
(339648,37739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina probablemente desearía que la persecución ... en tierra firme y no en un puente.'::text,'hubiera tenido lugar'::text,'tuviera lugar'::text,'tendría lugar'::text,'La gallina probablemente desearía que la persecución hubiera tenido lugar en tierra firme y no en un puente.'::text),
(339647,37739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule souhaiterait probablement que la poursuite ... sur la terre ferme plutôt que sur un pont.'::text,'ait eu lieu'::text,'ait lieu'::text,'aurait lieu'::text,'La poule souhaiterait probablement que la poursuite ait eu lieu sur la terre ferme plutôt que sur un pont.'::text),
(339650,37739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk muhtemelen kovalamacanın köprü yerine sağlam zeminde ... ister.'::text,'yaşanmış olmasını'::text,'yaşanmasını'::text,'yaşanacak olmasını'::text,'Tavuk muhtemelen kovalamacanın köprü yerine sağlam zeminde yaşanmış olmasını ister.'::text),
(339651,37739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk feltehetően azt kívánja, bárcsak az üldözés szilárd talajon ..., nem pedig egy hídon.'::text,'zajlott volna'::text,'zajlana'::text,'zajlana majd'::text,'A tyúk feltehetően azt kívánja, bárcsak az üldözés szilárd talajon zajlott volna, nem pedig egy hídon.'::text),
(345945,38439,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... ihre Küken, als der Fuchs näher kam, also war der Fuchs nah.'::text,'verteidigte'::text,'verteidigte'::text,'hat verteidigt'::text,'Die Henne verteidigte ihre Küken, als der Fuchs näher kam, also war der Fuchs nah.'::text),
(345949,38439,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка ... своїх курчат, коли лисиця підійшла ближче, тож лисиця була близько.'::text,'захищала'::text,'захистила'::text,'захистила'::text,'Курка захищала своїх курчат, коли лисиця підійшла ближче, тож лисиця була близько.'::text),
(345948,38439,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... a sus pollitos cuando el zorro se acercó, así que el zorro estaba cerca.'::text,'estaba defendiendo'::text,'defendió'::text,'ha defendido'::text,'La gallina estaba defendiendo a sus pollitos cuando el zorro se acercó, así que el zorro estaba cerca.'::text),
(345947,38439,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... ses poussins quand le renard s''est approché, donc le renard était proche.'::text,'défendait'::text,'défendit'::text,'a défendu'::text,'La poule défendait ses poussins quand le renard s''est approché, donc le renard était proche.'::text),
(345950,38439,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tilki yaklaştığında tavuk civcivlerini ..., yani tilki yakındaydı.'::text,'koruyordu'::text,'korudu'::text,'korumuş'::text,'Tilki yaklaştığında tavuk civcivlerini koruyordu, yani tilki yakındaydı.'::text),
(345951,38439,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk éppen ... a csibéit, amikor a róka közelebb jött, szóval a róka közel volt.'::text,'védte'::text,'megvédte'::text,'megvédte'::text,'A tyúk éppen védte a csibéit, amikor a róka közelebb jött, szóval a róka közel volt.'::text),
(345963,38441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... die Henne gegen die Flammen und hat dann ihre Küken auch noch vor einem Fuchs verteidigt.'::text,'kämpfte'::text,'kämpfte gerade'::text,'hat gekämpft'::text,'Hör mal, angeblich kämpfte die Henne gegen die Flammen und hat dann ihre Küken auch noch vor einem Fuchs verteidigt.'::text),
(345967,38441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, курка ... з полум''ям, а потім ще й захистила курчат від лисиці.'::text,'поборолася'::text,'боролася'::text,'поборолася'::text,'Слухай, кажуть, курка поборолася з полум''ям, а потім ще й захистила курчат від лисиці.'::text),
(345966,38441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la gallina ... contra las llamas y luego defendió a sus pollitos de un zorro también.'::text,'luchó'::text,'estaba luchando'::text,'ha luchado'::text,'Oye, al parecer la gallina luchó contra las llamas y luego defendió a sus pollitos de un zorro también.'::text),
(345965,38441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la poule ... contre les flammes et puis elle a aussi défendu ses poussins contre un renard.'::text,'s''est battue'::text,'se battait'::text,'s''est battue'::text,'Écoute, apparemment la poule s''est battue contre les flammes et puis elle a aussi défendu ses poussins contre un renard.'::text),
(345968,38441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya tavuk alevlerle ... ve sonra civcivlerini bir tilkiden de korumuş.'::text,'savaşmış'::text,'savaşıyormuş'::text,'savaşmış'::text,'Dinle, güya tavuk alevlerle savaşmış ve sonra civcivlerini bir tilkiden de korumuş.'::text),
(345969,38441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a tyúk ... a lángokkal, aztán még egy rókától is megvédte a csibéit.'::text,'megküzdött'::text,'küzdött'::text,'megküzdött'::text,'Figyelj, állítólag a tyúk megküzdött a lángokkal, aztán még egy rókától is megvédte a csibéit.'::text),
(345972,38442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich hab gehört, dass diese Henne ihre Küken diese Woche zweimal ...'::text,'verteidigt hat'::text,'verteidigt hat'::text,'verteidigt'::text,'Also, ich hab gehört, dass diese Henne ihre Küken diese Woche zweimal verteidigt hat.'::text),
(345976,38442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, я чула, що ця курка цього тижня двічі ... своїх курчат.'::text,'захистила'::text,'захищала'::text,'захищає'::text,'Отже, я чула, що ця курка цього тижня двічі захистила своїх курчат.'::text),
(345975,38442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, me enteré de que esta gallina ... a sus pollitos dos veces esta semana.'::text,'ha defendido'::text,'ha estado defendiendo'::text,'defiende'::text,'Bueno, me enteré de que esta gallina ha defendido a sus pollitos dos veces esta semana.'::text),
(345974,38442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire que cette poule ... ses poussins deux fois cette semaine.'::text,'a défendu'::text,'défend'::text,'défend'::text,'Bon, j''ai entendu dire que cette poule a défendu ses poussins deux fois cette semaine.'::text),
(345977,38442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki bu tavuk bu hafta civcivlerini iki kez ...'::text,'korumuş'::text,'koruyormuş'::text,'korur'::text,'Tamam, duydum ki bu tavuk bu hafta civcivlerini iki kez korumuş.'::text),
(345978,38442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na szóval, azt hallottam, hogy ez a tyúk a héten kétszer ... a csibéit.'::text,'megvédte'::text,'védte'::text,'védi'::text,'Na szóval, azt hallottam, hogy ez a tyúk a héten kétszer megvédte a csibéit.'::text),
(345981,38443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Fuchs kam, ... die Henne ihre Küken schon vor einem Feuer verteidigt. Nichts Wildes.'::text,'hatte'::text,'hat'::text,'verteidigt'::text,'Als der Fuchs kam, hatte die Henne ihre Küken schon vor einem Feuer verteidigt. Nichts Wildes.'::text),
(345985,38443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки прийшла лисиця, курка вже ... своїх курчат від вогню. Нічого особливого.'::text,'захистила'::text,'захистила'::text,'захищає'::text,'Поки прийшла лисиця, курка вже захистила своїх курчат від вогню. Нічого особливого.'::text),
(345984,38443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegó el zorro, la gallina ya ... a sus pollitos de un incendio. Nada del otro mundo.'::text,'había defendido'::text,'ha defendido'::text,'defiende'::text,'Cuando llegó el zorro, la gallina ya había defendido a sus pollitos de un incendio. Nada del otro mundo.'::text),
(345983,38443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le renard est arrivé, la poule ... ses poussins d''un incendie. Rien de bien méchant.'::text,'avait déjà défendu'::text,'a déjà défendu'::text,'défend'::text,'Quand le renard est arrivé, la poule avait déjà défendu ses poussins d''un incendie. Rien de bien méchant.'::text),
(345986,38443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tilki geldiğinde tavuk civcivlerini bir yangından ... bile. Önemli bir şey değil.'::text,'korumuştu'::text,'korudu'::text,'korur'::text,'Tilki geldiğinde tavuk civcivlerini bir yangından korumuştu bile. Önemli bir şey değil.'::text),
(345987,38443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a róka megjött, a tyúk már ... a csibéit egy tűztől. Semmi különös.'::text,'megvédte'::text,'megvédte'::text,'védi'::text,'Mire a róka megjött, a tyúk már megvédte a csibéit egy tűztől. Semmi különös.'::text),
(345999,38445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne verteidigte ihre Küken, ... der Fuchs viel größer war als sie.'::text,'obwohl'::text,'trotz'::text,'es sei denn'::text,'Die Henne verteidigte ihre Küken, obwohl der Fuchs viel größer war als sie.'::text),
(346003,38445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка захистила своїх курчат, ... лисиця була набагато більшою за неї.'::text,'хоча'::text,'попри'::text,'хіба що'::text,'Курка захистила своїх курчат, хоча лисиця була набагато більшою за неї.'::text),
(346002,38445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina defendió a sus pollitos, ... el zorro era mucho más grande que ella.'::text,'aunque'::text,'a pesar de'::text,'a menos que'::text,'La gallina defendió a sus pollitos, aunque el zorro era mucho más grande que ella.'::text),
(346001,38445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule a défendu ses poussins ... le renard était beaucoup plus grand qu''elle.'::text,'même si'::text,'malgré'::text,'à moins que'::text,'La poule a défendu ses poussins même si le renard était beaucoup plus grand qu''elle.'::text),
(346004,38445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tilki kendisinden çok daha büyük ... tavuk civcivlerini korudu.'::text,'olmasına rağmen'::text,'rağmen'::text,'olmadıkça'::text,'Tilki kendisinden çok daha büyük olmasına rağmen tavuk civcivlerini korudu.'::text),
(346005,38445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk megvédte a csibéit, ... a róka sokkal nagyobb volt nála.'::text,'noha'::text,'ellenére'::text,'hacsak nem'::text,'A tyúk megvédte a csibéit, noha a róka sokkal nagyobb volt nála.'::text),
(346008,38446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Küken wussten, dass ihre Mutter sie vor dem Fuchs ...'::text,'verteidigen würde'::text,'verteidigen wird'::text,'verteidigt'::text,'Die Küken wussten, dass ihre Mutter sie vor dem Fuchs verteidigen würde.'::text),
(346012,38446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курчата знали, що мама ... їх від лисиці.'::text,'захистить'::text,'захистить'::text,'захищає'::text,'Курчата знали, що мама захистить їх від лисиці.'::text),
(346011,38446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los pollitos sabían que su madre los ... del zorro.'::text,'defendería'::text,'defenderá'::text,'defiende'::text,'Los pollitos sabían que su madre los defendería del zorro.'::text),
(346010,38446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les poussins savaient que leur mère les ... contre le renard.'::text,'défendrait'::text,'défendra'::text,'défend'::text,'Les poussins savaient que leur mère les défendrait contre le renard.'::text),
(346013,38446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civcivler annelerinin onları tilkiden ... biliyordu.'::text,'koruyacağını'::text,'koruyacağını'::text,'koruduğunu'::text,'Civcivler annelerinin onları tilkiden koruyacağını biliyordu.'::text),
(346014,38446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibék tudták, hogy az anyjuk ... őket a rókától.'::text,'megvédi'::text,'megvédi'::text,'védi'::text,'A csibék tudták, hogy az anyjuk megvédi őket a rókától.'::text),
(346017,38447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... die Henne ihre Küken mit weit ausgebreiteten Flügeln.'::text,'verteidigt'::text,'verteidigt'::text,'hat verteidigt'::text,'In diesem Moment verteidigt die Henne ihre Küken mit weit ausgebreiteten Flügeln.'::text),
(346021,38447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цієї миті курка ... своїх курчат широко розправленими крилами.'::text,'захищає'::text,'захищає'::text,'захистила'::text,'Цієї миті курка захищає своїх курчат широко розправленими крилами.'::text),
(346020,38447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, la gallina ... a sus pollitos con las alas bien abiertas.'::text,'está defendiendo'::text,'defiende'::text,'ha defendido'::text,'En este momento, la gallina está defendiendo a sus pollitos con las alas bien abiertas.'::text),
(346019,38447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la poule ... ses poussins, les ailes grandes ouvertes.'::text,'défend'::text,'défend'::text,'a défendu'::text,'En ce moment, la poule défend ses poussins, les ailes grandes ouvertes.'::text),
(346022,38447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda tavuk kanatlarını iyice açmış hâlde civcivlerini ...'::text,'koruyor'::text,'korur'::text,'korudu'::text,'Şu anda tavuk kanatlarını iyice açmış hâlde civcivlerini koruyor.'::text),
(346023,38447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban a tyúk szélesre tárt szárnyakkal ... a csibéit.'::text,'védi'::text,'védi'::text,'megvédte'::text,'Ebben a pillanatban a tyúk szélesre tárt szárnyakkal védi a csibéit.'::text),
(346026,38448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fuchs ... sich mehrere Minuten lang näher, bevor das Weibchen eingriff, um ihre Küken zu verteidigen.'::text,'schlich'::text,'schleicht'::text,'schleicht'::text,'Der Fuchs schlich sich mehrere Minuten lang näher, bevor das Weibchen eingriff, um ihre Küken zu verteidigen.'::text),
(346030,38448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лисиця ... ближче кілька хвилин, перш ніж самка втрутилася, щоб захистити курчат.'::text,'підкрадалася'::text,'підкрадалася'::text,'підкрадається'::text,'Лисиця підкрадалася ближче кілька хвилин, перш ніж самка втрутилася, щоб захистити курчат.'::text),
(346029,38448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El zorro ... durante varios minutos antes de que la hembra interviniera para defender a sus pollitos.'::text,'se había estado acercando'::text,'se ha estado acercando'::text,'se está acercando'::text,'El zorro se había estado acercando durante varios minutos antes de que la hembra interviniera para defender a sus pollitos.'::text),
(346028,38448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le renard ... depuis plusieurs minutes quand la femelle est intervenue pour défendre ses poussins.'::text,'s''approchait à pas de loup'::text,'s''approche à pas de loup'::text,'s''approche à pas de loup'::text,'Le renard s''approchait à pas de loup depuis plusieurs minutes quand la femelle est intervenue pour défendre ses poussins.'::text),
(346031,38448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dişi civcivlerini korumak için araya girmeden önce tilki birkaç dakikadır sinsice ...'::text,'yaklaşıyordu'::text,'yaklaşıyor'::text,'yaklaşıyor'::text,'Dişi civcivlerini korumak için araya girmeden önce tilki birkaç dakikadır sinsice yaklaşıyordu.'::text),
(346032,38448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A róka már percek óta ... közelebb, mielőtt a nőstény közbelépett, hogy megvédje a csibéit.'::text,'lopakodott'::text,'lopakodik'::text,'lopakodik'::text,'A róka már percek óta lopakodott közelebb, mielőtt a nőstény közbelépett, hogy megvédje a csibéit.'::text),
(346035,38449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum nächsten Frühling sind die Küken ..., also wird das Weibchen sie nicht mehr verteidigen.'::text,'herangewachsen'::text,'wachsen'::text,'wachsen'::text,'Bis zum nächsten Frühling sind die Küken herangewachsen, also wird das Weibchen sie nicht mehr verteidigen.'::text),
(346039,38449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступної весни курчата ..., тож самка вже не захищатиме їх.'::text,'виростуть'::text,'виростуть'::text,'ростуть'::text,'До наступної весни курчата виростуть, тож самка вже не захищатиме їх.'::text),
(346038,38449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la próxima primavera, los pollitos ..., así que la hembra ya no los defenderá.'::text,'habrán crecido'::text,'crecerán'::text,'crecen'::text,'Para la próxima primavera, los pollitos habrán crecido, así que la hembra ya no los defenderá.'::text),
(346037,38449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le printemps prochain, les poussins ..., donc la femelle ne les défendra plus.'::text,'auront grandi'::text,'grandiront'::text,'grandissent'::text,'D''ici le printemps prochain, les poussins auront grandi, donc la femelle ne les défendra plus.'::text),
(346040,38449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek bahara kadar civcivler ..., bu yüzden dişi artık onları korumayacak.'::text,'büyümüş olacak'::text,'büyüyecek'::text,'büyür'::text,'Gelecek bahara kadar civcivler büyümüş olacak, bu yüzden dişi artık onları korumayacak.'::text),
(346041,38449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő tavaszra a csibék ..., így a nőstény már nem fogja védeni őket.'::text,'felnőnek'::text,'felnőnek'::text,'nőnek'::text,'Jövő tavaszra a csibék felnőnek, így a nőstény már nem fogja védeni őket.'::text),
(388875,43209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, angeblich ... sich diese Henne den ganzen Winter an schlafenden Wölfen vorbei.'::text,'schleicht'::text,'schleicht'::text,'schleicht'::text,'Warte, angeblich schleicht sich diese Henne den ganzen Winter an schlafenden Wölfen vorbei.'::text),
(388879,43209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, кажуть, та курка всю зиму ... повз сплячих вовків.'::text,'прокрадається'::text,'прокрадається'::text,'прокрадається'::text,'Стривай, кажуть, та курка всю зиму прокрадається повз сплячих вовків.'::text),
(388878,43209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer esa gallina ... a escondidas junto a lobos dormidos todo el invierno.'::text,'lleva pasando'::text,'está pasando'::text,'pasa'::text,'Espera, al parecer esa gallina lleva pasando a escondidas junto a lobos dormidos todo el invierno.'::text),
(388877,43209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment cette poule ... en douce devant des loups endormis depuis le début de l''hiver.'::text,'passe'::text,'passe'::text,'passe'::text,'Attends, apparemment cette poule passe en douce devant des loups endormis depuis le début de l''hiver.'::text),
(388880,43209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, güya o tavuk bütün kış uyuyan kurtların yanından gizlice ...'::text,'geçiyormuş'::text,'geçiyormuş'::text,'geçermiş'::text,'Dur, güya o tavuk bütün kış uyuyan kurtların yanından gizlice geçiyormuş.'::text),
(388881,43209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag az a tyúk egész télen ... az alvó farkasok mellett.'::text,'oson el'::text,'oson el'::text,'elosonik'::text,'Várj, állítólag az a tyúk egész télen oson el az alvó farkasok mellett.'::text),
(388884,43210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... sie sich gerade an den Wölfen vorbei, als einer die Augen öffnete.'::text,'schlich'::text,'schlich'::text,'ist geschlichen'::text,'Hör mal, angeblich schlich sie sich gerade an den Wölfen vorbei, als einer die Augen öffnete.'::text),
(388888,43210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... повз вовків, коли один розплющив очі.'::text,'прокрадалася'::text,'прокралася'::text,'прокралася'::text,'Слухай, кажуть, вона прокрадалася повз вовків, коли один розплющив очі.'::text),
(388887,43210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ella ... a escondidas junto a los lobos cuando uno abrió los ojos.'::text,'pasaba'::text,'pasó'::text,'ha pasado'::text,'Oye, al parecer ella pasaba a escondidas junto a los lobos cuando uno abrió los ojos.'::text),
(388886,43210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... en douce devant les loups quand l''un d''eux a ouvert les yeux.'::text,'passait'::text,'est passée'::text,'est passée'::text,'Écoute, apparemment elle passait en douce devant les loups quand l''un d''eux a ouvert les yeux.'::text),
(388889,43210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya kurtlardan biri gözlerini açtığında o yanlarından gizlice ...'::text,'geçiyormuş'::text,'geçmiş'::text,'geçmiş'::text,'Dinle, güya kurtlardan biri gözlerini açtığında o yanlarından gizlice geçiyormuş.'::text),
(388890,43210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag éppen ... a farkasok mellett, amikor az egyik kinyitotta a szemét.'::text,'osont el'::text,'elosont'::text,'elosont'::text,'Figyelj, állítólag éppen osont el a farkasok mellett, amikor az egyik kinyitotta a szemét.'::text),
(388893,43211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... sich schon zweimal an diesen Wölfen vorbei. Ganz klar ein entspannter Morgen.'::text,'schlich'::text,'schlich'::text,'schlich'::text,'Die Henne schlich sich schon zweimal an diesen Wölfen vorbei. Ganz klar ein entspannter Morgen.'::text),
(388897,43211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка вже двічі ... повз цих вовків. Явно розслаблений ранок.'::text,'прокралася'::text,'прокрадалася'::text,'прокралася'::text,'Курка вже двічі прокралася повз цих вовків. Явно розслаблений ранок.'::text),
(388896,43211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ya ... a escondidas junto a estos lobos dos veces. Claramente, una mañana relajante.'::text,'ha pasado'::text,'ha estado pasando'::text,'pasó'::text,'La gallina ya ha pasado a escondidas junto a estos lobos dos veces. Claramente, una mañana relajante.'::text),
(388895,43211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... déjà deux fois en douce devant ces loups. Clairement une matinée relax.'::text,'est passée'::text,'est passée'::text,'passa'::text,'La poule est passée déjà deux fois en douce devant ces loups. Clairement une matinée relax.'::text),
(388898,43211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk bu kurtların yanından iki kez gizlice ... bile. Belli ki rahatlatıcı bir sabah.'::text,'geçti'::text,'geçiyordu'::text,'geçti'::text,'Tavuk bu kurtların yanından iki kez gizlice geçti bile. Belli ki rahatlatıcı bir sabah.'::text),
(388899,43211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk már kétszer ... el ezek mellett a farkasok mellett. Nyilván egy pihentető reggel.'::text,'osont'::text,'osont'::text,'osont'::text,'A tyúk már kétszer osont el ezek mellett a farkasok mellett. Nyilván egy pihentető reggel.'::text),
(388902,43212,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Wölfe aufwachten, ... sich die Henne schon in den Schnee geschlichen. Makellose Planung, offensichtlich.'::text,'hatte'::text,'hat'::text,'schleicht'::text,'Als die Wölfe aufwachten, hatte sich die Henne schon in den Schnee geschlichen. Makellose Planung, offensichtlich.'::text),
(388906,43212,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вовки прокинулися, курка вже ... в сніг. Бездоганне планування, очевидно.'::text,'прокралася'::text,'прокралася'::text,'прокрадається'::text,'Поки вовки прокинулися, курка вже прокралася в сніг. Бездоганне планування, очевидно.'::text),
(388905,43212,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando los lobos se despertaron, la gallina ya ... en la nieve. Una planificación impecable, obviamente.'::text,'se había escabullido'::text,'se ha escabullido'::text,'se escabulle'::text,'Cuando los lobos se despertaron, la gallina ya se había escabullido en la nieve. Una planificación impecable, obviamente.'::text),
(388904,43212,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les loups se sont réveillés, la poule ... déjà dans la neige. Planification impeccable, évidemment.'::text,'s''était glissée'::text,'s''est glissée'::text,'se glisse'::text,'Quand les loups se sont réveillés, la poule s''était glissée déjà dans la neige. Planification impeccable, évidemment.'::text),
(388907,43212,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurtlar uyandığında tavuk çoktan karın içine ... bile. Kusursuz bir planlama, belli ki.'::text,'süzülmüştü'::text,'süzüldü'::text,'süzülür'::text,'Kurtlar uyandığında tavuk çoktan karın içine süzülmüştü bile. Kusursuz bir planlama, belli ki.'::text),
(388908,43212,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a farkasok felébredtek, a tyúk már ... a hóba. Hibátlan tervezés, nyilvánvalóan.'::text,'besurrant'::text,'besurrant'::text,'besurran'::text,'Mire a farkasok felébredtek, a tyúk már besurrant a hóba. Hibátlan tervezés, nyilvánvalóan.'::text),
(388920,43214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ist überzeugt, dass sie sich heil an den schlafenden Wölfen ...'::text,'vorbeischleichen wird'::text,'vorbeischleichen wird'::text,'vorbeischlich'::text,'Die Henne ist überzeugt, dass sie sich heil an den schlafenden Wölfen vorbeischleichen wird.'::text),
(388924,43214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка впевнена, що вона безпечно ... повз сплячих вовків.'::text,'прокрадеться'::text,'прокрадатиметься'::text,'прокралася'::text,'Курка впевнена, що вона безпечно прокрадеться повз сплячих вовків.'::text),
(388923,43214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina está segura de que ... a escondidas junto a los lobos dormidos sin peligro.'::text,'pasará'::text,'estará pasando'::text,'pasó'::text,'La gallina está segura de que pasará a escondidas junto a los lobos dormidos sin peligro.'::text),
(388922,43214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule est sûre qu''elle ... en douce devant les loups endormis sans danger.'::text,'passera'::text,'sera en train de passer'::text,'est passée'::text,'La poule est sûre qu''elle passera en douce devant les loups endormis sans danger.'::text),
(388925,43214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk, uyuyan kurtların yanından güvenle gizlice ... emin.'::text,'geçeceğinden'::text,'geçiyor olacağından'::text,'geçtiğinden'::text,'Tavuk, uyuyan kurtların yanından güvenle gizlice geçeceğinden emin.'::text),
(388926,43214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk biztos benne, hogy épségben ... az alvó farkasok mellett.'::text,'elsurran'::text,'el fog surranni'::text,'elsurrant'::text,'A tyúk biztos benne, hogy épségben elsurran az alvó farkasok mellett.'::text),
(388929,43215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Tier durch weichen Schnee schleicht, ... es sehr wenig Lärm.'::text,'macht'::text,'machte'::text,'wird machen'::text,'Wenn ein Tier durch weichen Schnee schleicht, macht es sehr wenig Lärm.'::text),
(388933,43215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли тварина прокрадається м''яким снігом, вона ... дуже мало шуму.'::text,'робить'::text,'робила'::text,'робитиме'::text,'Коли тварина прокрадається м''яким снігом, вона робить дуже мало шуму.'::text),
(388932,43215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando un animal se desliza sigilosamente por la nieve blanda, ... muy poco ruido.'::text,'hace'::text,'hizo'::text,'hará'::text,'Cuando un animal se desliza sigilosamente por la nieve blanda, hace muy poco ruido.'::text),
(388931,43215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand un animal se faufile dans la neige molle, il ... très peu de bruit.'::text,'fait'::text,'a fait'::text,'fera'::text,'Quand un animal se faufile dans la neige molle, il fait très peu de bruit.'::text),
(388934,43215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir hayvan yumuşak karda gizlice ilerlediğinde çok az ses ...'::text,'çıkarır'::text,'çıkardı'::text,'çıkaracak'::text,'Bir hayvan yumuşak karda gizlice ilerlediğinde çok az ses çıkarır.'::text),
(388935,43215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor egy állat a puha hóban oson, nagyon kevés zajt ...'::text,'csap'::text,'csapott'::text,'fog csapni'::text,'Amikor egy állat a puha hóban oson, nagyon kevés zajt csap.'::text),
(388938,43216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich die Henne noch näher heranschleicht, ...'::text,'wachen die Wölfe auf'::text,'würden die Wölfe aufwachen'::text,'wachten die Wölfe auf'::text,'Wenn sich die Henne noch näher heranschleicht, wachen die Wölfe auf.'::text),
(388942,43216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо курка підкрадеться ще ближче, вовки ...'::text,'прокинуться'::text,'прокинулися б'::text,'прокинулися'::text,'Якщо курка підкрадеться ще ближче, вовки прокинуться.'::text),
(388941,43216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gallina se acerca un poco más, los lobos ...'::text,'se despertarán'::text,'se despertarían'::text,'se despertaron'::text,'Si la gallina se acerca un poco más, los lobos se despertarán.'::text),
(388940,43216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la poule s''approche encore, les loups ...'::text,'se réveilleront'::text,'se réveilleraient'::text,'se sont réveillés'::text,'Si la poule s''approche encore, les loups se réveilleront.'::text),
(388943,43216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk biraz daha sinsice yaklaşırsa kurtlar ...'::text,'uyanacak'::text,'uyanırdı'::text,'uyandı'::text,'Tavuk biraz daha sinsice yaklaşırsa kurtlar uyanacak.'::text),
(388944,43216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tyúk még közelebb oson, a farkasok ...'::text,'felébrednek'::text,'felébrednének'::text,'felébredtek'::text,'Ha a tyúk még közelebb oson, a farkasok felébrednek.'::text),
(388947,43217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Exemplar sich nicht so leise ..., würden die Wölfe es vermutlich bemerken.'::text,'anschliche'::text,'anschleicht'::text,'anschleichen wird'::text,'Wenn das Exemplar sich nicht so leise anschliche, würden die Wölfe es vermutlich bemerken.'::text),
(388951,43217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби особина ... так тихо, вовки, імовірно, помітили б її.'::text,'не підкрадалася'::text,'не підкрадається'::text,'не підкрадатиметься'::text,'Якби особина не підкрадалася так тихо, вовки, імовірно, помітили б її.'::text),
(388950,43217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el ejemplar ... tan sigilosamente, los lobos probablemente lo detectarían.'::text,'no se moviera'::text,'no se mueve'::text,'no se moverá'::text,'Si el ejemplar no se moviera tan sigilosamente, los lobos probablemente lo detectarían.'::text),
(388949,43217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le spécimen ... aussi discrètement, les loups le détecteraient probablement.'::text,'ne se faufilait pas'::text,'ne se faufile pas'::text,'ne se faufilera pas'::text,'Si le spécimen ne se faufilait pas aussi discrètement, les loups le détecteraient probablement.'::text),
(388952,43217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birey bu kadar sessizce ..., kurtlar muhtemelen onu fark ederdi.'::text,'süzülmeseydi'::text,'süzülmüyorsa'::text,'süzülmeyecekse'::text,'Birey bu kadar sessizce süzülmeseydi, kurtlar muhtemelen onu fark ederdi.'::text),
(388953,43217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egyed ... ilyen halkan, a farkasok feltehetően észlelnék.'::text,'nem surranna'::text,'nem surran'::text,'nem fog surranni'::text,'Ha az egyed nem surranna ilyen halkan, a farkasok feltehetően észlelnék.'::text),
(388956,43218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... von den Wölfen, weil sie schliefen, also schlich sie vorbei.'::text,'wurde nicht gesehen'::text,'sah nicht'::text,'sieht nicht'::text,'Die Henne wurde nicht gesehen von den Wölfen, weil sie schliefen, also schlich sie vorbei.'::text),
(388960,43218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курку ... вовки, бо вони спали, тож вона прокралася повз.'::text,'не побачили'::text,'не побачила'::text,'не бачить'::text,'Курку не побачили вовки, бо вони спали, тож вона прокралася повз.'::text),
(388959,43218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... por los lobos porque estaban dormidos, así que pasó a escondidas.'::text,'no fue vista'::text,'no vio'::text,'no está viendo'::text,'La gallina no fue vista por los lobos porque estaban dormidos, así que pasó a escondidas.'::text),
(388958,43218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... par les loups parce qu''ils dormaient, donc elle est passée en douce.'::text,'n''a pas été vue'::text,'n''a pas vu'::text,'ne voit pas'::text,'La poule n''a pas été vue par les loups parce qu''ils dormaient, donc elle est passée en douce.'::text),
(388961,43218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurtlar uyuduğu için tavuk onlar tarafından ..., bu yüzden gizlice yanlarından geçti.'::text,'görülmedi'::text,'görmedi'::text,'görmüyor'::text,'Kurtlar uyuduğu için tavuk onlar tarafından görülmedi, bu yüzden gizlice yanlarından geçti.'::text),
(388962,43218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúkot ... a farkasok, mert aludtak, így elosont mellettük.'::text,'nem látták'::text,'nem látta'::text,'nem látja'::text,'A tyúkot nem látták a farkasok, mert aludtak, így elosont mellettük.'::text),
(388965,43219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... leise an den Wölfen vorbei, weil Schleichen leise ist.'::text,'schlich'::text,'wurde geschlichen'::text,'schleichend'::text,'Die Henne schlich leise an den Wölfen vorbei, weil Schleichen leise ist.'::text),
(388969,43219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка тихо ... повз вовків, бо підкрадатися — це тихо.'::text,'прокралася'::text,'прокралася'::text,'підкрадання'::text,'Курка тихо прокралася повз вовків, бо підкрадатися — це тихо.'::text),
(388968,43219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... sin hacer ruido junto a los lobos, porque escabullirse es silencioso.'::text,'pasó a escondidas'::text,'fue pasada a escondidas'::text,'pasando a escondidas'::text,'La gallina pasó a escondidas sin hacer ruido junto a los lobos, porque escabullirse es silencioso.'::text),
(388967,43219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... discrètement devant les loups, parce que se faufiler, c''est silencieux.'::text,'est passée'::text,'a été passée'::text,'passant'::text,'La poule est passée discrètement devant les loups, parce que se faufiler, c''est silencieux.'::text),
(388970,43219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk kurtların yanından sessizce ..., çünkü gizlice ilerlemek sessizdir.'::text,'süzüldü'::text,'süzüldü'::text,'süzülmek'::text,'Tavuk kurtların yanından sessizce süzüldü, çünkü gizlice ilerlemek sessizdir.'::text),
(388971,43219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk halkan ... a farkasok mellett, mert az osonás halk.'::text,'osont el'::text,'osont el'::text,'osonás'::text,'A tyúk halkan osont el a farkasok mellett, mert az osonás halk.'::text),
(358311,39813,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Glühwürmchen im Glas leuchtet, und ... der ganze Wald. Offensichtlich eine kleine Lichtshow.'::text,'ebenso'::text,'ebenso ist'::text,'ebenso wenig'::text,'Das Glühwürmchen im Glas leuchtet, und ebenso der ganze Wald. Offensichtlich eine kleine Lichtshow.'::text),
(358315,39813,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Світлячок у банці світиться, і ... весь ліс. Очевидно, маленьке світлове шоу.'::text,'світиться й'::text,'є й'::text,'не світиться й'::text,'Світлячок у банці світиться, і світиться й весь ліс. Очевидно, маленьке світлове шоу.'::text),
(358314,39813,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luciérnaga del frasco brilla, y ... todo el bosque. Obviamente, un pequeño espectáculo de luces.'::text,'también brilla'::text,'también es'::text,'tampoco brilla'::text,'La luciérnaga del frasco brilla, y también brilla todo el bosque. Obviamente, un pequeño espectáculo de luces.'::text),
(358313,39813,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luciole dans le bocal brille, et ... toute la forêt. Évidemment, un petit spectacle de lumière.'::text,'brille aussi'::text,'est aussi'::text,'ne brille pas non plus'::text,'La luciole dans le bocal brille, et brille aussi toute la forêt. Évidemment, un petit spectacle de lumière.'::text),
(358316,39813,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kavanozdaki ateş böceği parlıyor, bütün orman da ..., belli ki küçük bir ışık gösterisi.'::text,'parlıyor'::text,'öyle'::text,'parlamıyor'::text,'Kavanozdaki ateş böceği parlıyor, bütün orman da parlıyor, belli ki küçük bir ışık gösterisi.'::text),
(358317,39813,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A befőttesüvegben lévő szentjánosbogár világít, és ... az egész erdő. Nyilvánvalóan egy kis fényshow.'::text,'ugyanígy világít'::text,'ugyanígy van'::text,'nem világít'::text,'A befőttesüvegben lévő szentjánosbogár világít, és ugyanígy világít az egész erdő. Nyilvánvalóan egy kis fényshow.'::text),
(358320,39814,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, bis Mitternacht wird das Glas vom Küken sein Leuchten ..., ohne Witz.'::text,'verloren haben'::text,'verlieren'::text,'verlieren'::text,'Digga, bis Mitternacht wird das Glas vom Küken sein Leuchten verloren haben, ohne Witz.'::text),
(358324,39814,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, до півночі банка курчати ... своє сяйво, без приколів.'::text,'втратить'::text,'втратить'::text,'втрачає'::text,'Йоу, до півночі банка курчати втратить своє сяйво, без приколів.'::text),
(358323,39814,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, para medianoche el frasco del pollito ... su brillo, en serio.'::text,'habrá perdido'::text,'perderá'::text,'pierde'::text,'Oye, para medianoche el frasco del pollito habrá perdido su brillo, en serio.'::text),
(358322,39814,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, d''ici minuit, le bocal du poussin ... son éclat, sans mentir.'::text,'aura perdu'::text,'perdra'::text,'perd'::text,'Yo, d''ici minuit, le bocal du poussin aura perdu son éclat, sans mentir.'::text),
(358325,39814,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gece yarısına kadar civcivin kavanozu ışığını ..., yemin ederim.'::text,'kaybetmiş olacak'::text,'kaybedecek'::text,'kaybeder'::text,'Kanka, gece yarısına kadar civcivin kavanozu ışığını kaybetmiş olacak, yemin ederim.'::text),
(358326,39814,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, éjfélre a csibe üvege ... a fényét, komolyan.'::text,'elveszíti'::text,'elveszíti'::text,'veszíti'::text,'Tesó, éjfélre a csibe üvege elveszíti a fényét, komolyan.'::text),
(358329,39815,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn das Glühwürmchen nicht geleuchtet hätte, ... das Küken in dem Bau gar nichts gesehen, echt jetzt.'::text,'hätte'::text,'wird'::text,'sah'::text,'Bro, wenn das Glühwürmchen nicht geleuchtet hätte, hätte das Küken in dem Bau gar nichts gesehen, echt jetzt.'::text),
(358333,39815,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, якби світлячок не світився, курча ... нічого в тій норі, реально.'::text,'не побачило б'::text,'не побачить'::text,'не бачило'::text,'Брате, якби світлячок не світився, курча не побачило б нічого в тій норі, реально.'::text),
(358332,39815,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si la luciérnaga no hubiera brillado, el pollito ... nada en esa madriguera, de verdad.'::text,'no habría visto'::text,'no verá'::text,'no vio'::text,'Bro, si la luciérnaga no hubiera brillado, el pollito no habría visto nada en esa madriguera, de verdad.'::text),
(358331,39815,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si la luciole n''avait pas brillé, le poussin ... dans ce terrier, grave.'::text,'n''aurait rien vu'::text,'ne verra rien'::text,'n''a rien vu'::text,'Frérot, si la luciole n''avait pas brillé, le poussin n''aurait rien vu dans ce terrier, grave.'::text),
(358334,39815,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ateş böceği parlamasaydı civciv o yuvada hiçbir şey ..., cidden.'::text,'göremezdi'::text,'görmeyecek'::text,'görmedi'::text,'Kanka, ateş böceği parlamasaydı civciv o yuvada hiçbir şey göremezdi, cidden.'::text),
(358335,39815,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha a szentjánosbogár nem világított volna, a csibe ... semmit abban az üregben, komolyan.'::text,'nem látott volna'::text,'nem fog látni'::text,'nem látott'::text,'Tesó, ha a szentjánosbogár nem világított volna, a csibe nem látott volna semmit abban az üregben, komolyan.'::text),
(358338,39816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne erinnerte das Küken daran, das leuchtende Glas vorsichtig ...'::text,'zu halten'::text,'halten'::text,'gehalten'::text,'Die Henne erinnerte das Küken daran, das leuchtende Glas vorsichtig zu halten.'::text),
(358342,39816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка нагадала курчаті обережно ... банку, що світиться.'::text,'тримати'::text,'тримання'::text,'тримало'::text,'Курка нагадала курчаті обережно тримати банку, що світиться.'::text),
(358341,39816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina le recordó al pollito que ... el frasco brillante con cuidado.'::text,'sostuviera'::text,'sosteniendo'::text,'sostuvo'::text,'La gallina le recordó al pollito que sostuviera el frasco brillante con cuidado.'::text),
(358340,39816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule a rappelé au poussin de ... le bocal lumineux avec précaution.'::text,'tenir'::text,'tenant'::text,'tenu'::text,'La poule a rappelé au poussin de tenir le bocal lumineux avec précaution.'::text),
(358343,39816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk civcive parlayan kavanozu dikkatlice ... hatırlattı.'::text,'tutmasını'::text,'tutarak'::text,'tuttu'::text,'Tavuk civcive parlayan kavanozu dikkatlice tutmasını hatırlattı.'::text),
(358344,39816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk emlékeztette a csibét, hogy óvatosan ... a világító üveget.'::text,'tartsa'::text,'tartva'::text,'tartotta'::text,'A tyúk emlékeztette a csibét, hogy óvatosan tartsa a világító üveget.'::text),
(358347,39817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken ... das Glühwürmchen vorhin gefangen haben, denn jetzt leuchtet es im Glas.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Das Küken muss das Glühwürmchen vorhin gefangen haben, denn jetzt leuchtet es im Glas.'::text),
(358351,39817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча ... світлячка раніше, бо тепер він світиться в банці.'::text,'мабуть, спіймало'::text,'мало спіймати'::text,'не могло спіймати'::text,'Курча мабуть, спіймало світлячка раніше, бо тепер він світиться в банці.'::text),
(358350,39817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito ... atrapado la luciérnaga antes, porque ahora brilla dentro del frasco.'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'El pollito debe de haber atrapado la luciérnaga antes, porque ahora brilla dentro del frasco.'::text),
(358349,39817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin ... attraper la luciole plus tôt, car elle brille maintenant dans le bocal.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Le poussin a dû attraper la luciole plus tôt, car elle brille maintenant dans le bocal.'::text),
(358352,39817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv ateş böceğini daha önce ..., çünkü şimdi kavanozun içinde parlıyor.'::text,'yakalamış olmalı'::text,'yakalamalıydı'::text,'yakalamış olamaz'::text,'Civciv ateş böceğini daha önce yakalamış olmalı, çünkü şimdi kavanozun içinde parlıyor.'::text),
(358353,39817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe ... a szentjánosbogarat korábban, mert most az üvegben világít.'::text,'biztosan elkapta'::text,'el kellett volna kapnia'::text,'nem kaphatta el'::text,'A csibe biztosan elkapta a szentjánosbogarat korábban, mert most az üvegben világít.'::text),
(358356,39818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken ließ das Glas mit einem Metalldeckel ..., damit das leuchtende Glühwürmchen drinblieb.'::text,'verschließen'::text,'verschließen'::text,'zu verschließen'::text,'Das Küken ließ das Glas mit einem Metalldeckel verschließen, damit das leuchtende Glühwürmchen drinblieb.'::text),
(358360,39818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча попросило ... банку металевою кришкою, щоб світлячок лишився всередині.'::text,'закрити'::text,'закрити'::text,'закрити'::text,'Курча попросило закрити банку металевою кришкою, щоб світлячок лишився всередині.'::text),
(358359,39818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito hizo ... el frasco con una tapa de metal para que la luciérnaga brillante se quedara dentro.'::text,'cerrar'::text,'cerrar'::text,'cerrar'::text,'El pollito hizo cerrar el frasco con una tapa de metal para que la luciérnaga brillante se quedara dentro.'::text),
(358358,39818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin a fait ... le bocal avec un couvercle en métal pour que la luciole lumineuse reste dedans.'::text,'fermer'::text,'fermer'::text,'fermer'::text,'Le poussin a fait fermer le bocal avec un couvercle en métal pour que la luciole lumineuse reste dedans.'::text),
(358361,39818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv, parlayan ateş böceği içeride kalsın diye kavanozu metal bir kapakla ...'::text,'kapattırdı'::text,'kapattırdı'::text,'kapattırdı'::text,'Civciv, parlayan ateş böceği içeride kalsın diye kavanozu metal bir kapakla kapattırdı.'::text),
(358362,39818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe fémfedővel ... az üveget, hogy a világító szentjánosbogár bent maradjon.'::text,'lezáratta'::text,'lezáratta'::text,'lezáratta'::text,'A csibe fémfedővel lezáratta az üveget, hogy a világító szentjánosbogár bent maradjon.'::text),
(358365,39819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken wünscht sich, sein Glas ... so hell wie der Wald.'::text,'leuchtete'::text,'leuchtet'::text,'würde leuchten'::text,'Das Küken wünscht sich, sein Glas leuchtete so hell wie der Wald.'::text),
(358369,39819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча хотіло б, щоб його банка ... так яскраво, як ліс.'::text,'сяяла'::text,'сяє'::text,'сяятиме'::text,'Курча хотіло б, щоб його банка сяяла так яскраво, як ліс.'::text),
(358368,39819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito desearía que su frasco ... tan intensamente como el bosque.'::text,'brillara'::text,'brilla'::text,'brillará'::text,'El pollito desearía que su frasco brillara tan intensamente como el bosque.'::text),
(358367,39819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin aimerait que son bocal ... aussi fort que la forêt.'::text,'brille'::text,'brille'::text,'brillera'::text,'Le poussin aimerait que son bocal brille aussi fort que la forêt.'::text),
(358370,39819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv keşke kavanozu da orman kadar parlak ... diye düşünüyor.'::text,'parlasa'::text,'parlıyor'::text,'parlayacak'::text,'Civciv keşke kavanozu da orman kadar parlak parlasa diye düşünüyor.'::text),
(358371,39819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe azt kívánja, bárcsak az üvege olyan fényesen ..., mint az erdő.'::text,'ragyogna'::text,'ragyog'::text,'ragyogni fog'::text,'A csibe azt kívánja, bárcsak az üvege olyan fényesen ragyogna, mint az erdő.'::text),
(358383,39821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken trug das Glas zum Eingang des Baus, ... den leuchtenden Wald zu sehen.'::text,'um'::text,'damit'::text,'trotz'::text,'Das Küken trug das Glas zum Eingang des Baus, um den leuchtenden Wald zu sehen.'::text),
(358387,39821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча віднесло банку до виходу з нори, ... побачити сяючий ліс.'::text,'щоб'::text,'щоб'::text,'попри'::text,'Курча віднесло банку до виходу з нори, щоб побачити сяючий ліс.'::text),
(358386,39821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito llevó el frasco a la entrada de la madriguera ... ver el bosque brillante.'::text,'para'::text,'para que'::text,'a pesar de'::text,'El pollito llevó el frasco a la entrada de la madriguera para ver el bosque brillante.'::text),
(358385,39821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin a porté le bocal jusqu''à l''entrée du terrier ... voir la forêt lumineuse.'::text,'afin de'::text,'pour que'::text,'malgré'::text,'Le poussin a porté le bocal jusqu''à l''entrée du terrier afin de voir la forêt lumineuse.'::text),
(358388,39821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Civciv parlayan ormanı ... kavanozu yuvanın ağzına taşıdı.'::text,'görmek için'::text,'görsün diye'::text,'görmesine rağmen'::text,'Civciv parlayan ormanı görmek için kavanozu yuvanın ağzına taşıdı.'::text),
(358389,39821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe az üreg bejáratához vitte az üveget, ... lássa a világító erdőt.'::text,'hogy'::text,'azért, hogy'::text,'annak ellenére, hogy'::text,'A csibe az üreg bejáratához vitte az üveget, hogy lássa a világító erdőt.'::text),
(358392,39822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... der ganze Wald morgen Nacht wieder.'::text,'leuchtet'::text,'leuchtet'::text,'wird geleuchtet haben'::text,'Bestie, angeblich leuchtet der ganze Wald morgen Nacht wieder.'::text),
(358396,39822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, весь ліс завтра вночі знову ...'::text,'засяє'::text,'сяє'::text,'засяє'::text,'Подруго, кажуть, весь ліс завтра вночі знову засяє.'::text),
(358395,39822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dicen que todo el bosque ... otra vez mañana por la noche.'::text,'brillará'::text,'brilla'::text,'habrá brillado'::text,'Amiga, dicen que todo el bosque brillará otra vez mañana por la noche.'::text),
(358394,39822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que toute la forêt ... encore demain soir.'::text,'brillera'::text,'brille'::text,'aura brillé'::text,'Ma belle, il paraît que toute la forêt brillera encore demain soir.'::text),
(358397,39822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dediklerine göre bütün orman yarın gece yine ...'::text,'parlayacakmış'::text,'parlıyormuş'::text,'parlamış olacakmış'::text,'Kanka, dediklerine göre bütün orman yarın gece yine parlayacakmış.'::text),
(358398,39822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag holnap éjjel megint ... az egész erdő.'::text,'világítani fog'::text,'világít'::text,'világított majd'::text,'Csajszi, állítólag holnap éjjel megint világítani fog az egész erdő.'::text),
(357924,39770,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die großzügige Henne Mais in das Loch ..., stieg das Lebensmittelbudget der Mäuse um 100 %.'::text,'schob'::text,'schob'::text,'geschoben hat'::text,'Während die großzügige Henne Mais in das Loch schob, stieg das Lebensmittelbudget der Mäuse um 100 %.'::text),
(357928,39770,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки щедра курка ... кукурудзу в нору, продовольчий бюджет мишей зріс на 100 %.'::text,'штовхала'::text,'заштовхала'::text,'заштовхала'::text,'Поки щедра курка штовхала кукурудзу в нору, продовольчий бюджет мишей зріс на 100 %.'::text),
(357927,39770,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras la generosa gallina ... maíz en el agujero, el presupuesto alimentario de los ratones creció un 100 %.'::text,'empujaba'::text,'empujó'::text,'ha empujado'::text,'Mientras la generosa gallina empujaba maíz en el agujero, el presupuesto alimentario de los ratones creció un 100 %.'::text),
(357926,39770,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que la généreuse poule ... du maïs dans le trou, le budget alimentaire des souris a augmenté de 100 %.'::text,'poussait'::text,'a poussé'::text,'a poussé'::text,'Pendant que la généreuse poule poussait du maïs dans le trou, le budget alimentaire des souris a augmenté de 100 %.'::text),
(357929,39770,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cömert tavuk mısırı deliğe ..., farelerin yiyecek bütçesi %100 arttı.'::text,'iterken'::text,'itti'::text,'itmiş'::text,'Cömert tavuk mısırı deliğe iterken, farelerin yiyecek bütçesi %100 arttı.'::text),
(357930,39770,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a nagylelkű tyúk kukoricát ... a lyukba, az egerek élelmiszer-költségvetése 100%-kal nőtt.'::text,'tolt'::text,'betolt'::text,'betolt'::text,'Miközben a nagylelkű tyúk kukoricát tolt a lyukba, az egerek élelmiszer-költségvetése 100%-kal nőtt.'::text),
(357933,39771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese großzügige Henne ... den verzweifelten Mäusen den ganzen Winter Mais!'::text,'bringt'::text,'bringt'::text,'bringt'::text,'Diese großzügige Henne bringt den verzweifelten Mäusen den ganzen Winter Mais!'::text),
(357937,39771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця щедра курка всю зиму ... кукурудзу тим нещасним мишам!'::text,'носить'::text,'носить'::text,'носить'::text,'Ця щедра курка всю зиму носить кукурудзу тим нещасним мишам!'::text),
(357936,39771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta generosa gallina ... maíz a esos ratones desesperados todo el invierno!'::text,'lleva trayendo'::text,'está trayendo'::text,'trae'::text,'¡Esta generosa gallina lleva trayendo maíz a esos ratones desesperados todo el invierno!'::text),
(357935,39771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette généreuse poule ... du maïs à ces souris désespérées depuis tout l''hiver !'::text,'apporte'::text,'apporte'::text,'apporte'::text,'Cette généreuse poule apporte du maïs à ces souris désespérées depuis tout l''hiver !'::text),
(357938,39771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu cömert tavuk bütün kış o çaresiz farelere mısır ...!'::text,'getiriyor'::text,'getiriyor'::text,'getirir'::text,'Bu cömert tavuk bütün kış o çaresiz farelere mısır getiriyor!'::text),
(357939,39771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a nagylelkű tyúk egész télen ... kukoricát azoknak a kétségbeesett egereknek!'::text,'hord'::text,'hord'::text,'hord'::text,'Ez a nagylelkű tyúk egész télen hord kukoricát azoknak a kétségbeesett egereknek!'::text),
(357942,39772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die großzügige Henne ... sich durch den Zaun und schaute dann in das Loch.'::text,'zwängte'::text,'zwängte gerade'::text,'hat gezwängt'::text,'Die großzügige Henne zwängte sich durch den Zaun und schaute dann in das Loch.'::text),
(357946,39772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щедра курка ... крізь паркан, а потім зазирнула в нору.'::text,'протиснулася'::text,'протискалася'::text,'протиснулася'::text,'Щедра курка протиснулася крізь паркан, а потім зазирнула в нору.'::text),
(357945,39772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La generosa gallina ... por la valla y luego miró dentro del agujero.'::text,'se coló'::text,'se estaba colando'::text,'se ha colado'::text,'La generosa gallina se coló por la valla y luego miró dentro del agujero.'::text),
(357944,39772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La généreuse poule ... à travers la clôture, puis a regardé dans le trou.'::text,'s''est faufilée'::text,'se faufilait'::text,'s''est faufilée'::text,'La généreuse poule s''est faufilée à travers la clôture, puis a regardé dans le trou.'::text),
(357947,39772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cömert tavuk çitin arasından ... ve sonra deliğe baktı.'::text,'sıyrıldı'::text,'sıyrılıyordu'::text,'sıyrılmış'::text,'Cömert tavuk çitin arasından sıyrıldı ve sonra deliğe baktı.'::text),
(357948,39772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagylelkű tyúk ... a kerítésen, aztán belenézett a lyukba.'::text,'átpréselte magát'::text,'préselte magát'::text,'átpréselte magát'::text,'A nagylelkű tyúk átpréselte magát a kerítésen, aztán belenézett a lyukba.'::text),
(357951,39773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die großzügige Henne ... den Mäusen diese Woche drei große Haufen Mais gegeben.'::text,'hat'::text,'hat'::text,'gibt'::text,'Die großzügige Henne hat den Mäusen diese Woche drei große Haufen Mais gegeben.'::text),
(357955,39773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щедра курка цього тижня ... мишам три великі купи кукурудзи.'::text,'дала'::text,'давала'::text,'дає'::text,'Щедра курка цього тижня дала мишам три великі купи кукурудзи.'::text),
(357954,39773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La generosa gallina les ... a los ratones tres grandes montones de maíz esta semana.'::text,'ha dado'::text,'ha estado dando'::text,'da'::text,'La generosa gallina les ha dado a los ratones tres grandes montones de maíz esta semana.'::text),
(357953,39773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La généreuse poule ... trois gros tas de maïs aux souris cette semaine.'::text,'a donné'::text,'donne'::text,'donne'::text,'La généreuse poule a donné trois gros tas de maïs aux souris cette semaine.'::text),
(357956,39773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cömert tavuk bu hafta farelere üç büyük yığın mısır ...'::text,'verdi'::text,'veriyor'::text,'verir'::text,'Cömert tavuk bu hafta farelere üç büyük yığın mısır verdi.'::text),
(357957,39773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagylelkű tyúk ezen a héten három nagy kupac kukoricát ... az egereknek.'::text,'adott'::text,'adogatott'::text,'ad'::text,'A nagylelkű tyúk ezen a héten három nagy kupac kukoricát adott az egereknek.'::text),
(357960,39774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sich die Mäuse versammelten, ... die großzügige Henne schon den ganzen Mais in das Loch geschoben.'::text,'hatte'::text,'hat'::text,'schiebt'::text,'Als sich die Mäuse versammelten, hatte die großzügige Henne schon den ganzen Mais in das Loch geschoben.'::text),
(357964,39774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки миші зібралися, щедра курка вже ... всю кукурудзу в нору.'::text,'заштовхала'::text,'заштовхала'::text,'штовхає'::text,'Поки миші зібралися, щедра курка вже заштовхала всю кукурудзу в нору.'::text),
(357963,39774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando los ratones se reunieron, la generosa gallina ya ... todo el maíz en el agujero.'::text,'había empujado'::text,'ha empujado'::text,'empuja'::text,'Cuando los ratones se reunieron, la generosa gallina ya había empujado todo el maíz en el agujero.'::text),
(357962,39774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les souris se sont rassemblées, la généreuse poule ... tout le maïs dans le trou.'::text,'avait déjà poussé'::text,'a déjà poussé'::text,'pousse'::text,'Quand les souris se sont rassemblées, la généreuse poule avait déjà poussé tout le maïs dans le trou.'::text),
(357965,39774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fareler toplandığında cömert tavuk bütün mısırı çoktan deliğe ... bile.'::text,'itmişti'::text,'itti'::text,'itiyor'::text,'Fareler toplandığında cömert tavuk bütün mısırı çoktan deliğe itmişti bile.'::text),
(357966,39774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az egerek összegyűltek, a nagylelkű tyúk már az összes kukoricát ... a lyukba.'::text,'betolta'::text,'betolta'::text,'tolja'::text,'Mire az egerek összegyűltek, a nagylelkű tyúk már az összes kukoricát betolta a lyukba.'::text),
(357969,39775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Henne so großzügig bleibt, ... die Mäuse genug Mais für den Winter.'::text,'haben'::text,'hätten'::text,'hatten'::text,'Wenn die Henne so großzügig bleibt, haben die Mäuse genug Mais für den Winter.'::text),
(357973,39775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо курка залишиться такою щедрою, миші ... достатньо кукурудзи на зиму.'::text,'матимуть'::text,'мали б'::text,'мали'::text,'Якщо курка залишиться такою щедрою, миші матимуть достатньо кукурудзи на зиму.'::text),
(357972,39775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gallina sigue siendo tan generosa, los ratones ... suficiente maíz para el invierno.'::text,'tendrán'::text,'tendrían'::text,'tenían'::text,'Si la gallina sigue siendo tan generosa, los ratones tendrán suficiente maíz para el invierno.'::text),
(357971,39775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la poule reste aussi généreuse, les souris ... assez de maïs pour l''hiver.'::text,'auront'::text,'auraient'::text,'avaient'::text,'Si la poule reste aussi généreuse, les souris auront assez de maïs pour l''hiver.'::text),
(357974,39775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk böyle cömert kalırsa fareler kış için yeterince mısıra ...'::text,'sahip olacak'::text,'sahip olurdu'::text,'sahipti'::text,'Tavuk böyle cömert kalırsa fareler kış için yeterince mısıra sahip olacak.'::text),
(357975,39775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tyúk ilyen nagylelkű marad, az egereknek ... elég kukoricájuk télre.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a tyúk ilyen nagylelkű marad, az egereknek lesz elég kukoricájuk télre.'::text),
(357978,39776,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre die Henne weniger großzügig, ... die Mäuse.'::text,'hungerten'::text,'werden hungern'::text,'hungern'::text,'Wäre die Henne weniger großzügig, hungerten die Mäuse.'::text),
(357982,39776,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби курка була менш щедрою, миші ...'::text,'голодували б'::text,'голодуватимуть'::text,'голодують'::text,'Якби курка була менш щедрою, миші голодували б.'::text),
(357981,39776,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gallina fuera menos generosa, los ratones ...'::text,'pasarían hambre'::text,'pasarán hambre'::text,'pasan hambre'::text,'Si la gallina fuera menos generosa, los ratones pasarían hambre.'::text),
(357980,39776,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la poule était moins généreuse, les souris ...'::text,'auraient faim'::text,'auront faim'::text,'ont faim'::text,'Si la poule était moins généreuse, les souris auraient faim.'::text),
(357983,39776,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk daha az cömert olsaydı fareler ...'::text,'aç kalırdı'::text,'aç kalacak'::text,'aç kalır'::text,'Tavuk daha az cömert olsaydı fareler aç kalırdı.'::text),
(357984,39776,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tyúk kevésbé lenne nagylelkű, az egerek ...'::text,'éheznének'::text,'éhezni fognak'::text,'éheznek'::text,'Ha a tyúk kevésbé lenne nagylelkű, az egerek éheznének.'::text),
(357996,39778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die großzügige Henne ... den Mäusen den ganzen Mais. Offensichtlich eine schreckliche Nachbarin.'::text,'gab'::text,'bekam'::text,'gebend'::text,'Die großzügige Henne gab den Mäusen den ganzen Mais. Offensichtlich eine schreckliche Nachbarin.'::text),
(358000,39778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щедра курка ... мишам усю кукурудзу. Очевидно, жахлива сусідка.'::text,'віддала'::text,'отримала'::text,'віддаючи'::text,'Щедра курка віддала мишам усю кукурудзу. Очевидно, жахлива сусідка.'::text),
(357999,39778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La generosa gallina les ... todo el maíz a los ratones. Obviamente, una vecina terrible.'::text,'dio'::text,'fue dado'::text,'dando'::text,'La generosa gallina les dio todo el maíz a los ratones. Obviamente, una vecina terrible.'::text),
(357998,39778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La généreuse poule ... tout le maïs aux souris. Évidemment, une voisine horrible.'::text,'a donné'::text,'a été donnée'::text,'donnant'::text,'La généreuse poule a donné tout le maïs aux souris. Évidemment, une voisine horrible.'::text),
(358001,39778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cömert tavuk bütün mısırı farelere ..., belli ki berbat bir komşu.'::text,'verdi'::text,'verildi'::text,'vererek'::text,'Cömert tavuk bütün mısırı farelere verdi, belli ki berbat bir komşu.'::text),
(358002,39778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagylelkű tyúk az összes kukoricát ... az egereknek. Nyilvánvalóan szörnyű szomszéd.'::text,'odaadta'::text,'kapta'::text,'odaadva'::text,'A nagylelkű tyúk az összes kukoricát odaadta az egereknek. Nyilvánvalóan szörnyű szomszéd.'::text),
(358005,39779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, diese Henne ... der großzügigste Vogel auf der ganzen Farm sein, ohne Witz.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Digga, diese Henne muss der großzügigste Vogel auf der ganzen Farm sein, ohne Witz.'::text),
(358009,39779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, ця курка ... бути найщедрішою пташкою на всій фермі, без приколів.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Брате, ця курка мусить бути найщедрішою пташкою на всій фермі, без приколів.'::text),
(358008,39779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esa gallina ... ser el ave más generosa de toda la granja, en serio.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Bro, esa gallina debe de ser el ave más generosa de toda la granja, en serio.'::text),
(358007,39779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette poule ... être l''oiseau le plus généreux de toute la ferme, sans mentir.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Frérot, cette poule doit être l''oiseau le plus généreux de toute la ferme, sans mentir.'::text),
(358010,39779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o tavuk bütün çiftliğin en cömert kuşu ..., yemin ederim.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Kanka, o tavuk bütün çiftliğin en cömert kuşu olmalı, yemin ederim.'::text),
(358011,39779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a tyúk ... az egész farm legnagylelkűbb madara, komolyan.'::text,'biztosan'::text,'nem lehet'::text,'nem szabad, hogy'::text,'Tesó, az a tyúk biztosan az egész farm legnagylelkűbb madara, komolyan.'::text),
(358014,39780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Henne, ... Mais die ganze Mäusefamilie satt gemacht hat, ist schon ziemlich großzügig, echt.'::text,'deren'::text,'die'::text,'welche'::text,'Digga, die Henne, deren Mais die ganze Mäusefamilie satt gemacht hat, ist schon ziemlich großzügig, echt.'::text),
(358018,39780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, курка, ... кукурудза нагодувала всю мишачу родину, досить щедра, реально.'::text,'чия'::text,'яка'::text,'котра'::text,'Йоу, курка, чия кукурудза нагодувала всю мишачу родину, досить щедра, реально.'::text),
(358017,39780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la gallina ... maíz alimentó a toda la familia de ratones es bastante generosa, en serio.'::text,'cuyo'::text,'que'::text,'la cual'::text,'Oye, la gallina cuyo maíz alimentó a toda la familia de ratones es bastante generosa, en serio.'::text),
(358016,39780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la poule ... le maïs a nourri toute la famille de souris est plutôt généreuse, grave.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Yo, la poule dont le maïs a nourri toute la famille de souris est plutôt généreuse, grave.'::text),
(358019,39780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... mısırı bütün fare ailesini doyuran tavuk bayağı cömert, cidden.'::text,''::text,NULL::text,NULL::text,'Kanka, mısırı bütün fare ailesini doyuran tavuk bayağı cömert, cidden.'::text),
(358020,39780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a tyúk, ... kukoricája megetette az egész egércsaládot, elég nagylelkű, komolyan.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Tesó, a tyúk, akinek a kukoricája megetette az egész egércsaládot, elég nagylelkű, komolyan.'::text),
(369111,41013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hielt den Alligator für ihren Hund, während sie durch den Säulengang ...'::text,'lief'::text,'lief'::text,'gelaufen ist'::text,'Sie hielt den Alligator für ihren Hund, während sie durch den Säulengang lief.'::text),
(369115,41013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сплутала алігатора зі своїм собакою, поки ... колонадою.'::text,'гуляла'::text,'гуляла'::text,'пройшлася'::text,'Вона сплутала алігатора зі своїм собакою, поки гуляла колонадою.'::text),
(369114,41013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Confundió al caimán con su perro mientras ... por la columnata.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Confundió al caimán con su perro mientras caminaba por la columnata.'::text),
(369113,41013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a pris l''alligator pour son chien pendant qu''elle ... le long de la colonnade.'::text,'marchait'::text,'marcha'::text,'a marché'::text,'Elle a pris l''alligator pour son chien pendant qu''elle marchait le long de la colonnade.'::text),
(369116,41013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sütunlu yol boyunca ... timsahı köpeği sandı.'::text,'yürürken'::text,'yürüdü'::text,'yürümüş'::text,'Sütunlu yol boyunca yürürken timsahı köpeği sandı.'::text),
(369117,41013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Összetévesztette az aligátort a kutyájával, miközben az oszlopsor mentén ...'::text,'sétált'::text,'végigsétált'::text,'végigsétált'::text,'Összetévesztette az aligátort a kutyájával, miközben az oszlopsor mentén sétált.'::text),
(369120,41014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Alligator seit einer halben Stunde an der Leine spazieren und hält ihn für ihren Hund.'::text,'führt'::text,'führt'::text,'führt'::text,'Sie führt den Alligator seit einer halben Stunde an der Leine spazieren und hält ihn für ihren Hund.'::text),
(369124,41014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже пів години ... алігатора на повідку, приймаючи його за свого собаку.'::text,'вигулює'::text,'вигулює'::text,'вигулює'::text,'Вона вже пів години вигулює алігатора на повідку, приймаючи його за свого собаку.'::text),
(369123,41014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... al caimán con correa media hora, confundiéndolo con su perro.'::text,'lleva paseando'::text,'está paseando'::text,'pasea'::text,'Ella lleva paseando al caimán con correa media hora, confundiéndolo con su perro.'::text),
(369122,41014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... l''alligator en laisse depuis une demi-heure, le prenant pour son chien.'::text,'promène'::text,'promène'::text,'promène'::text,'Elle promène l''alligator en laisse depuis une demi-heure, le prenant pour son chien.'::text),
(369125,41014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarım saattir timsahı köpeği sanarak tasmayla ...'::text,'gezdiriyor'::text,'gezdiriyor'::text,'gezdirir'::text,'Yarım saattir timsahı köpeği sanarak tasmayla gezdiriyor.'::text),
(369126,41014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fél órája ... pórázon az aligátort, mert a kutyájának hiszi.'::text,'sétáltatja'::text,'sétáltatja'::text,'sétáltatja'::text,'Fél órája sétáltatja pórázon az aligátort, mert a kutyájának hiszi.'::text),
(369129,41015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Alligator für ihren Hund, weil sie ihre Brille vergessen hatte.'::text,'hielt'::text,'hielt gerade'::text,'hat gehalten'::text,'Sie hielt den Alligator für ihren Hund, weil sie ihre Brille vergessen hatte.'::text),
(369133,41015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... алігатора зі своїм собакою, бо забула окуляри.'::text,'сплутала'::text,'плутала'::text,'сплутала'::text,'Вона сплутала алігатора зі своїм собакою, бо забула окуляри.'::text),
(369132,41015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... al caimán con su perro porque olvidó sus gafas.'::text,'confundió'::text,'estaba confundiendo'::text,'ha confundido'::text,'Ella confundió al caimán con su perro porque olvidó sus gafas.'::text),
(369131,41015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... l''alligator pour son chien parce qu''elle avait oublié ses lunettes.'::text,'a pris'::text,'prenait'::text,'a pris'::text,'Elle a pris l''alligator pour son chien parce qu''elle avait oublié ses lunettes.'::text),
(369134,41015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlüğünü unuttuğu için timsahı köpeği ...'::text,'sandı'::text,'sanıyordu'::text,'sanmış'::text,'Gözlüğünü unuttuğu için timsahı köpeği sandı.'::text),
(369135,41015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... az aligátort a kutyájával, mert elfelejtette a szemüvegét.'::text,'összetévesztette'::text,'éppen összetévesztette'::text,'összetévesztette'::text,'Ő összetévesztette az aligátort a kutyájával, mert elfelejtette a szemüvegét.'::text),
(369138,41016,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie ... den Alligator diese Woche schon zweimal für ihren Hund gehalten, ohne Witz.'::text,'hat'::text,'hat'::text,'hält'::text,'Digga, sie hat den Alligator diese Woche schon zweimal für ihren Hund gehalten, ohne Witz.'::text),
(369142,41016,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, вона цього тижня двічі ... того алігатора зі своїм собакою, без приколів.'::text,'сплутала'::text,'плутала'::text,'плутає'::text,'Брате, вона цього тижня двічі сплутала того алігатора зі своїм собакою, без приколів.'::text),
(369141,41016,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esta semana ella ... dos veces a ese caimán con su perro, en serio.'::text,'ha confundido'::text,'ha estado confundiendo'::text,'confunde'::text,'Bro, esta semana ella ha confundido dos veces a ese caimán con su perro, en serio.'::text),
(369140,41016,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... cet alligator pour son chien deux fois cette semaine, sans mentir.'::text,'a pris'::text,'prend'::text,'prend'::text,'Frérot, elle a pris cet alligator pour son chien deux fois cette semaine, sans mentir.'::text),
(369143,41016,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu hafta o timsahı iki kez köpeği ..., yemin ederim.'::text,'sandı'::text,'sanıyordu'::text,'sanar'::text,'Kanka, bu hafta o timsahı iki kez köpeği sandı, yemin ederim.'::text),
(369144,41016,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a héten már kétszer ... azt az aligátort a kutyájával, komolyan.'::text,'összetévesztette'::text,'tévesztette össze'::text,'összetéveszti'::text,'Tesó, a héten már kétszer összetévesztette azt az aligátort a kutyájával, komolyan.'::text),
(369147,41017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Digga, sie ... ihre Brille zu Hause gelassen, deshalb hat sie den Alligator für ihren Hund gehalten.'::text,'hatte'::text,'hat'::text,'lässt'::text,'Nee, Digga, sie hatte ihre Brille zu Hause gelassen, deshalb hat sie den Alligator für ihren Hund gehalten.'::text),
(369151,41017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, брате, вона ... окуляри вдома, тому й сплутала алігатора з собакою.'::text,'залишила'::text,'залишила'::text,'залишає'::text,'Не, брате, вона залишила окуляри вдома, тому й сплутала алігатора з собакою.'::text),
(369150,41017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, bro, ella ... las gafas en casa, por eso confundió al caimán con su perro.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'Nah, bro, ella había dejado las gafas en casa, por eso confundió al caimán con su perro.'::text),
(369149,41017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, elle ... ses lunettes à la maison, c''est pour ça qu''elle a pris l''alligator pour son chien.'::text,'avait laissé'::text,'a laissé'::text,'laisse'::text,'Non frérot, elle avait laissé ses lunettes à la maison, c''est pour ça qu''elle a pris l''alligator pour son chien.'::text),
(369152,41017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, gözlüğünü evde ..., o yüzden timsahı köpeği sandı.'::text,'bırakmıştı'::text,'bıraktı'::text,'bırakır'::text,'Yok kanka, gözlüğünü evde bırakmıştı, o yüzden timsahı köpeği sandı.'::text),
(369153,41017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, otthon ... a szemüvegét, ezért tévesztette össze az aligátort a kutyájával.'::text,'hagyta'::text,'hagyta'::text,'hagyja'::text,'Nem, tesó, otthon hagyta a szemüvegét, ezért tévesztette össze az aligátort a kutyájával.'::text),
(369156,41018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während des Meetings morgen um 9 Uhr ... sie mit dem Alligator Gassi, den sie für ihren Hund hält.'::text,'geht'::text,'wird gehen'::text,'geht'::text,'Während des Meetings morgen um 9 Uhr geht sie mit dem Alligator Gassi, den sie für ihren Hund hält.'::text),
(369160,41018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час завтрашньої наради о 9:00 вона ... алігатора, якого плутає зі своїм собакою.'::text,'вигулюватиме'::text,'вигуляє'::text,'вигулює'::text,'Під час завтрашньої наради о 9:00 вона вигулюватиме алігатора, якого плутає зі своїм собакою.'::text),
(369159,41018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Durante la reunión de mañana a las 9:00, ella ... al caimán que confunde con su perro.'::text,'estará paseando'::text,'paseará'::text,'pasea'::text,'Durante la reunión de mañana a las 9:00, ella estará paseando al caimán que confunde con su perro.'::text),
(369158,41018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant la réunion de demain à 9 h, elle ... l''alligator qu''elle prend pour son chien.'::text,'sera en train de promener'::text,'promènera'::text,'promène'::text,'Pendant la réunion de demain à 9 h, elle sera en train de promener l''alligator qu''elle prend pour son chien.'::text),
(369161,41018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat 9''daki toplantı sırasında, köpeği sandığı timsahı ...'::text,'gezdiriyor olacak'::text,'gezdirecek'::text,'gezdirir'::text,'Yarın saat 9''daki toplantı sırasında, köpeği sandığı timsahı gezdiriyor olacak.'::text),
(369162,41018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A holnapi 9 órás megbeszélés alatt ... azt az aligátort, amelyet a kutyájának hisz.'::text,'éppen sétáltatni fogja'::text,'sétáltatni fogja'::text,'sétáltatja'::text,'A holnapi 9 órás megbeszélés alatt éppen sétáltatni fogja azt az aligátort, amelyet a kutyájának hisz.'::text),
(369165,41019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann sagte, sie ... den Alligator für ihren Hund gehalten, weil es nicht ihr Hund war.'::text,'hätte'::text,'hat'::text,'hält'::text,'Der junge Mann sagte, sie hätte den Alligator für ihren Hund gehalten, weil es nicht ihr Hund war.'::text),
(369169,41019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік сказав, що вона ... алігатора зі своїм собакою, бо це був не її собака.'::text,'сплутала'::text,'сплутала'::text,'плутає'::text,'Молодий чоловік сказав, що вона сплутала алігатора зі своїм собакою, бо це був не її собака.'::text),
(369168,41019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven dijo que ella ... al caimán con su perro, porque no era su perro.'::text,'había confundido'::text,'ha confundido'::text,'confunde'::text,'El joven dijo que ella había confundido al caimán con su perro, porque no era su perro.'::text),
(369167,41019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme a dit qu''elle ... l''alligator pour son chien, parce que ce n''était pas son chien.'::text,'avait pris'::text,'a pris'::text,'prend'::text,'Le jeune homme a dit qu''elle avait pris l''alligator pour son chien, parce que ce n''était pas son chien.'::text),
(369170,41019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam, onun timsahı köpeği ... söyledi, çünkü o onun köpeği değildi.'::text,'sandığını'::text,'sandığını'::text,'sandığını'::text,'Genç adam, onun timsahı köpeği sandığını söyledi, çünkü o onun köpeği değildi.'::text),
(369171,41019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember azt mondta, hogy ... az aligátort a kutyájával, mert az nem az ő kutyája volt.'::text,'összetévesztette'::text,'összetévesztette'::text,'összetéveszti'::text,'A fiatalember azt mondta, hogy összetévesztette az aligátort a kutyájával, mert az nem az ő kutyája volt.'::text),
(369183,41021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat total vergessen, ihre Brille ..., und hat einen Alligator für ihren Hund gehalten!'::text,'mitzunehmen'::text,'mitgenommen zu haben'::text,'mitnehmen'::text,'Sie hat total vergessen, ihre Brille mitzunehmen, und hat einen Alligator für ihren Hund gehalten!'::text),
(369187,41021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона геть забула ... окуляри й сплутала алігатора зі своїм собакою!'::text,'взяти'::text,'що взяла'::text,'взяти'::text,'Вона геть забула взяти окуляри й сплутала алігатора зі своїм собакою!'::text),
(369186,41021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se olvidó por completo de ... las gafas y confundió a un caimán con su perro!'::text,'traer'::text,'haber traído'::text,'traer'::text,'¡Se olvidó por completo de traer las gafas y confundió a un caimán con su perro!'::text),
(369185,41021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a complètement oublié de ... ses lunettes et a pris un alligator pour son chien !'::text,'prendre'::text,'avoir pris'::text,'prendre'::text,'Elle a complètement oublié de prendre ses lunettes et a pris un alligator pour son chien !'::text),
(369188,41021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlüğünü ... tamamen unuttu ve bir timsahı köpeği sandı!'::text,'almayı'::text,'aldığını'::text,'almak'::text,'Gözlüğünü almayı tamamen unuttu ve bir timsahı köpeği sandı!'::text),
(369189,41021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen elfelejtette ... a szemüvegét, és összetévesztett egy aligátort a kutyájával!'::text,'elhozni'::text,'hogy elhozta'::text,'elhoz'::text,'Teljesen elfelejtette elhozni a szemüvegét, és összetévesztett egy aligátort a kutyájával!'::text),
(369192,41022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade einen Alligator Gassi, den sie für ihren Hund hält. Totales Chaos!'::text,'führt'::text,'führt'::text,'hat geführt'::text,'Sie führt gerade einen Alligator Gassi, den sie für ihren Hund hält. Totales Chaos!'::text),
