(376668,41852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat azt javasolta, hogy a megbeszélés alatt 5 percig ... a bögrét az egérre.'::text,'nyomják'::text,'nyomják'::text,'nyomják'::text,'A csapat azt javasolta, hogy a megbeszélés alatt 5 percig nyomják a bögrét az egérre.'::text),
(388173,43131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... dieser Hang der steilste im ganzen Land sein, aber wer weiß.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Mädel, angeblich könnte dieser Hang der steilste im ganzen Land sein, aber wer weiß.'::text),
(388177,43131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, цей схил ... бути найкрутішим у країні, але хто знає.'::text,'може'::text,'мусить'::text,'мав би'::text,'Подруго, кажуть, цей схил може бути найкрутішим у країні, але хто знає.'::text),
(388176,43131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer esa pendiente ... ser la más empinada del país, pero quién sabe.'::text,'podría'::text,'debe de'::text,'debería'::text,'Tía, al parecer esa pendiente podría ser la más empinada del país, pero quién sabe.'::text),
(388175,43131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment cette pente ... être la plus raide du pays, mais qui sait.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Ma belle, apparemment cette pente pourrait être la plus raide du pays, mais qui sait.'::text),
(388178,43131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya o yamaç ülkenin en diki ..., ama kim bilir.'::text,'olabilirmiş'::text,'olmalıymış'::text,'olması gerekirmiş'::text,'Kızım, güya o yamaç ülkenin en diki olabilirmiş, ama kim bilir.'::text),
(388179,43131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az a lejtő ... az ország legmeredekebbje, de ki tudja.'::text,'talán'::text,'biztosan'::text,'elvileg'::text,'Csajszi, állítólag az a lejtő talán az ország legmeredekebbje, de ki tudja.'::text),
(388182,43132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, der Typ, ... den Hang runtergefahren ist, hat das allein gemacht.'::text,'der'::text,'welcher'::text,'dessen'::text,'Hör mal, ich hab gehört, der Typ, der den Hang runtergefahren ist, hat das allein gemacht.'::text),
(388186,43132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що хлопець, ... з''їхав тим схилом на лижах, зробив це сам.'::text,'який'::text,'котрий'::text,'чий'::text,'Слухай, я чула, що хлопець, який з''їхав тим схилом на лижах, зробив це сам.'::text),
(388185,43132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijeron que el chico ... bajó esa pendiente esquiando lo hizo solo.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Oye, me dijeron que el chico que bajó esa pendiente esquiando lo hizo solo.'::text),
(388184,43132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que le mec ... a descendu cette pente à ski l''a fait tout seul.'::text,'qui'::text,'lequel'::text,'dont'::text,'Écoute, j''ai entendu dire que le mec qui a descendu cette pente à ski l''a fait tout seul.'::text),
(388187,43132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki o yamaçtan kayakla ... inen çocuk bunu tek başına yapmış.'::text,''::text,NULL::text,NULL::text,'Dinle, duydum ki o yamaçtan kayakla inen çocuk bunu tek başına yapmış.'::text),
(388188,43132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a srác, ... lesíelt azon a lejtőn, egyedül csinálta.'::text,'aki'::text,'amely'::text,'akinek'::text,'Figyelj, azt hallottam, hogy a srác, aki lesíelt azon a lejtőn, egyedül csinálta.'::text),
(388191,43133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er meinte, der Hang ... ziemlich easy, ohne Witz.'::text,'sei'::text,'wären'::text,'habe'::text,'Digga, er meinte, der Hang sei ziemlich easy, ohne Witz.'::text),
(388195,43133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, він сказав, що той схил ... досить легкий, без приколів.'::text,'був'::text,'були'::text,'має'::text,'Брате, він сказав, що той схил був досить легкий, без приколів.'::text),
(388194,43133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dijo que la pendiente ... bastante fácil, en serio.'::text,'era'::text,'eran'::text,'ha'::text,'Bro, dijo que la pendiente era bastante fácil, en serio.'::text),
(388193,43133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il a dit que la pente ... plutôt facile, sans mentir.'::text,'était'::text,'étaient'::text,'a'::text,'Frérot, il a dit que la pente était plutôt facile, sans mentir.'::text),
(388196,43133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yamacın bayağı kolay ... söyledi, yemin ederim.'::text,'olduğunu'::text,'olduklarını'::text,NULL::text,'Kanka, yamacın bayağı kolay olduğunu söyledi, yemin ederim.'::text),
(388197,43133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy a lejtő elég könnyű ..., komolyan.'::text,''::text,'voltak'::text,'van'::text,'Tesó, azt mondta, hogy a lejtő elég könnyű, komolyan.'::text),
(388200,43134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... auf kleineren Hängen Ski, bevor er diesen ausprobierte.'::text,'fuhr früher'::text,'war es gewohnt'::text,'fuhr früher'::text,'Er fuhr früher auf kleineren Hängen Ski, bevor er diesen ausprobierte.'::text),
(388204,43134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на лижах на менших схилах, перш ніж спробував цей.'::text,'катався раніше'::text,'звик кататися'::text,'катався раніше'::text,'Він катався раніше на лижах на менших схилах, перш ніж спробував цей.'::text),
(388203,43134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... esquiar en pendientes más pequeñas antes de probar esta.'::text,'solía'::text,'estaba acostumbrado a'::text,'solía'::text,'Él solía esquiar en pendientes más pequeñas antes de probar esta.'::text),
(388202,43134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... skier sur de plus petites pentes avant d''essayer celle-ci.'::text,'avait l''habitude de'::text,'était habitué à'::text,'avait l''habitude de'::text,'Il avait l''habitude de skier sur de plus petites pentes avant d''essayer celle-ci.'::text),
(388205,43134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bunu denemeden önce daha küçük yamaçlarda ...'::text,'kayardı'::text,'kaymaya alışkındı'::text,'kayardı'::text,'Bunu denemeden önce daha küçük yamaçlarda kayardı.'::text),
(388206,43134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korábban kisebb lejtőkön ..., mielőtt ezt kipróbálta.'::text,'síelt'::text,'hozzászokott a síeléshez'::text,'síelt'::text,'Korábban kisebb lejtőkön síelt, mielőtt ezt kipróbálta.'::text),
(388209,43135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat keine Angst, einen so steilen Hang ...'::text,'hinunterzufahren'::text,'hinunterzufahren'::text,'hinunterfahren'::text,'Er hat keine Angst, einen so steilen Hang hinunterzufahren.'::text),
(388213,43135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не боїться ... таким крутим схилом.'::text,'спускатися'::text,'спускатися'::text,'спускатися'::text,'Він не боїться спускатися таким крутим схилом.'::text),
(388212,43135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No tiene miedo de ... por una pendiente tan empinada.'::text,'bajar esquiando'::text,'bajar esquiando'::text,'bajar esquiando'::text,'No tiene miedo de bajar esquiando por una pendiente tan empinada.'::text),
(388211,43135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''a pas peur de ... une pente aussi raide.'::text,'descendre à ski'::text,'descendre à ski'::text,'descendre à ski'::text,'Il n''a pas peur de descendre à ski une pente aussi raide.'::text),
(388214,43135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar dik bir yamaçtan kayakla ... korkmuyor.'::text,'inmekten'::text,'inmeye'::text,'inmek'::text,'Bu kadar dik bir yamaçtan kayakla inmekten korkmuyor.'::text),
(388215,43135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fél ... egy ilyen meredek lejtőn.'::text,'lesíelni'::text,'lesíelni'::text,'lesíelni'::text,'Nem fél lesíelni egy ilyen meredek lejtőn.'::text),
(388227,43137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hang ist überhaupt nicht gruselig, klar, und ...'::text,'der Abgrund zum Wasser auch nicht'::text,'der Abgrund zum Wasser auch'::text,'der Abgrund zum Wasser auch nicht'::text,'Der Hang ist überhaupt nicht gruselig, klar, und der Abgrund zum Wasser auch nicht.'::text),
(388231,43137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схил зовсім не страшний, звісно, і ...'::text,'обрив до води теж ні'::text,'обрив до води теж'::text,'обрив до води теж ні'::text,'Схил зовсім не страшний, звісно, і обрив до води теж ні.'::text),
(388230,43137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pendiente no da nada de miedo, claro, y ...'::text,'la caída al agua tampoco'::text,'la caída al agua también'::text,'la caída al agua tampoco'::text,'La pendiente no da nada de miedo, claro, y la caída al agua tampoco.'::text),
(388229,43137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pente n''est pas du tout effrayante, évidemment, et ...'::text,'la chute vers l''eau non plus'::text,'la chute vers l''eau aussi'::text,'la chute vers l''eau non plus'::text,'La pente n''est pas du tout effrayante, évidemment, et la chute vers l''eau non plus.'::text),
(388232,43137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yamaç hiç korkutucu değil, belli ki, ve ...'::text,'suya inen uçurum da değil'::text,'suya inen uçurum da öyle'::text,'suya inen uçurum da değil'::text,'Yamaç hiç korkutucu değil, belli ki, ve suya inen uçurum da değil.'::text),
(388233,43137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lejtő egyáltalán nem ijesztő, nyilván, és ...'::text,'a vízhez vezető szakadék sem'::text,'a vízhez vezető szakadék is'::text,'a vízhez vezető szakadék sem'::text,'A lejtő egyáltalán nem ijesztő, nyilván, és a vízhez vezető szakadék sem.'::text),
(388236,43138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... erst zehn Minuten den Hang hinunter, als die Sonne unterging. Kaum ein Workout.'::text,'fuhr'::text,'ist gefahren'::text,'fährt'::text,'Er fuhr erst zehn Minuten den Hang hinunter, als die Sonne unterging. Kaum ein Workout.'::text),
(388240,43138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... схилом лише десять хвилин, перш ніж сонце сіло. Навряд чи тренування.'::text,'катався'::text,'катається'::text,'катається'::text,'Він катався схилом лише десять хвилин, перш ніж сонце сіло. Навряд чи тренування.'::text),
(388239,43138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él solo ... por la pendiente diez minutos antes de que se pusiera el sol. Menudo entrenamiento.'::text,'había estado esquiando'::text,'ha estado esquiando'::text,'está esquiando'::text,'Él solo había estado esquiando por la pendiente diez minutos antes de que se pusiera el sol. Menudo entrenamiento.'::text),
(388238,43138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur la pente depuis seulement dix minutes quand le soleil s''est couché. Pas vraiment un entraînement.'::text,'skiait'::text,'skie'::text,'skie'::text,'Il skiait sur la pente depuis seulement dix minutes quand le soleil s''est couché. Pas vraiment un entraînement.'::text),
(388241,43138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş batmadan önce yamaçta sadece on dakika ..., pek de antrenman sayılmaz.'::text,'kaymıştı'::text,'kaydı'::text,'kayıyor'::text,'Güneş batmadan önce yamaçta sadece on dakika kaymıştı, pek de antrenman sayılmaz.'::text),
(388242,43138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindössze tíz percig ... a lejtőn, mielőtt lement a nap. Aligha edzés.'::text,'síelt'::text,'síel'::text,'síel'::text,'Mindössze tíz percig síelt a lejtőn, mielőtt lement a nap. Aligha edzés.'::text),
(388254,43140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang wird er drei Stunden lang auf diesem furchterregenden Hang ...!'::text,'Ski gefahren sein'::text,'Ski fahren'::text,'Ski fahren'::text,'Bis zum Sonnenuntergang wird er drei Stunden lang auf diesem furchterregenden Hang Ski gefahren sein!'::text),
(388258,43140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... цим жахливим схилом уже три години!'::text,'катиметься'::text,'катиметься'::text,'катиметься'::text,'До заходу сонця він катиметься цим жахливим схилом уже три години!'::text),
(388257,43140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer, él ... por esta pendiente aterradora durante tres horas!'::text,'habrá estado esquiando'::text,'esquiará'::text,'estará esquiando'::text,'¡Para el atardecer, él habrá estado esquiando por esta pendiente aterradora durante tres horas!'::text),
(388256,43140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, il ... sur cette pente terrifiante depuis trois heures !'::text,'aura skié'::text,'skiera'::text,'sera en train de skier'::text,'Au coucher du soleil, il aura skié sur cette pente terrifiante depuis trois heures !'::text),
(388259,43140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu korkunç yamaçta üç saattir ...!'::text,'kayıyor olacak'::text,'kayacak'::text,'kayıyor olacak'::text,'Gün batımına kadar bu korkunç yamaçta üç saattir kayıyor olacak!'::text),
(388260,43140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára már három órája ... ezen a félelmetes lejtőn!'::text,'síel'::text,'síelni fog'::text,'síelni fog'::text,'Napnyugtára már három órája síel ezen a félelmetes lejtőn!'::text),
(388263,43141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Schnee abgerutscht, ... sich der Hang in eine totale Katastrophe verwandelt!'::text,'hätte'::text,'wird'::text,'verwandelte'::text,'Wäre der Schnee abgerutscht, hätte sich der Hang in eine totale Katastrophe verwandelt!'::text),
(388267,43141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сніг зсунувся, схил ... на повну катастрофу!'::text,'перетворився б'::text,'перетвориться'::text,'перетворився'::text,'Якби сніг зсунувся, схил перетворився б на повну катастрофу!'::text),
(388266,43141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la nieve se hubiera deslizado, la pendiente ... en un desastre total!'::text,'se habría convertido'::text,'se convertirá'::text,'se convirtió'::text,'¡Si la nieve se hubiera deslizado, la pendiente se habría convertido en un desastre total!'::text),
(388265,43141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la neige avait glissé, la pente ... en véritable catastrophe !'::text,'se serait transformée'::text,'se transformera'::text,'s''est transformée'::text,'Si la neige avait glissé, la pente se serait transformée en véritable catastrophe !'::text),
(388268,43141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kar kaysaydı yamaç tam bir felakete ...!'::text,'dönüşürdü'::text,'dönüşecek'::text,'dönüştü'::text,'Kar kaysaydı yamaç tam bir felakete dönüşürdü!'::text),
(388269,43141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hó megcsúszott volna, a lejtő teljes katasztrófává ...!'::text,'vált volna'::text,'válik majd'::text,'vált'::text,'Ha a hó megcsúszott volna, a lejtő teljes katasztrófává vált volna!'::text),
(353514,39280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Adler morgen wieder hier fischt, ... er noch einen silbernen Fisch.'::text,'fängt'::text,'würde fangen'::text,'fing'::text,'Wenn der Adler morgen wieder hier fischt, fängt er noch einen silbernen Fisch.'::text),
(353518,39280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо орел завтра знову рибалитиме тут, він ... ще одну срібну рибу.'::text,'спіймає'::text,'спіймав би'::text,'спіймав'::text,'Якщо орел завтра знову рибалитиме тут, він спіймає ще одну срібну рибу.'::text),
(353517,39280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el águila vuelve a pescar aquí mañana, ... otro pez plateado.'::text,'atrapará'::text,'atraparía'::text,'atrapó'::text,'Si el águila vuelve a pescar aquí mañana, atrapará otro pez plateado.'::text),
(353516,39280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''aigle pêche encore ici demain, il ... un autre poisson argenté.'::text,'attrapera'::text,'attraperait'::text,'attrapa'::text,'Si l''aigle pêche encore ici demain, il attrapera un autre poisson argenté.'::text),
(353519,39280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kartal yarın yine burada balık avlarsa, bir gümüş balık daha ...'::text,'yakalayacak'::text,'yakalardı'::text,'yakaladı'::text,'Kartal yarın yine burada balık avlarsa, bir gümüş balık daha yakalayacak.'::text),
(353520,39280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sas holnap is itt halászik, ... még egy ezüstös halat.'::text,'fog'::text,'fogna'::text,'fogott'::text,'Ha a sas holnap is itt halászik, fog még egy ezüstös halat.'::text),
(353523,39281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre das Wasser unruhig, ... der Adler nicht so dicht über der Oberfläche.'::text,'jagte'::text,'wird jagen'::text,'jagte'::text,'Wäre das Wasser unruhig, jagte der Adler nicht so dicht über der Oberfläche.'::text),
(353527,39281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вода була бурхливою, орел ... так близько до поверхні.'::text,'не рибалив би'::text,'не рибалитиме'::text,'не рибалив'::text,'Якби вода була бурхливою, орел не рибалив би так близько до поверхні.'::text),
(353526,39281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el agua estuviera agitada, el águila ... tan cerca de la superficie.'::text,'no pescaría'::text,'no pescará'::text,'no pescó'::text,'Si el agua estuviera agitada, el águila no pescaría tan cerca de la superficie.'::text),
(353525,39281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''eau était agitée, l''aigle ... si près de la surface.'::text,'ne pêcherait pas'::text,'ne pêchera pas'::text,'n''a pas pêché'::text,'Si l''eau était agitée, l''aigle ne pêcherait pas si près de la surface.'::text),
(353528,39281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su dalgalı olsaydı kartal yüzeye bu kadar yakın ...'::text,'avlanmazdı'::text,'avlanmayacak'::text,'avlanmadı'::text,'Su dalgalı olsaydı kartal yüzeye bu kadar yakın avlanmazdı.'::text),
(353529,39281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha háborgós lenne a víz, a sas ... ilyen közel a felszínhez.'::text,'nem halászna'::text,'nem fog halászni'::text,'nem halászott'::text,'Ha háborgós lenne a víz, a sas nem halászna ilyen közel a felszínhez.'::text),
(353532,39282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fisch ... aus dem Wasser gezogen, weil der Adler fischte.'::text,'wurde'::text,'zog'::text,'wird'::text,'Der Fisch wurde aus dem Wasser gezogen, weil der Adler fischte.'::text),
(353536,39282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рибу ... з води, бо орел рибалив.'::text,'витягли'::text,'витягла'::text,'витягують'::text,'Рибу витягли з води, бо орел рибалив.'::text),
(353535,39282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pez ... del agua porque el águila estaba pescando.'::text,'fue sacado'::text,'sacó'::text,'es sacado'::text,'El pez fue sacado del agua porque el águila estaba pescando.'::text),
(353534,39282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poisson ... de l''eau parce que l''aigle pêchait.'::text,'a été tiré'::text,'a tiré'::text,'est tiré'::text,'Le poisson a été tiré de l''eau parce que l''aigle pêchait.'::text),
(353537,39282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kartal balık avladığı için balık sudan ...'::text,'çıkarıldı'::text,'çıkardı'::text,'çıkarılır'::text,'Kartal balık avladığı için balık sudan çıkarıldı.'::text),
(353538,39282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A halat ... a vízből, mert a sas halászott.'::text,'kihúzták'::text,'kihúzta'::text,'kihúzzák'::text,'A halat kihúzták a vízből, mert a sas halászott.'::text),
(353541,39283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... der Adler hier jeden Morgen, und die Fische sehen ihn nie kommen.'::text,'fischt'::text,'wird gefischt'::text,'fischend'::text,'Bestie, angeblich fischt der Adler hier jeden Morgen, und die Fische sehen ihn nie kommen.'::text),
(353545,39283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, орел тут щоранку ..., і риба ніколи не бачить його наближення.'::text,'рибалить'::text,'виловлюється'::text,'рибалячи'::text,'Подруго, кажуть, орел тут щоранку рибалить, і риба ніколи не бачить його наближення.'::text),
(353544,39283,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dicen que el águila ... aquí todas las mañanas y los peces nunca la ven venir.'::text,'pesca'::text,'es pescada'::text,'pescando'::text,'Amiga, dicen que el águila pesca aquí todas las mañanas y los peces nunca la ven venir.'::text),
(353543,39283,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que l''aigle ... ici tous les matins, et les poissons ne le voient jamais venir.'::text,'pêche'::text,'est pêché'::text,'pêchant'::text,'Ma belle, il paraît que l''aigle pêche ici tous les matins, et les poissons ne le voient jamais venir.'::text),
(353546,39283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dediklerine göre kartal her sabah burada ... ve balıklar onun geldiğini hiç görmüyor.'::text,'balık avlıyormuş'::text,'avlanıyormuş'::text,'balık avlayarak'::text,'Kanka, dediklerine göre kartal her sabah burada balık avlıyormuş ve balıklar onun geldiğini hiç görmüyor.'::text),
(353547,39283,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a sas minden reggel itt ..., és a halak sosem látják jönni.'::text,'halászik'::text,'halásszák'::text,'halászva'::text,'Csajszi, állítólag a sas minden reggel itt halászik, és a halak sosem látják jönni.'::text),
(353550,39284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er hat mir gesagt, der Adler ... morgen wieder hier fischen, aber keiner weiß es sicher.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Hör mal, er hat mir gesagt, der Adler könnte morgen wieder hier fischen, aber keiner weiß es sicher.'::text),
(353554,39284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що орел ... знову рибалити тут завтра, але ніхто точно не знає.'::text,'може'::text,'мусить'::text,'не може'::text,'Слухай, він сказав мені, що орел може знову рибалити тут завтра, але ніхто точно не знає.'::text),
(353553,39284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que el águila ... pescar aquí otra vez mañana, pero nadie lo sabe seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Oye, me dijo que el águila podría pescar aquí otra vez mañana, pero nadie lo sabe seguro.'::text),
(353552,39284,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que l''aigle ... pêcher ici encore demain, mais personne n''en est sûr.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Écoute, il m''a dit que l''aigle pourrait pêcher ici encore demain, mais personne n''en est sûr.'::text),
(353555,39284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana kartalın yarın yine burada balık ... söyledi, ama kimse kesin bilmiyor.'::text,'avlayabileceğini'::text,'avlaması gerektiğini'::text,'avlayamayacağını'::text,'Dinle, bana kartalın yarın yine burada balık avlayabileceğini söyledi, ama kimse kesin bilmiyor.'::text),
(353556,39284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a sas holnap ... megint itt halászik, de senki sem tudja biztosan.'::text,'talán'::text,'biztosan'::text,'biztosan nem'::text,'Figyelj, azt mondta, hogy a sas holnap talán megint itt halászik, de senki sem tudja biztosan.'::text),
(353568,39286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Guide sagte, der Adler ... stundenlang gefischt. Es dauerte zehn Sekunden. Wirklich anstrengende Arbeit.'::text,'hätte'::text,'hat'::text,'fischt'::text,'Der Guide sagte, der Adler hätte stundenlang gefischt. Es dauerte zehn Sekunden. Wirklich anstrengende Arbeit.'::text),
(353572,39286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід сказав, що орел ... годинами. Це тривало десять секунд. Справді виснажлива робота.'::text,'рибалив'::text,'рибалив'::text,'рибалить'::text,'Гід сказав, що орел рибалив годинами. Це тривало десять секунд. Справді виснажлива робота.'::text),
(353571,39286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guía dijo que el águila ... durante horas. Tardó diez segundos. Un trabajo realmente agotador.'::text,'había estado pescando'::text,'ha estado pescando'::text,'está pescando'::text,'El guía dijo que el águila había estado pescando durante horas. Tardó diez segundos. Un trabajo realmente agotador.'::text),
(353570,39286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guide a dit que l''aigle ... depuis des heures. Ça a pris dix secondes. Un travail vraiment épuisant.'::text,'pêchait'::text,'pêche'::text,'pêche'::text,'Le guide a dit que l''aigle pêchait depuis des heures. Ça a pris dix secondes. Un travail vraiment épuisant.'::text),
(353573,39286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber, kartalın saatlerdir ... söyledi. On saniye sürdü. Gerçekten yorucu bir iş.'::text,'balık avladığını'::text,'balık avladığını'::text,'balık avladığını'::text,'Rehber, kartalın saatlerdir balık avladığını söyledi. On saniye sürdü. Gerçekten yorucu bir iş.'::text),
(353577,39287,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, früher ... mein Opa hier jeden Tag angeln, weil es keine Adler gab.'::text,'ging'::text,'ging'::text,'war gewohnt'::text,'Digga, früher ging mein Opa hier jeden Tag angeln, weil es keine Adler gab.'::text),
(353581,39287,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, колись мій дід ... тут щодня, бо орлів тут не було.'::text,'рибалив'::text,'рибалив'::text,'звик рибалити'::text,'Брате, колись мій дід рибалив тут щодня, бо орлів тут не було.'::text),
(353580,39287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, antes mi abuelo ... aquí a diario, porque no había águilas.'::text,'pescaba'::text,'pescaba'::text,'estaba acostumbrado a pescar'::text,'Bro, antes mi abuelo pescaba aquí a diario, porque no había águilas.'::text),
(353579,39287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, à l''époque mon grand-père ... ici tous les jours, parce qu''il n''y avait pas d''aigles.'::text,'pêchait'::text,'pêchait'::text,'avait l''habitude de pêcher'::text,'Frérot, à l''époque mon grand-père pêchait ici tous les jours, parce qu''il n''y avait pas d''aigles.'::text),
(353582,39287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden dedem burada her gün ..., çünkü etrafta kartal yoktu.'::text,'balık tutardı'::text,'balık tutardı'::text,'balık tutmaya alışkındı'::text,'Kanka, eskiden dedem burada her gün balık tutardı, çünkü etrafta kartal yoktu.'::text),
(353583,39287,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, régen a nagyapám itt ... naponta, mert nem voltak errefelé sasok.'::text,'horgászott'::text,'horgászott'::text,'hozzá volt szokva a horgászáshoz'::text,'Tesó, régen a nagyapám itt horgászott naponta, mert nem voltak errefelé sasok.'::text),
(353586,39288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Adler wird hier weiter ..., bis kein Fisch mehr übrig ist, echt.'::text,'fischen'::text,'fischen'::text,'fischen'::text,'Digga, der Adler wird hier weiter fischen, bis kein Fisch mehr übrig ist, echt.'::text),
(353590,39288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, той орел і далі ... тут, поки не залишиться жодної риби, реально.'::text,'рибалитиме'::text,'рибалитиме'::text,'рибалитиме'::text,'Чувак, той орел і далі рибалитиме тут, поки не залишиться жодної риби, реально.'::text),
(353589,39288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esa águila va a seguir ... aquí hasta que no quede ni un pez, en serio.'::text,'pescando'::text,'pescar'::text,'pescar'::text,'Tío, esa águila va a seguir pescando aquí hasta que no quede ni un pez, en serio.'::text),
(353588,39288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, cet aigle va continuer à ... ici jusqu''à ce qu''il n''y ait plus de poissons, grave.'::text,'pêcher'::text,'pêcher'::text,'pêcher'::text,'Mec, cet aigle va continuer à pêcher ici jusqu''à ce qu''il n''y ait plus de poissons, grave.'::text),
(353591,39288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kartal hiç balık kalmayana kadar burada ... devam edecek, cidden.'::text,'avlanmaya'::text,'avlanmaya'::text,'avlanmak'::text,'Kanka, o kartal hiç balık kalmayana kadar burada avlanmaya devam edecek, cidden.'::text),
(353592,39288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a sas addig ... itt, amíg egy hal sem marad, komolyan.'::text,'halászik tovább'::text,'halászik tovább'::text,'halászik tovább'::text,'Tesó, az a sas addig halászik tovább itt, amíg egy hal sem marad, komolyan.'::text),
(353595,39289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Adler ... hier 3-mal am Tag, deutlich über dem Ziel.'::text,'fischt'::text,'fischt'::text,'hat gefischt'::text,'Der Adler fischt hier 3-mal am Tag, deutlich über dem Ziel.'::text),
(353599,39289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Орел ... тут 3 рази на день, значно вище за ціль.'::text,'рибалить'::text,'рибалить'::text,'рибалив'::text,'Орел рибалить тут 3 рази на день, значно вище за ціль.'::text),
(353598,39289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El águila ... aquí 3 veces al día, muy por encima del objetivo.'::text,'pesca'::text,'está pescando'::text,'ha pescado'::text,'El águila pesca aquí 3 veces al día, muy por encima del objetivo.'::text),
(353597,39289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''aigle ... ici 3 fois par jour, bien au-dessus de l''objectif.'::text,'pêche'::text,'pêche'::text,'a pêché'::text,'L''aigle pêche ici 3 fois par jour, bien au-dessus de l''objectif.'::text),
(353600,39289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kartal burada günde 3 kez ..., hedefin çok üstünde.'::text,'avlanır'::text,'avlanıyor'::text,'avlandı'::text,'Kartal burada günde 3 kez avlanır, hedefin çok üstünde.'::text),
(353601,39289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sas naponta 3-szor ... itt, jóval a cél felett.'::text,'halászik'::text,'halászik'::text,'halászott'::text,'A sas naponta 3-szor halászik itt, jóval a cél felett.'::text),
(399495,44389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Besitzer keine Tiefgarage gebaut hätte, ... das Auto jetzt draußen.'::text,'stünde'::text,'hätte gestanden'::text,'wird stehen'::text,'Wenn der Besitzer keine Tiefgarage gebaut hätte, stünde das Auto jetzt draußen.'::text),
(399499,44389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби власник не збудував підземний гараж, машина ... зараз надворі.'::text,'стояла б'::text,'стояла б'::text,'стоятиме'::text,'Якби власник не збудував підземний гараж, машина стояла б зараз надворі.'::text),
(399498,44389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el dueño no hubiera construido un garaje subterráneo, el coche ... fuera ahora.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si el dueño no hubiera construido un garaje subterráneo, el coche estaría fuera ahora.'::text),
(399497,44389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le propriétaire n''avait pas construit de garage souterrain, la voiture ... dehors maintenant.'::text,'serait garée'::text,'aurait été garée'::text,'sera garée'::text,'Si le propriétaire n''avait pas construit de garage souterrain, la voiture serait garée dehors maintenant.'::text),
(399500,44389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi yeraltı garajı yapmasaydı, araba şu an dışarıda ...'::text,'duruyor olurdu'::text,'durmuş olurdu'::text,'duracak'::text,'Sahibi yeraltı garajı yapmasaydı, araba şu an dışarıda duruyor olurdu.'::text),
(399501,44389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tulajdonos nem épített volna mélygarázst, az autó most kint ...'::text,'állna'::text,'állt volna'::text,'állni fog'::text,'Ha a tulajdonos nem épített volna mélygarázst, az autó most kint állna.'::text),
(399504,44390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tiefgarage soll vor Jahren unter der Einfahrt ...'::text,'gebaut worden sein'::text,'bauen'::text,'bauend'::text,'Die Tiefgarage soll vor Jahren unter der Einfahrt gebaut worden sein.'::text),
(399508,44390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що підземний гараж ... під під''їзною доріжкою багато років тому.'::text,'збудували'::text,'збудувати'::text,'будівництво'::text,'Вважається, що підземний гараж збудували під під''їзною доріжкою багато років тому.'::text),
(399507,44390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el garaje subterráneo ... bajo la entrada hace años.'::text,'fue construido'::text,'construir'::text,'construyendo'::text,'Se cree que el garaje subterráneo fue construido bajo la entrada hace años.'::text),
(399506,44390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le garage souterrain ... sous l''allée il y a des années.'::text,'a été construit'::text,'construire'::text,'construisant'::text,'On pense que le garage souterrain a été construit sous l''allée il y a des années.'::text),
(399509,44390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeraltı garajının yıllar önce araba yolunun altına ... düşünülüyor.'::text,'inşa edildiği'::text,'inşa etmek'::text,'inşa ederek'::text,'Yeraltı garajının yıllar önce araba yolunun altına inşa edildiği düşünülüyor.'::text),
(399510,44390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy a mélygarázst évekkel ezelőtt ... a kocsibeálló alá.'::text,'építették'::text,'építeni'::text,'építve'::text,'Úgy tartják, hogy a mélygarázst évekkel ezelőtt építették a kocsibeálló alá.'::text),
(399513,44391,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer bestritt, eine Tiefgarage ... zu haben. Dann öffnete sich die ganze Einfahrt!'::text,'gebaut'::text,'bauen'::text,'baute'::text,'Der Besitzer bestritt, eine Tiefgarage gebaut zu haben. Dann öffnete sich die ganze Einfahrt!'::text),
(399517,44391,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник заперечив, що ... підземний гараж. А потім відкрилася вся під''їзна доріжка!'::text,'збудував'::text,'збудувати'::text,'збудував'::text,'Власник заперечив, що збудував підземний гараж. А потім відкрилася вся під''їзна доріжка!'::text),
(399516,44391,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño negó ... un garaje subterráneo. ¡Entonces se abrió toda la entrada!'::text,'haber construido'::text,'construir'::text,'construyó'::text,'El dueño negó haber construido un garaje subterráneo. ¡Entonces se abrió toda la entrada!'::text),
(399515,44391,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire a nié ... un garage souterrain. Puis toute l''allée s''est ouverte !'::text,'avoir construit'::text,'construire'::text,'construit'::text,'Le propriétaire a nié avoir construit un garage souterrain. Puis toute l''allée s''est ouverte !'::text),
(399518,44391,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi bir yeraltı garajı ... inkâr etti. Sonra bütün araba yolu açıldı!'::text,'yaptırdığını'::text,'yaptırmayı'::text,'yaptırdı'::text,'Sahibi bir yeraltı garajı yaptırdığını inkâr etti. Sonra bütün araba yolu açıldı!'::text),
(399519,44391,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tulajdonos tagadta, hogy ... mélygarázst. Aztán kinyílt az egész kocsibeálló!'::text,'épített'::text,'építeni'::text,'épített'::text,'A tulajdonos tagadta, hogy épített mélygarázst. Aztán kinyílt az egész kocsibeálló!'::text),
(399522,44392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jemand ... für diese Tiefgarage ein Vermögen ausgegeben haben. Unglaublich!'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Jemand muss für diese Tiefgarage ein Vermögen ausgegeben haben. Unglaublich!'::text),
(399526,44392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хтось ... цілий статок на цей підземний гараж. Неймовірно!'::text,'напевно витратив'::text,'мав витратити'::text,'не міг витратити'::text,'Хтось напевно витратив цілий статок на цей підземний гараж. Неймовірно!'::text),
(399525,44392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alguien ... gastado una fortuna en este garaje subterráneo. ¡Increíble!'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'Alguien debe de haber gastado una fortuna en este garaje subterráneo. ¡Increíble!'::text),
(399524,44392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelqu''un ... dépenser une fortune pour ce garage souterrain. Incroyable !'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Quelqu''un a dû dépenser une fortune pour ce garage souterrain. Incroyable !'::text),
(399527,44392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri bu yeraltı garajına bir servet ..., inanılmaz!'::text,'harcamış olmalı'::text,'harcamalıydı'::text,'harcamış olamaz'::text,'Biri bu yeraltı garajına bir servet harcamış olmalı, inanılmaz!'::text),
(399528,44392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valaki ... egy vagyont erre a mélygarázsra. Hihetetlen!'::text,'biztosan elköltött'::text,'el kellett volna költenie'::text,'nem költhetett el'::text,'Valaki biztosan elköltött egy vagyont erre a mélygarázsra. Hihetetlen!'::text),
(399531,44393,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... öffnet sich die Einfahrt, sondern sie verbirgt auch eine Tiefgarage.'::text,''::text,NULL::text,'ist'::text,'Nicht nur öffnet sich die Einfahrt, sondern sie verbirgt auch eine Tiefgarage.'::text),
(399535,44393,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під''їзна доріжка не лише ... відкривається, а й приховує підземний гараж.'::text,''::text,NULL::text,'є'::text,'Під''їзна доріжка не лише відкривається, а й приховує підземний гараж.'::text),
(399534,44393,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... se abre la entrada, sino que también esconde un garaje subterráneo.'::text,''::text,NULL::text,'es'::text,'No solo se abre la entrada, sino que también esconde un garaje subterráneo.'::text),
(399533,44393,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement l''allée ... s''ouvre, mais elle cache aussi un garage souterrain.'::text,''::text,NULL::text,'est'::text,'Non seulement l''allée s''ouvre, mais elle cache aussi un garage souterrain.'::text),
(399536,44393,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba yolu sadece ... açılmakla kalmıyor, bir yeraltı garajı da saklıyor.'::text,''::text,NULL::text,NULL::text,'Araba yolu sadece açılmakla kalmıyor, bir yeraltı garajı da saklıyor.'::text),
(399537,44393,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... kinyílik a kocsibeálló, hanem egy mélygarázst is rejt.'::text,''::text,NULL::text,'van'::text,'Nemcsak kinyílik a kocsibeálló, hanem egy mélygarázst is rejt.'::text),
(399540,44394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ließ unter seiner Einfahrt eine Tiefgarage ..., offensichtlich eine ganz normale Wahl.'::text,'bauen'::text,'bauen'::text,'bauen'::text,'Er ließ unter seiner Einfahrt eine Tiefgarage bauen, offensichtlich eine ganz normale Wahl.'::text),
(399544,44394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він звелів ... підземний гараж під своєю під''їзною доріжкою. Очевидно, цілком звичайний вибір.'::text,'збудувати'::text,'збудувати'::text,'збудувати'::text,'Він звелів збудувати підземний гараж під своєю під''їзною доріжкою. Очевидно, цілком звичайний вибір.'::text),
(399543,44394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se hizo ... un garaje subterráneo bajo la entrada. Obviamente, una elección normal.'::text,'construir'::text,'construir'::text,'construir'::text,'Se hizo construir un garaje subterráneo bajo la entrada. Obviamente, una elección normal.'::text),
(399542,44394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il s''est fait ... un garage souterrain sous son allée. Évidemment, un choix tout à fait normal.'::text,'construire'::text,'construire'::text,'construire'::text,'Il s''est fait construire un garage souterrain sous son allée. Évidemment, un choix tout à fait normal.'::text),
(399545,44394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba yolunun altına bir yeraltı garajı ..., belli ki gayet normal bir tercih.'::text,'yaptırdı'::text,'yaptırdı'::text,'yaptırdı'::text,'Araba yolunun altına bir yeraltı garajı yaptırdı, belli ki gayet normal bir tercih.'::text),
(399546,44394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kocsibeállója alá mélygarázst ..., nyilván teljesen normális döntés.'::text,'építtetett'::text,'építtetett'::text,'építtetett'::text,'A kocsibeállója alá mélygarázst építtetett, nyilván teljesen normális döntés.'::text),
(399558,44396,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tiefgarage, ... Budget 200.000 Euro betrug, hat orangefarbene Lichter.'::text,'deren'::text,'die'::text,'welche'::text,'Die Tiefgarage, deren Budget 200.000 Euro betrug, hat orangefarbene Lichter.'::text),
(399562,44396,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підземний гараж, ... бюджет становив 200 000 євро, має помаранчеві лампи.'::text,'чий'::text,'який'::text,'котрий'::text,'Підземний гараж, чий бюджет становив 200 000 євро, має помаранчеві лампи.'::text),
(399561,44396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El garaje subterráneo, ... presupuesto fue de 200 000 euros, tiene luces naranjas.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El garaje subterráneo, cuyo presupuesto fue de 200 000 euros, tiene luces naranjas.'::text),
(399560,44396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garage souterrain, ... le budget était de 200 000 euros, a des lumières orange.'::text,'dont'::text,'qui'::text,'que'::text,'Le garage souterrain, dont le budget était de 200 000 euros, a des lumières orange.'::text),
(399563,44396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bütçesi 200.000 avro olan yeraltı garajında turuncu ışıklar var.'::text,''::text,NULL::text,NULL::text,'Bütçesi 200.000 avro olan yeraltı garajında turuncu ışıklar var.'::text),
(399564,44396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mélygarázs, ... költségvetése 200 000 euró volt, narancssárga lámpákkal rendelkezik.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A mélygarázs, amelynek a költségvetése 200 000 euró volt, narancssárga lámpákkal rendelkezik.'::text),
(399567,44397,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des starken Regens wurde die Tiefgarage vor der Q3-Deadline fertiggestellt.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des starken Regens wurde die Tiefgarage vor der Q3-Deadline fertiggestellt.'::text),
(399571,44397,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... сильний дощ, підземний гараж завершили до дедлайну Q3.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри сильний дощ, підземний гараж завершили до дедлайну Q3.'::text),
(399570,44397,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la fuerte lluvia, el garaje subterráneo se terminó antes de la fecha límite del T3.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de la fuerte lluvia, el garaje subterráneo se terminó antes de la fecha límite del T3.'::text),
(399569,44397,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la forte pluie, le garage souterrain a été terminé avant l''échéance du T3.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré la forte pluie, le garage souterrain a été terminé avant l''échéance du T3.'::text),
(399572,44397,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şiddetli yağmura ..., yeraltı garajı 3. çeyrek teslim tarihinden önce tamamlandı.'::text,'rağmen'::text,'olsa da'::text,'yüzünden'::text,'Şiddetli yağmura rağmen, yeraltı garajı 3. çeyrek teslim tarihinden önce tamamlandı.'::text),
(399573,44397,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A heves eső ... a mélygarázs elkészült a Q3-as határidő előtt.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A heves eső ellenére a mélygarázs elkészült a Q3-as határidő előtt.'::text),
(399576,44398,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer wusste, dass das Auto in der Tiefgarage sicher ...'::text,'sein würde'::text,'sein wird'::text,'ist'::text,'Der Besitzer wusste, dass das Auto in der Tiefgarage sicher sein würde.'::text),
(399580,44398,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник знав, що машина ... в безпеці в підземному гаражі.'::text,'буде'::text,'буде'::text,NULL::text,'Власник знав, що машина буде в безпеці в підземному гаражі.'::text),
(399579,44398,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño sabía que el coche ... a salvo en el garaje subterráneo.'::text,'estaría'::text,'estará'::text,'está siendo'::text,'El dueño sabía que el coche estaría a salvo en el garaje subterráneo.'::text),
(399578,44398,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire savait que la voiture ... en sécurité dans le garage souterrain.'::text,'serait'::text,'sera'::text,'est'::text,'Le propriétaire savait que la voiture serait en sécurité dans le garage souterrain.'::text),
(399581,44398,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi arabanın yeraltı garajında güvende ... biliyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Sahibi arabanın yeraltı garajında güvende olacağını biliyordu.'::text),
(399582,44398,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tulajdonos tudta, hogy az autó biztonságban ... a mélygarázsban.'::text,'lesz'::text,'lesz'::text,'van'::text,'A tulajdonos tudta, hogy az autó biztonságban lesz a mélygarázsban.'::text),
(399585,44399,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sich die Klappe über der Tiefgarage.'::text,'schließt'::text,'schließt'::text,'hat geschlossen'::text,'Gerade schließt sich die Klappe über der Tiefgarage.'::text),
(399589,44399,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз люк ... над підземним гаражем.'::text,'закривається'::text,'закривається'::text,'закрився'::text,'Саме зараз люк закривається над підземним гаражем.'::text),
(399588,44399,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, la trampilla ... sobre el garaje subterráneo.'::text,'se está cerrando'::text,'se cierra'::text,'se ha cerrado'::text,'En este momento, la trampilla se está cerrando sobre el garaje subterráneo.'::text),
(399587,44399,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la trappe ... sur le garage souterrain.'::text,'se referme'::text,'se referme'::text,'s''est refermée'::text,'En ce moment, la trappe se referme sur le garage souterrain.'::text),
(399590,44399,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda kapak yeraltı garajının üzerine ...'::text,'kapanıyor'::text,'kapanır'::text,'kapandı'::text,'Şu anda kapak yeraltı garajının üzerine kapanıyor.'::text),
(399591,44399,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a fedél a mélygarázs fölött.'::text,'záródik le'::text,'záródik le'::text,'lezáródott'::text,'Épp most záródik le a fedél a mélygarázs fölött.'::text),
(349176,38798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er seine Füße wieder durch den See. Eindeutig ein entspannendes Hobby.'::text,'zieht'::text,'wird ziehen'::text,'zieht'::text,'Morgen um diese Zeit zieht er seine Füße wieder durch den See. Eindeutig ein entspannendes Hobby.'::text),
(349180,38798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він знову ... ноги по озеру. Явно розслаблююче хобі.'::text,'тягнутиме'::text,'потягне'::text,'тягне'::text,'Завтра в цей час він знову тягнутиме ноги по озеру. Явно розслаблююче хобі.'::text),
(349179,38798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, él ... los pies por el lago otra vez. Claramente, una afición relajante.'::text,'estará arrastrando'::text,'arrastrará'::text,'arrastra'::text,'Mañana a esta hora, él estará arrastrando los pies por el lago otra vez. Claramente, una afición relajante.'::text),
(349178,38798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... ses pieds dans le lac encore une fois. Clairement un passe-temps relaxant.'::text,'sera en train de traîner'::text,'traînera'::text,'traîne'::text,'Demain à la même heure, il sera en train de traîner ses pieds dans le lac encore une fois. Clairement un passe-temps relaxant.'::text),
(349181,38798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yine ayaklarını gölde ..., belli ki rahatlatıcı bir hobi.'::text,'sürüklüyor olacak'::text,'sürükleyecek'::text,'sürüklüyor'::text,'Yarın bu saatte yine ayaklarını gölde sürüklüyor olacak, belli ki rahatlatıcı bir hobi.'::text),
(349182,38798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a lábát a tóban. Nyilván egy pihentető hobbi.'::text,'húzza'::text,'húzni fogja'::text,'húzza'::text,'Holnap ilyenkor megint húzza a lábát a tóban. Nyilván egy pihentető hobbi.'::text),
(349185,38799,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht, nächstes Mal ... er seine Füße nur einmal durchs Wasser. Na klar.'::text,'zieht'::text,'wird ziehen'::text,'zieht gerade'::text,'Er verspricht, nächstes Mal zieht er seine Füße nur einmal durchs Wasser. Na klar.'::text),
(349189,38799,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що наступного разу ... ноги по воді лише раз. Аякже.'::text,'протягне'::text,'тягнутиме'::text,'тягне'::text,'Він обіцяє, що наступного разу протягне ноги по воді лише раз. Аякже.'::text),
(349188,38799,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que la próxima vez solo ... los pies por el agua una vez. Claro.'::text,'arrastrará'::text,'estará arrastrando'::text,'está arrastrando'::text,'Promete que la próxima vez solo arrastrará los pies por el agua una vez. Claro.'::text),
(349187,38799,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet que la prochaine fois, il ... ses pieds dans l''eau une seule fois. Évidemment.'::text,'traînera'::text,'sera en train de traîner'::text,'traîne'::text,'Il promet que la prochaine fois, il traînera ses pieds dans l''eau une seule fois. Évidemment.'::text),
(349190,38799,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dahaki sefere ayaklarını suda sadece bir kez ... söz veriyor. Tabii ki.'::text,'sürükleyeceğine'::text,'sürüklüyor olacağına'::text,'sürüklediğine'::text,'Bir dahaki sefere ayaklarını suda sadece bir kez sürükleyeceğine söz veriyor. Tabii ki.'::text),
(349191,38799,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy legközelebb csak egyszer ... a lábát a vízben. Hát persze.'::text,'húzza végig'::text,'fogja húzni'::text,'húzza'::text,'Megígéri, hogy legközelebb csak egyszer húzza végig a lábát a vízben. Hát persze.'::text),
(349203,38801,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Paraglider zog seine Füße durch den See, ...?'::text,'oder'::text,'oder'::text,'echt'::text,'Der Paraglider zog seine Füße durch den See, oder?'::text),
(349207,38801,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парапланерист протягнув ноги по озеру, ...?'::text,'так'::text,'так'::text,'справді'::text,'Парапланерист протягнув ноги по озеру, так?'::text),
(349206,38801,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El parapentista arrastró los pies por el lago, ¿...?'::text,'verdad'::text,'verdad'::text,'en serio'::text,'El parapentista arrastró los pies por el lago, ¿verdad?'::text),
(349205,38801,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le parapentiste a traîné ses pieds dans le lac, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'vraiment'::text,'Le parapentiste a traîné ses pieds dans le lac, n''est-ce pas ?'::text),
(349208,38801,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yamaç paraşütçüsü ayaklarını gölde sürükledi, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Yamaç paraşütçüsü ayaklarını gölde sürükledi, değil mi?'::text),
(349209,38801,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A siklóernyős végighúzta a lábát a tavon, ...?'::text,'ugye'::text,'ugye'::text,'tényleg'::text,'A siklóernyős végighúzta a lábát a tavon, ugye?'::text),
(349212,38802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Paraglider zog seine Füße durchs Wasser, und ... sein Spiegelbild im See.'::text,'ebenso'::text,'ebenso war'::text,'ebenso wenig'::text,'Der Paraglider zog seine Füße durchs Wasser, und ebenso sein Spiegelbild im See.'::text),
(349216,38802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парапланерист тягнув ноги по воді, і ... його відображення в озері.'::text,'тягнуло й'::text,'було й'::text,'не тягнуло й'::text,'Парапланерист тягнув ноги по воді, і тягнуло й його відображення в озері.'::text),
(349215,38802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El parapentista arrastró los pies por el agua, y ... su reflejo en el lago.'::text,'también lo hizo'::text,'también lo fue'::text,'tampoco lo hizo'::text,'El parapentista arrastró los pies por el agua, y también lo hizo su reflejo en el lago.'::text),
(349214,38802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le parapentiste a traîné ses pieds dans l''eau, et son reflet dans le lac ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Le parapentiste a traîné ses pieds dans l''eau, et son reflet dans le lac aussi.'::text),
(349217,38802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yamaç paraşütçüsü ayaklarını suda sürükledi, göldeki yansıması da ...'::text,'sürükledi'::text,'öyleydi'::text,'sürüklemedi'::text,'Yamaç paraşütçüsü ayaklarını suda sürükledi, göldeki yansıması da sürükledi.'::text),
(349218,38802,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A siklóernyős végighúzta a lábát a vízen, és ... a tükörképe is a tóban.'::text,'így tett'::text,'így volt'::text,'nem tett így'::text,'A siklóernyős végighúzta a lábát a vízen, és így tett a tükörképe is a tóban.'::text),
(349221,38803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis er landet, wird er seine Füße schon zum dritten Mal durch den See ...'::text,'gezogen haben'::text,'ziehen'::text,'ziehen'::text,'Bis er landet, wird er seine Füße schon zum dritten Mal durch den See gezogen haben.'::text),
(349225,38803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він приземлиться, він уже втретє ... ноги по озеру.'::text,'протягне'::text,'протягне'::text,'тягнутиме'::text,'Поки він приземлиться, він уже втретє протягне ноги по озеру.'::text),
(349224,38803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando aterrice, ... los pies por el lago por tercera vez.'::text,'habrá arrastrado'::text,'arrastrará'::text,'estará arrastrando'::text,'Para cuando aterrice, habrá arrastrado los pies por el lago por tercera vez.'::text),
(349223,38803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''il atterrisse, il ... ses pieds dans le lac pour la troisième fois.'::text,'aura traîné'::text,'traînera'::text,'sera en train de traîner'::text,'D''ici à ce qu''il atterrisse, il aura traîné ses pieds dans le lac pour la troisième fois.'::text),
(349226,38803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnene kadar ayaklarını üçüncü kez gölde ...'::text,'sürüklemiş olacak'::text,'sürükleyecek'::text,'sürüklüyor olacak'::text,'İnene kadar ayaklarını üçüncü kez gölde sürüklemiş olacak.'::text),
(349227,38803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire leszáll, már harmadszor ... végig a lábát a tavon.'::text,'húzza'::text,'húzza'::text,'fogja húzni'::text,'Mire leszáll, már harmadszor húzza végig a lábát a tavon.'::text),
(349230,38804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre das Individuum tiefer gesunken, ... das Wasser es unter die Oberfläche gezogen.'::text,'hätte'::text,'würde'::text,'zog'::text,'Wäre das Individuum tiefer gesunken, hätte das Wasser es unter die Oberfläche gezogen.'::text),
(349234,38804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби особина опустилася нижче, вода ... її під поверхню.'::text,'затягнула б'::text,'затягнула б'::text,'затягнула'::text,'Якби особина опустилася нижче, вода затягнула б її під поверхню.'::text),
(349233,38804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el individuo hubiera descendido más, el agua lo ... bajo la superficie.'::text,'habría arrastrado'::text,'arrastraría'::text,'arrastró'::text,'Si el individuo hubiera descendido más, el agua lo habría arrastrado bajo la superficie.'::text),
(349232,38804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''individu était descendu plus bas, l''eau ... sous la surface.'::text,'l''aurait entraîné'::text,'l''entraînerait'::text,'l''a entraîné'::text,'Si l''individu était descendu plus bas, l''eau l''aurait entraîné sous la surface.'::text),
(349235,38804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birey daha alçağa inseydi, su onu yüzeyin altına ...'::text,'çekmiş olurdu'::text,'çekerdi'::text,'çekti'::text,'Birey daha alçağa inseydi, su onu yüzeyin altına çekmiş olurdu.'::text),
(349236,38804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egyed lejjebb ereszkedett volna, a víz ... a felszín alá.'::text,'lehúzta volna'::text,'lehúzná'::text,'lehúzta'::text,'Ha az egyed lejjebb ereszkedett volna, a víz lehúzta volna a felszín alá.'::text),
(349239,38805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast zugegeben, deine Füße nur fürs Video ... zu haben. Nicht schlecht.'::text,'durch den See gezogen'::text,'durch den See ziehen'::text,'durch den See gezogen'::text,'Du hast zugegeben, deine Füße nur fürs Video durch den See gezogen zu haben. Nicht schlecht.'::text),
(349243,38805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зізнався, що ... ноги по озеру лише заради відео. Спритно.'::text,'тягнув'::text,'тягнути'::text,'тягнув'::text,'Ти зізнався, що тягнув ноги по озеру лише заради відео. Спритно.'::text),
(349242,38805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitiste ... los pies por el lago solo para el vídeo. Qué estilo.'::text,'haber arrastrado'::text,'arrastrar'::text,'arrastraste'::text,'Admitiste haber arrastrado los pies por el lago solo para el vídeo. Qué estilo.'::text),
(349241,38805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as avoué ... tes pieds dans le lac juste pour la vidéo. La classe.'::text,'avoir traîné'::text,'traîner'::text,'as traîné'::text,'Tu as avoué avoir traîné tes pieds dans le lac juste pour la vidéo. La classe.'::text),
(349244,38805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayaklarını gölde sadece video için ... itiraf ettin. Tarz sahibi.'::text,'sürüklediğini'::text,'sürüklemeyi'::text,'sürükledin'::text,'Ayaklarını gölde sadece video için sürüklediğini itiraf ettin. Tarz sahibi.'::text),
(349245,38805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevallottad, hogy csak a videó kedvéért ... végig a lábad a tavon. Ügyes.'::text,'húztad'::text,'húzni'::text,'húztad'::text,'Bevallottad, hogy csak a videó kedvéért húztad végig a lábad a tavon. Ügyes.'::text),
(349248,38806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... jahrelang geübt haben, um deine Füße so perfekt durchs Wasser zu ziehen.'::text,'musst'::text,'solltest'::text,'kannst nicht'::text,'Ehrlich gesagt, du musst jahrelang geübt haben, um deine Füße so perfekt durchs Wasser zu ziehen.'::text),
(349252,38806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... роками, щоб так ідеально тягнути ноги.'::text,'мабуть, тренувався'::text,'мав тренуватися'::text,'не міг тренуватися'::text,'Чесно, ти мабуть, тренувався роками, щоб так ідеально тягнути ноги.'::text),
(349251,38806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... practicado durante años para arrastrar los pies tan perfectamente.'::text,'debes de haber'::text,'deberías haber'::text,'no puedes haber'::text,'No voy a mentir, debes de haber practicado durante años para arrastrar los pies tan perfectamente.'::text),
(349250,38806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... t''entraîner pendant des années pour traîner tes pieds aussi parfaitement.'::text,'as dû'::text,'aurais dû'::text,'n''as pas pu'::text,'Sans mentir, tu as dû t''entraîner pendant des années pour traîner tes pieds aussi parfaitement.'::text),
(349253,38806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ayaklarını bu kadar mükemmel sürüklemek için yıllarca ...'::text,'çalışmış olmalısın'::text,'çalışmalıydın'::text,'çalışmış olamazsın'::text,'Yalan yok, ayaklarını bu kadar mükemmel sürüklemek için yıllarca çalışmış olmalısın.'::text),
(349254,38806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... évekig, hogy ilyen tökéletesen húzd végig a lábad.'::text,'biztosan gyakoroltál'::text,'gyakorolnod kellett volna'::text,'nem gyakorolhattál'::text,'Őszintén, biztosan gyakoroltál évekig, hogy ilyen tökéletesen húzd végig a lábad.'::text),
(349257,38807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, lass den Moment, als du deine Füße durch den See gezogen hast, in Zeitlupe ...'::text,'filmen'::text,'filmen'::text,'filmen'::text,'Ehrlich, lass den Moment, als du deine Füße durch den See gezogen hast, in Zeitlupe filmen.'::text),
(349261,38807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, попроси ... момент, коли ти тягнув ноги по озеру, у сповільненій зйомці.'::text,'зняти'::text,'зняти'::text,'зняти'::text,'Чесно, попроси зняти момент, коли ти тягнув ноги по озеру, у сповільненій зйомці.'::text),
(349260,38807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, haz que ... el momento en que arrastraste los pies por el lago a cámara lenta.'::text,'graben'::text,'graben'::text,'graben'::text,'En serio, haz que graben el momento en que arrastraste los pies por el lago a cámara lenta.'::text),
(349259,38807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, fais ... le moment où tu as traîné tes pieds dans le lac au ralenti.'::text,'filmer'::text,'filmer'::text,'filmer'::text,'Franchement, fais filmer le moment où tu as traîné tes pieds dans le lac au ralenti.'::text),
(349262,38807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cidden, ayaklarını gölde sürüklediğin anı ağır çekimde ...'::text,'çektir'::text,'çektir'::text,'çektir'::text,'Cidden, ayaklarını gölde sürüklediğin anı ağır çekimde çektir.'::text),
(349263,38807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... lassításban azt a pillanatot, amikor végighúztad a lábad a tavon.'::text,'vetesd fel'::text,'vetesd fel'::text,'vetesd fel'::text,'Őszintén, vetesd fel lassításban azt a pillanatot, amikor végighúztad a lábad a tavon.'::text),
(358419,39825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast den perfekten Klippenrand ausgesucht, um zuzusehen, wie das Meer golden wird, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Ehrlich, du hast den perfekten Klippenrand ausgesucht, um zuzusehen, wie das Meer golden wird, oder?'::text),
(358423,39825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти обрав ідеальну скелю, щоб дивитися, як море стає золотим, ...?'::text,'так'::text,'так'::text,'так'::text,'Чесно, ти обрав ідеальну скелю, щоб дивитися, як море стає золотим, так?'::text),
(358422,39825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, elegiste el acantilado perfecto para ver cómo el mar se vuelve dorado, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'De verdad, elegiste el acantilado perfecto para ver cómo el mar se vuelve dorado, ¿verdad?'::text),
(358421,39825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as choisi le sommet de falaise parfait pour voir la mer devenir dorée, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Franchement, tu as choisi le sommet de falaise parfait pour voir la mer devenir dorée, n''est-ce pas ?'::text),
(358424,39825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cidden, denizin altın rengine dönüşünü izlemek için mükemmel uçurumu seçtin, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Cidden, denizin altın rengine dönüşünü izlemek için mükemmel uçurumu seçtin, değil mi?'::text),
(358425,39825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a tökéletes sziklaszirtet választottad, hogy nézd, ahogy aranyszínűvé válik a tenger, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Őszintén, a tökéletes sziklaszirtet választottad, hogy nézd, ahogy aranyszínűvé válik a tenger, ugye?'::text),
(358446,39828,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Sonne den Horizont berührt, wird sich die ganze Bucht golden ...'::text,'gefärbt haben'::text,'färben'::text,'färben'::text,'Bis die Sonne den Horizont berührt, wird sich die ganze Bucht golden gefärbt haben.'::text),
(358450,39828,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки сонце торкнеться обрію, вся затока ... золотою.'::text,'стане'::text,'стане'::text,'ставатиме'::text,'Поки сонце торкнеться обрію, вся затока стане золотою.'::text),
(358449,39828,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el sol toque el horizonte, toda la bahía ... dorada.'::text,'se habrá vuelto'::text,'se volverá'::text,'se estará volviendo'::text,'Para cuando el sol toque el horizonte, toda la bahía se habrá vuelto dorada.'::text),
(358448,39828,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le soleil touchera l''horizon, toute la baie ... dorée.'::text,'sera devenue'::text,'deviendra'::text,'sera en train de devenir'::text,'Quand le soleil touchera l''horizon, toute la baie sera devenue dorée.'::text),
(358451,39828,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş ufka değdiğinde bütün koy altın rengine ...'::text,'bürünmüş olacak'::text,'bürünecek'::text,'bürünüyor olacak'::text,'Güneş ufka değdiğinde bütün koy altın rengine bürünmüş olacak.'::text),
(358452,39828,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a nap eléri a horizontot, az egész öböl aranyszínűvé ...'::text,'válik'::text,'válik majd'::text,'éppen válik'::text,'Mire a nap eléri a horizontot, az egész öböl aranyszínűvé válik.'::text),
(358455,39829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang wird die Drohne zwanzig Minuten über dem goldenen Wasser ...'::text,'geflogen sein'::text,'fliegen'::text,'fliegen'::text,'Bis zum Sonnenuntergang wird die Drohne zwanzig Minuten über dem goldenen Wasser geflogen sein.'::text),
(358459,39829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця дрон ... над золотою водою двадцять хвилин.'::text,'літатиме'::text,'літатиме'::text,'пролетить'::text,'До заходу сонця дрон літатиме над золотою водою двадцять хвилин.'::text),
(358458,39829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, el dron ... sobre el agua dorada durante veinte minutos.'::text,'habrá estado volando'::text,'estará volando'::text,'volará'::text,'Para el atardecer, el dron habrá estado volando sobre el agua dorada durante veinte minutos.'::text),
(358457,39829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, le drone ... au-dessus de l''eau dorée depuis vingt minutes.'::text,'aura volé'::text,'sera en train de voler'::text,'volera'::text,'Au coucher du soleil, le drone aura volé au-dessus de l''eau dorée depuis vingt minutes.'::text),
(358460,39829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar drone yirmi dakikadır altın rengi suyun üzerinde ...'::text,'uçuyor olacak'::text,'uçuyor olacak'::text,'uçacak'::text,'Gün batımına kadar drone yirmi dakikadır altın rengi suyun üzerinde uçuyor olacak.'::text),
(358461,39829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a drón húsz percen át ... az aranyszínű víz fölött.'::text,'repül'::text,'repülni fog'::text,'repül majd'::text,'Napnyugtáig a drón húsz percen át repül az aranyszínű víz fölött.'::text),
(358464,39830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre die Drohne gegen diesen Felsbogen geknallt, ... wir den goldenen Sonnenuntergang nie gesehen. Eine totale Katastrophe!'::text,'hätten'::text,'werden'::text,'sahen'::text,'Wäre die Drohne gegen diesen Felsbogen geknallt, hätten wir den goldenen Sonnenuntergang nie gesehen. Eine totale Katastrophe!'::text),
(358468,39830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби дрон врізався в ту скельну арку, ми ... золотого заходу сонця. Повна катастрофа!'::text,'ніколи б не побачили'::text,'ніколи не побачимо'::text,'ніколи не бачили'::text,'Якби дрон врізався в ту скельну арку, ми ніколи б не побачили золотого заходу сонця. Повна катастрофа!'::text),
(358467,39830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el dron hubiera chocado con ese arco de roca, ... la puesta de sol dorada. ¡Un desastre total!'::text,'nunca habríamos visto'::text,'nunca veremos'::text,'nunca vimos'::text,'Si el dron hubiera chocado con ese arco de roca, nunca habríamos visto la puesta de sol dorada. ¡Un desastre total!'::text),
(358466,39830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le drone avait heurté cette arche rocheuse, nous ... le coucher de soleil doré. Un désastre total !'::text,'n''aurions jamais vu'::text,'ne verrons jamais'::text,'n''avons jamais vu'::text,'Si le drone avait heurté cette arche rocheuse, nous n''aurions jamais vu le coucher de soleil doré. Un désastre total !'::text),
(358469,39830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drone o kaya kemerine çarpsaydı, altın rengi gün batımını asla ..., tam bir felaket!'::text,'görmemiş olurduk'::text,'göremeyeceğiz'::text,'görmedik'::text,'Drone o kaya kemerine çarpsaydı, altın rengi gün batımını asla görmemiş olurduk, tam bir felaket!'::text),
(358470,39830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a drón nekiment volna annak a sziklaívnek, ... az aranyszínű naplementét. Totális katasztrófa!'::text,'sosem láttuk volna'::text,'sosem fogjuk látni'::text,'sosem láttuk'::text,'Ha a drón nekiment volna annak a sziklaívnek, sosem láttuk volna az aranyszínű naplementét. Totális katasztrófa!'::text),
(358473,39831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Akku an der Klippe leer gegangen, ... wir jetzt nicht auf dieses goldene Meer. Ein Albtraum!'::text,'starrten'::text,'hätten gestarrt'::text,'werden starren'::text,'Wäre der Akku an der Klippe leer gegangen, starrten wir jetzt nicht auf dieses goldene Meer. Ein Albtraum!'::text),
(358477,39831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби батарея сіла біля скелі, ми зараз ... на це золоте море. Жах!'::text,'не дивилися б'::text,'не дивилися б'::text,'не дивитимемося'::text,'Якби батарея сіла біля скелі, ми зараз не дивилися б на це золоте море. Жах!'::text),
(358476,39831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la batería se hubiera agotado en el acantilado, ahora ... este mar dorado. ¡Una pesadilla!'::text,'no estaríamos mirando'::text,'no habríamos mirado'::text,'no miraremos'::text,'Si la batería se hubiera agotado en el acantilado, ahora no estaríamos mirando este mar dorado. ¡Una pesadilla!'::text),
(358475,39831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la batterie avait lâché à la falaise, nous ... cette mer dorée maintenant. Un cauchemar !'::text,'ne regarderions pas'::text,'n''aurions pas regardé'::text,'ne regarderons pas'::text,'Si la batterie avait lâché à la falaise, nous ne regarderions pas cette mer dorée maintenant. Un cauchemar !'::text),
(358478,39831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Batarya uçurumda bitseydi, şu an bu altın rengi denize ..., tam bir kâbus!'::text,'bakıyor olmazdık'::text,'bakmış olmazdık'::text,'bakmayacağız'::text,'Batarya uçurumda bitseydi, şu an bu altın rengi denize bakıyor olmazdık, tam bir kâbus!'::text),
(358479,39831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szikláknál lemerült volna az akku, most ... erre az aranyszínű tengerre. Rémálom!'::text,'nem bámulnánk'::text,'nem bámultunk volna'::text,'nem fogunk bámulni'::text,'Ha a szikláknál lemerült volna az akku, most nem bámulnánk erre az aranyszínű tengerre. Rémálom!'::text),
(358482,39832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser goldene Sonnenuntergang soll nur Sekunden vor dem totalen Akku-Aus ...!'::text,'gefilmt worden sein'::text,'gefilmt werden'::text,'filmend'::text,'Dieser goldene Sonnenuntergang soll nur Sekunden vor dem totalen Akku-Aus gefilmt worden sein!'::text),
(358486,39832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що цей золотий захід сонця ... за кілька секунд до того, як батарея повністю сіла!'::text,'зняли'::text,'знімають'::text,'зйомка'::text,'Кажуть, що цей золотий захід сонця зняли за кілька секунд до того, як батарея повністю сіла!'::text),
(358485,39832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se dice que este atardecer dorado ... segundos antes de que la batería muriera por completo!'::text,'fue grabado'::text,'es grabado'::text,'grabando'::text,'¡Se dice que este atardecer dorado fue grabado segundos antes de que la batería muriera por completo!'::text),
(358484,39832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que ce coucher de soleil doré ... quelques secondes avant que la batterie ne meure complètement !'::text,'a été filmé'::text,'est filmé'::text,'filmant'::text,'On dit que ce coucher de soleil doré a été filmé quelques secondes avant que la batterie ne meure complètement !'::text),
(358487,39832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu altın rengi gün batımının, batarya tamamen bitmeden saniyeler önce ... söyleniyor!'::text,'çekildiği'::text,'çekileceği'::text,'çekerek'::text,'Bu altın rengi gün batımının, batarya tamamen bitmeden saniyeler önce çekildiği söyleniyor!'::text),
(358488,39832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag ezt az aranyszínű naplementét másodpercekkel azelőtt ..., hogy az akku teljesen lemerült!'::text,'vették fel'::text,'veszik fel'::text,'felvéve'::text,'Állítólag ezt az aranyszínű naplementét másodpercekkel azelőtt vették fel, hogy az akku teljesen lemerült!'::text),
(358491,39833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich hat der Schwimmer abgestritten, die Drohne über dem goldenen Wasser ...'::text,'gesehen zu haben'::text,'gesehen zu haben'::text,'sah'::text,'Bestie, angeblich hat der Schwimmer abgestritten, die Drohne über dem goldenen Wasser gesehen zu haben.'::text),
(358495,39833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, плавець заперечив, що ... дрон над золотою водою.'::text,'бачив'::text,'бачив'::text,'бачив'::text,'Подруго, кажуть, плавець заперечив, що бачив дрон над золотою водою.'::text),
(358494,39833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el nadador negó ... el dron sobre el agua dorada.'::text,'haber visto'::text,'haber visto'::text,'vio'::text,'Amiga, al parecer el nadador negó haber visto el dron sobre el agua dorada.'::text),
(358493,39833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment le nageur a nié ... le drone au-dessus de l''eau dorée.'::text,'avoir vu'::text,'avoir vu'::text,'a vu'::text,'Ma belle, apparemment le nageur a nié avoir vu le drone au-dessus de l''eau dorée.'::text),
(358496,39833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya yüzücü altın rengi suyun üzerindeki drone''u ... inkâr etmiş.'::text,'gördüğünü'::text,'görmüş olduğunu'::text,'gördü'::text,'Kanka, güya yüzücü altın rengi suyun üzerindeki drone''u gördüğünü inkâr etmiş.'::text),
(358497,39833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az úszó tagadta, hogy ... a drónt az aranyszínű víz fölött.'::text,'látta'::text,'látta'::text,'látta'::text,'Csajszi, állítólag az úszó tagadta, hogy látta a drónt az aranyszínű víz fölött.'::text),
(358500,39834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, der Schwimmer ... total durchgefroren gewesen sein, als das goldene Licht gestern Abend verblasste.'::text,'muss'::text,'sollte'::text,'muss'::text,'Hör mal, ich hab gehört, der Schwimmer muss total durchgefroren gewesen sein, als das goldene Licht gestern Abend verblasste.'::text),
(358504,39834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що плавець ... змерзлим, коли вчора ввечері згасло золоте світло.'::text,'мабуть, був'::text,'мав бути'::text,'мабуть, є'::text,'Слухай, я чула, що плавець мабуть, був змерзлим, коли вчора ввечері згасло золоте світло.'::text),
(358503,39834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijeron que el nadador ... congelado cuando la luz dorada se apagó anoche.'::text,'debía de estar'::text,'debería haber estado'::text,'debe de estar'::text,'Oye, me dijeron que el nadador debía de estar congelado cuando la luz dorada se apagó anoche.'::text),
(358502,39834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que le nageur ... gelé quand la lumière dorée s''est éteinte hier soir.'::text,'devait être'::text,'aurait dû être'::text,'doit être'::text,'Écoute, j''ai entendu dire que le nageur devait être gelé quand la lumière dorée s''est éteinte hier soir.'::text),
(358505,39834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki dün gece altın ışık söndüğünde yüzücü ...'::text,'donmuş olmalı'::text,'donması gerekirdi'::text,'donuyor olmalı'::text,'Dinle, duydum ki dün gece altın ışık söndüğünde yüzücü donmuş olmalı.'::text),
(358506,39834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy az úszó ..., amikor tegnap este kihunyt az aranyszínű fény.'::text,'biztosan fagyoskodott'::text,'fagyoskodnia kellett volna'::text,'biztosan fagyoskodik'::text,'Figyelj, azt hallottam, hogy az úszó biztosan fagyoskodott, amikor tegnap este kihunyt az aranyszínű fény.'::text),
(358509,39835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich blieb sie auf der Klippe, bis ... im goldenen Meer versank.'::text,'die Sonne'::text,'eine Sonne'::text,'Sonne'::text,'Mädel, angeblich blieb sie auf der Klippe, bis die Sonne im goldenen Meer versank.'::text),
(358513,39835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона лишалася на скелі, поки ... сонце не сіло в золоте море.'::text,''::text,NULL::text,NULL::text,'Подруго, кажуть, вона лишалася на скелі, поки сонце не сіло в золоте море.'::text),
(358512,39835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer se quedó en el acantilado hasta que ... se hundió en el mar dorado.'::text,'el sol'::text,'un sol'::text,'sol'::text,'Tía, al parecer se quedó en el acantilado hasta que el sol se hundió en el mar dorado.'::text),
(358511,39835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle est restée sur la falaise jusqu''à ce que ... se couche dans la mer dorée.'::text,'le soleil'::text,'un soleil'::text,'soleil'::text,'Ma belle, apparemment elle est restée sur la falaise jusqu''à ce que le soleil se couche dans la mer dorée.'::text),
(358514,39835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya ... güneş altın rengi denize batana kadar uçurumda kalmış.'::text,''::text,'bir'::text,NULL::text,'Kızım, güya güneş altın rengi denize batana kadar uçurumda kalmış.'::text),
(358515,39835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag addig maradt a sziklán, amíg ... bele nem süllyedt az aranyszínű tengerbe.'::text,'a nap'::text,'egy nap'::text,'nap'::text,'Csajszi, állítólag addig maradt a sziklán, amíg a nap bele nem süllyedt az aranyszínű tengerbe.'::text),
(399846,44428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Bikes gerade aufrecht, als die Sonne unterging. Eindeutig ein langweiliger Abend.'::text,'hielten'::text,'hielten'::text,'haben gehalten'::text,'Sie hielten die Bikes gerade aufrecht, als die Sonne unterging. Eindeutig ein langweiliger Abend.'::text),
(399850,44428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... мотоцикли вертикально, коли сонце сіло. Явно нудний вечір.'::text,'тримали'::text,'втримали'::text,'втримали'::text,'Вони тримали мотоцикли вертикально, коли сонце сіло. Явно нудний вечір.'::text),
(399849,44428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... las motos en vertical cuando se puso el sol. Claramente, una tarde aburrida.'::text,'mantenían'::text,'mantuvieron'::text,'han mantenido'::text,'Ellos mantenían las motos en vertical cuando se puso el sol. Claramente, una tarde aburrida.'::text),
(399848,44428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... les motos à la verticale quand le soleil s''est couché. Clairement une soirée ennuyeuse.'::text,'tenaient'::text,'tinrent'::text,'ont tenu'::text,'Ils tenaient les motos à la verticale quand le soleil s''est couché. Clairement une soirée ennuyeuse.'::text),
(399851,44428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş battığında motosikletleri dik ..., belli ki sıkıcı bir akşam.'::text,'tutuyorlardı'::text,'tuttular'::text,'tutmuşlar'::text,'Güneş battığında motosikletleri dik tutuyorlardı, belli ki sıkıcı bir akşam.'::text),
(399852,44428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen ... függőlegesen a motorokat, amikor lement a nap. Nyilván egy unalmas este.'::text,'tartották'::text,'megtartották'::text,'megtartották'::text,'Éppen tartották függőlegesen a motorokat, amikor lement a nap. Nyilván egy unalmas este.'::text),
(399855,44429,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fahrer ... ihre Bikes schon lange aufrecht.'::text,'halten'::text,'halten'::text,'halten'::text,'Die Fahrer halten ihre Bikes schon lange aufrecht.'::text),
(399859,44429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Райдери вже довго ... свої мотоцикли вертикально.'::text,'тримають'::text,'тримають'::text,'тримають'::text,'Райдери вже довго тримають свої мотоцикли вертикально.'::text),
(399858,44429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los pilotos ... sus motos en vertical desde hace mucho rato.'::text,'mantienen'::text,'están manteniendo'::text,'mantienen'::text,'Los pilotos mantienen sus motos en vertical desde hace mucho rato.'::text),
(399857,44429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pilotes ... leurs motos à la verticale depuis longtemps maintenant.'::text,'tiennent'::text,'tiennent'::text,'tiennent'::text,'Les pilotes tiennent leurs motos à la verticale depuis longtemps maintenant.'::text),
(399860,44429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürücüler uzun süredir motosikletlerini dik ...'::text,'tutuyor'::text,'tutuyor'::text,'tutar'::text,'Sürücüler uzun süredir motosikletlerini dik tutuyor.'::text),
(399861,44429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motorosok már hosszú ideje függőlegesen ... a motorjukat.'::text,'tartják'::text,'tartják'::text,'tartják'::text,'A motorosok már hosszú ideje függőlegesen tartják a motorjukat.'::text),
(399864,44430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie fuhren am Strand entlang, als sie plötzlich ihre Bikes in die Senkrechte ...'::text,'zogen'::text,'gerade zogen'::text,'gezogen haben'::text,'Sie fuhren am Strand entlang, als sie plötzlich ihre Bikes in die Senkrechte zogen.'::text),
(399868,44430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони їхали пляжем, коли раптом ... мотоцикли вертикально.'::text,'підняли'::text,'піднімали'::text,'підняли'::text,'Вони їхали пляжем, коли раптом підняли мотоцикли вертикально.'::text),
(399867,44430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Iban por la playa cuando de repente ... las motos en vertical.'::text,'pusieron'::text,'estaban poniendo'::text,'han puesto'::text,'Iban por la playa cuando de repente pusieron las motos en vertical.'::text),
(399866,44430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils roulaient le long de la plage quand soudain ils ... leurs motos à la verticale.'::text,'ont levé'::text,'levaient'::text,'ont levé'::text,'Ils roulaient le long de la plage quand soudain ils ont levé leurs motos à la verticale.'::text),
(399869,44430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahil boyunca gidiyorlardı ki birden motosikletlerini dikine ...'::text,'kaldırdılar'::text,'kaldırıyorlardı'::text,'kaldırmışlar'::text,'Sahil boyunca gidiyorlardı ki birden motosikletlerini dikine kaldırdılar.'::text),
(399870,44430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parton motoroztak, amikor hirtelen függőlegesbe ... a motorjukat.'::text,'rántották'::text,'rántották éppen'::text,'rántották'::text,'A parton motoroztak, amikor hirtelen függőlegesbe rántották a motorjukat.'::text),
(399873,44431,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fahrer ... ihre Bikes seit Sonnenuntergang dreimal aufgerichtet.'::text,'haben'::text,'haben'::text,'richteten'::text,'Die Fahrer haben ihre Bikes seit Sonnenuntergang dreimal aufgerichtet.'::text),
(399877,44431,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від заходу сонця райдери тричі ... мотоцикли вертикально.'::text,'поставили'::text,'ставили'::text,'поставили'::text,'Від заходу сонця райдери тричі поставили мотоцикли вертикально.'::text),
(399876,44431,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los pilotos ... las motos en vertical tres veces desde el atardecer.'::text,'han puesto'::text,'han estado poniendo'::text,'pusieron'::text,'Los pilotos han puesto las motos en vertical tres veces desde el atardecer.'::text),
(399875,44431,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pilotes ... leurs motos à la verticale trois fois depuis le coucher du soleil.'::text,'ont mis'::text,'mettent'::text,'ont mis'::text,'Les pilotes ont mis leurs motos à la verticale trois fois depuis le coucher du soleil.'::text),
(399878,44431,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımından beri sürücüler motosikletlerini üç kez dikine ...'::text,'kaldırdılar'::text,'kaldırıyorlar'::text,'kaldırdılar'::text,'Gün batımından beri sürücüler motosikletlerini üç kez dikine kaldırdılar.'::text),
(399879,44431,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugta óta a motorosok háromszor ... függőlegesbe a motorjukat.'::text,'állították'::text,'állítgatták'::text,'állították'::text,'Napnyugta óta a motorosok háromszor állították függőlegesbe a motorjukat.'::text),
(399882,44432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Sonne verschwand, ... beide Bikes schon eine furchterregende Minute lang aufrecht gestanden!'::text,'hatten'::text,'haben'::text,'stehen'::text,'Als die Sonne verschwand, hatten beide Bikes schon eine furchterregende Minute lang aufrecht gestanden!'::text),
(399886,44432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки сонце зникло, обидва мотоцикли ... вертикально цілу жахливу хвилину!'::text,'простояли'::text,'простояли'::text,'стоять'::text,'Поки сонце зникло, обидва мотоцикли простояли вертикально цілу жахливу хвилину!'::text),
(399885,44432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando el sol desapareció, ambas motos ... en vertical durante un minuto aterrador!'::text,'habían estado'::text,'han estado'::text,'están'::text,'¡Para cuando el sol desapareció, ambas motos habían estado en vertical durante un minuto aterrador!'::text),
(399884,44432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le soleil a disparu, les deux motos ... à la verticale pendant une minute terrifiante !'::text,'étaient restées'::text,'sont restées'::text,'restent'::text,'Quand le soleil a disparu, les deux motos étaient restées à la verticale pendant une minute terrifiante !'::text),
(399887,44432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş kaybolduğunda iki motosiklet de korkunç bir dakika boyunca dik ...!'::text,'durmuştu'::text,'durdu'::text,'duruyor'::text,'Güneş kaybolduğunda iki motosiklet de korkunç bir dakika boyunca dik durmuştu!'::text),
(399888,44432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a nap eltűnt, mindkét motor egy rémisztő percig ... függőlegesen!'::text,'állt'::text,'állt'::text,'áll'::text,'Mire a nap eltűnt, mindkét motor egy rémisztő percig állt függőlegesen!'::text),
(399900,44434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Bikes nicht aufrecht wären, ... ihre Spiegelbilder im Wasser nicht so hoch aus.'::text,'sähen'::text,'werden'::text,'sehen'::text,'Wenn die Bikes nicht aufrecht wären, sähen ihre Spiegelbilder im Wasser nicht so hoch aus.'::text),
(399904,44434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби мотоцикли не стояли вертикально, їхні відображення ... у воді такими високими.'::text,'не виглядали б'::text,'не виглядатимуть'::text,'не виглядають'::text,'Якби мотоцикли не стояли вертикально, їхні відображення не виглядали б у воді такими високими.'::text),
(399903,44434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las motos no estuvieran en vertical, sus reflejos ... tan altos en el agua.'::text,'no parecerían'::text,'no parecerán'::text,'no parecen'::text,'Si las motos no estuvieran en vertical, sus reflejos no parecerían tan altos en el agua.'::text),
(399902,44434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les motos n''étaient pas à la verticale, leurs reflets ... aussi grands dans l''eau.'::text,'ne paraîtraient pas'::text,'ne paraîtront pas'::text,'ne paraissent pas'::text,'Si les motos n''étaient pas à la verticale, leurs reflets ne paraîtraient pas aussi grands dans l''eau.'::text),
(399905,44434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Motosikletler dik olmasaydı, sudaki yansımaları bu kadar uzun ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmüyor'::text,'Motosikletler dik olmasaydı, sudaki yansımaları bu kadar uzun görünmezdi.'::text),
(399906,44434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a motorok nem lennének függőlegesek, a tükörképük ... ilyen magasnak a vízben.'::text,'nem tűnne'::text,'nem fog tűnni'::text,'nem tűnik'::text,'Ha a motorok nem lennének függőlegesek, a tükörképük nem tűnne ilyen magasnak a vízben.'::text),
(399909,44435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, angeblich ... beide Bikes die ganze Fahrt über aufrecht gehalten.'::text,'wurden'::text,'hielten'::text,'halten'::text,'Krass, angeblich wurden beide Bikes die ganze Fahrt über aufrecht gehalten.'::text),
(399913,44435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, обидва мотоцикли ... вертикально всю поїздку.'::text,'утримувалися'::text,'тримали'::text,'тримають'::text,'Та ну, кажуть, обидва мотоцикли утримувалися вертикально всю поїздку.'::text),
(399912,44435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, al parecer las dos motos ... en vertical todo el trayecto.'::text,'fueron mantenidas'::text,'mantuvieron'::text,'están manteniendo'::text,'No puede ser, al parecer las dos motos fueron mantenidas en vertical todo el trayecto.'::text),
(399911,44435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, apparemment les deux motos ... à la verticale pendant tout le trajet.'::text,'ont été tenues'::text,'ont tenu'::text,'tiennent'::text,'Sérieux, apparemment les deux motos ont été tenues à la verticale pendant tout le trajet.'::text),
(399914,44435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz, güya iki motosiklet de bütün sürüş boyunca dik ...'::text,'tutulmuş'::text,'tutmuş'::text,'tutuyor'::text,'Olamaz, güya iki motosiklet de bütün sürüş boyunca dik tutulmuş.'::text),
(399915,44435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na ne, állítólag mindkét motort az egész út alatt függőlegesen ...'::text,'tartották'::text,'tartotta'::text,'tartják'::text,'Na ne, állítólag mindkét motort az egész út alatt függőlegesen tartották.'::text),
(399918,44436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sie ... die Bikes bis in den Sonnenuntergang aufrecht.'::text,'hielten'::text,'wurden gehalten'::text,'haltend'::text,'Hör mal, ich hab gehört, sie hielten die Bikes bis in den Sonnenuntergang aufrecht.'::text),
(399922,44436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вони ... мотоцикли вертикально аж до заходу сонця.'::text,'втримали'::text,'були втримані'::text,'втримуючи'::text,'Слухай, я чула, що вони втримали мотоцикли вертикально аж до заходу сонця.'::text),
(399921,44436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijeron que ... las motos en vertical hasta la puesta de sol.'::text,'mantuvieron'::text,'fueron mantenidos'::text,'manteniendo'::text,'Oye, me dijeron que mantuvieron las motos en vertical hasta la puesta de sol.'::text),
(399920,44436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''ils ... les motos à la verticale jusqu''au coucher du soleil.'::text,'ont gardé'::text,'ont été gardés'::text,'gardant'::text,'Écoute, j''ai entendu dire qu''ils ont gardé les motos à la verticale jusqu''au coucher du soleil.'::text),
(399923,44436,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki motosikletleri gün batımına kadar dik ...'::text,'tutmuşlar'::text,'tutulmuşlar'::text,'tutarak'::text,'Dinle, duydum ki motosikletleri gün batımına kadar dik tutmuşlar.'::text),
(399924,44436,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy egészen a naplementéig függőlegesen ... a motorokat.'::text,'tartották'::text,'tartották'::text,'tartva'::text,'Figyelj, azt hallottam, hogy egészen a naplementéig függőlegesen tartották a motorokat.'::text),
(399927,44437,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stark: Du ... das Bike ewig aufrecht gehalten, bevor es jemand gemerkt hat.'::text,'hattest'::text,'hast'::text,'hältst'::text,'Stark: Du hattest das Bike ewig aufrecht gehalten, bevor es jemand gemerkt hat.'::text),
(399931,44437,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круто: ти ... той мотоцикл вертикально цілу вічність, перш ніж хтось помітив.'::text,'тримав'::text,'тримаєш'::text,'тримаєш'::text,'Круто: ти тримав той мотоцикл вертикально цілу вічність, перш ніж хтось помітив.'::text),
(399930,44437,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con estilo: ... esa moto en vertical una eternidad antes de que alguien se diera cuenta.'::text,'habías estado sosteniendo'::text,'has estado sosteniendo'::text,'sostienes'::text,'Con estilo: habías estado sosteniendo esa moto en vertical una eternidad antes de que alguien se diera cuenta.'::text),
(399929,44437,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La classe : tu ... cette moto à la verticale pendant une éternité avant que quelqu''un ne remarque.'::text,'tenais'::text,'tiens'::text,'tiens'::text,'La classe : tu tenais cette moto à la verticale pendant une éternité avant que quelqu''un ne remarque.'::text),
(399932,44437,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarz sahibi: kimse fark etmeden önce o motosikleti uzun süre dik ...'::text,'tutmuştun'::text,'tutuyorsun'::text,'tutarsın'::text,'Tarz sahibi: kimse fark etmeden önce o motosikleti uzun süre dik tutmuştun.'::text),
(399933,44437,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menő: egy örökkévalóságig ... függőlegesen azt a motort, mielőtt bárki észrevette.'::text,'tartottad'::text,'tartod'::text,'tartod'::text,'Menő: egy örökkévalóságig tartottad függőlegesen azt a motort, mielőtt bárki észrevette.'::text),
(380190,42244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... einen weiteren Hai am selben Strand.'::text,'rettet er gerade'::text,'wird er retten'::text,'rettet er'::text,'Morgen um diese Zeit rettet er gerade einen weiteren Hai am selben Strand.'::text),
(380194,42244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він ... ще одну акулу на тому самому пляжі.'::text,'рятуватиме'::text,'врятує'::text,'рятує'::text,'Завтра в цей час він рятуватиме ще одну акулу на тому самому пляжі.'::text),
(380193,42244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, él ... a otro tiburón en la misma playa.'::text,'estará rescatando'::text,'rescatará'::text,'rescata'::text,'Mañana a esta hora, él estará rescatando a otro tiburón en la misma playa.'::text),
(380192,42244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... un autre requin sur la même plage.'::text,'sera en train de sauver'::text,'sauvera'::text,'sauve'::text,'Demain à la même heure, il sera en train de sauver un autre requin sur la même plage.'::text),
(380195,42244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte aynı sahilde başka bir köpekbalığını ...'::text,'kurtarıyor olacak'::text,'kurtaracak'::text,'kurtarır'::text,'Yarın bu saatte aynı sahilde başka bir köpekbalığını kurtarıyor olacak.'::text),
(380196,42244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor épp egy másik cápát ... ugyanazon a strandon.'::text,'fog menteni'::text,'megment'::text,'ment'::text,'Holnap ilyenkor épp egy másik cápát fog menteni ugyanazon a strandon.'::text),
(380199,42245,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht, dass er jeden Hai ..., der an diesem Strand stecken bleibt.'::text,'retten wird'::text,'gerade retten wird'::text,'gerade rettet'::text,'Er verspricht, dass er jeden Hai retten wird, der an diesem Strand stecken bleibt.'::text),
(380203,42245,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що ... кожну акулу, яка застрягне на цьому пляжі.'::text,'врятує'::text,'рятуватиме'::text,'рятує'::text,'Він обіцяє, що врятує кожну акулу, яка застрягне на цьому пляжі.'::text),
(380202,42245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que ... a cada tiburón que quede atrapado en esta playa.'::text,'rescatará'::text,'estará rescatando'::text,'está rescatando'::text,'Promete que rescatará a cada tiburón que quede atrapado en esta playa.'::text),
(380201,42245,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il ... chaque requin qui se retrouve coincé sur cette plage.'::text,'sauvera'::text,'sera en train de sauver'::text,'est en train de sauver'::text,'Il promet qu''il sauvera chaque requin qui se retrouve coincé sur cette plage.'::text),
(380204,42245,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sahilde mahsur kalan her köpekbalığını ... söz veriyor.'::text,'kurtaracağına'::text,'kurtarıyor olacağına'::text,'kurtardığına'::text,'Bu sahilde mahsur kalan her köpekbalığını kurtaracağına söz veriyor.'::text),
(380205,42245,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy minden cápát ..., amely ezen a strandon rekedt.'::text,'megment'::text,'menteni fog'::text,'éppen ment'::text,'Megígéri, hogy minden cápát megment, amely ezen a strandon rekedt.'::text),
(380208,42246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Menschen einen gestrandeten Hai schnell retten, ... er normalerweise davon.'::text,'schwimmt'::text,'schwamm'::text,'würde schwimmen'::text,'Wenn Menschen einen gestrandeten Hai schnell retten, schwimmt er normalerweise davon.'::text),
(380212,42246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо люди швидко рятують акулу, що застрягла на березі, вона зазвичай ...'::text,'відпливає'::text,'відпливла'::text,'відпливла б'::text,'Якщо люди швидко рятують акулу, що застрягла на березі, вона зазвичай відпливає.'::text),
(380211,42246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gente rescata rápido a un tiburón varado, normalmente ...'::text,'se aleja nadando'::text,'se alejó nadando'::text,'se alejaría nadando'::text,'Si la gente rescata rápido a un tiburón varado, normalmente se aleja nadando.'::text),
(380210,42246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si des gens sauvent vite un requin échoué, il ... généralement.'::text,'repart à la nage'::text,'repartit à la nage'::text,'repartirait à la nage'::text,'Si des gens sauvent vite un requin échoué, il repart à la nage généralement.'::text),
(380213,42246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar karaya vurmuş bir köpekbalığını çabuk kurtarırsa, genellikle yüzerek ...'::text,'uzaklaşır'::text,'uzaklaştı'::text,'uzaklaşırdı'::text,'İnsanlar karaya vurmuş bir köpekbalığını çabuk kurtarırsa, genellikle yüzerek uzaklaşır.'::text),
(380214,42246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az emberek gyorsan megmentenek egy partra vetett cápát, az általában ...'::text,'elúszik'::text,'elúszott'::text,'elúszna'::text,'Ha az emberek gyorsan megmentenek egy partra vetett cápát, az általában elúszik.'::text),
(380217,42247,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, er ... ein Rettungsschwimmer sein, der Haie rettet, aber wer weiß.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Okay, also ich hab gehört, er könnte ein Rettungsschwimmer sein, der Haie rettet, aber wer weiß.'::text),
(380221,42247,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, я чула, що він ... бути рятувальником, який рятує акул, але хто знає.'::text,'може'::text,'мусить'::text,'мав би'::text,'Отже, я чула, що він може бути рятувальником, який рятує акул, але хто знає.'::text),
(380220,42247,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bueno, me dijeron que él ... ser un socorrista que rescata tiburones, pero quién sabe.'::text,'podría'::text,'debe de'::text,'debería'::text,'Bueno, me dijeron que él podría ser un socorrista que rescata tiburones, pero quién sabe.'::text),
(380219,42247,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire qu''il ... être un maître-nageur qui sauve des requins, mais qui sait.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Bon, j''ai entendu dire qu''il pourrait être un maître-nageur qui sauve des requins, mais qui sait.'::text),
(380222,42247,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki köpekbalıklarını kurtaran bir cankurtaran ..., ama kim bilir.'::text,'olabilirmiş'::text,'olmalıymış'::text,'olması gerekirmiş'::text,'Tamam, duydum ki köpekbalıklarını kurtaran bir cankurtaran olabilirmiş, ama kim bilir.'::text),
(380223,42247,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na szóval, azt hallottam, hogy ő ... egy cápákat mentő vízimentő, de ki tudja.'::text,'talán'::text,'biztosan'::text,'elvileg'::text,'Na szóval, azt hallottam, hogy ő talán egy cápákat mentő vízimentő, de ki tudja.'::text),
(380235,42249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... den Hai auf jeden Fall retten, und ehrlich, Respekt.'::text,'würdest'::text,'wirst'::text,'rettest'::text,'Du hast gesagt, du würdest den Hai auf jeden Fall retten, und ehrlich, Respekt.'::text),
(380239,42249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказав, що ... ту акулу за будь-яку ціну, і чесно, респект.'::text,'врятуєш'::text,'врятуєш'::text,'рятуєш'::text,'Ти сказав, що врятуєш ту акулу за будь-яку ціну, і чесно, респект.'::text),
(380238,42249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que ... a ese tiburón pasara lo que pasara, y sinceramente, respeto.'::text,'rescatarías'::text,'rescatarás'::text,'rescatas'::text,'Dijiste que rescatarías a ese tiburón pasara lo que pasara, y sinceramente, respeto.'::text),
(380237,42249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... ce requin quoi qu''il arrive, et franchement, respect.'::text,'sauverais'::text,'sauveras'::text,'sauves'::text,'Tu as dit que tu sauverais ce requin quoi qu''il arrive, et franchement, respect.'::text),
(380240,42249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne olursa olsun o köpekbalığını ... söyledin, ve açıkçası, saygılar.'::text,'kurtaracağını'::text,'kurtaracağını'::text,'kurtardığını'::text,'Ne olursa olsun o köpekbalığını kurtaracağını söyledin, ve açıkçası, saygılar.'::text),
(380241,42249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy mindenképp ... azt a cápát, és őszintén, respect.'::text,'megmented'::text,'megmented'::text,'mented'::text,'Azt mondtad, hogy mindenképp megmented azt a cápát, és őszintén, respect.'::text),
(380244,42250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht gelogen, du ... Angst vor Haien, und jetzt rettest du sie.'::text,'hattest früher'::text,'hättest'::text,'warst es gewohnt'::text,'Nicht gelogen, du hattest früher Angst vor Haien, und jetzt rettest du sie.'::text),
(380248,42250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти ... акул, а тепер їх рятуєш.'::text,'раніше боявся'::text,'боявся б'::text,'звик боятися'::text,'Не брехатиму, ти раніше боявся акул, а тепер їх рятуєш.'::text),
(380247,42250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... miedo a los tiburones, y ahora los rescatas.'::text,'solías tener'::text,'tendrías'::text,'estabas acostumbrado a tener'::text,'No voy a mentir, solías tener miedo a los tiburones, y ahora los rescatas.'::text),
(380246,42250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, tu ... peur des requins, et maintenant tu les sauves.'::text,'avais'::text,'aurais'::text,'avais l''habitude d''avoir'::text,'Sans mentir, tu avais peur des requins, et maintenant tu les sauves.'::text),
(380249,42250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, eskiden köpekbalıklarından ..., şimdi onları kurtarıyorsun.'::text,'korkardın'::text,'korkardın'::text,'korkmaya alışkındın'::text,'Yalan yok, eskiden köpekbalıklarından korkardın, şimdi onları kurtarıyorsun.'::text),
(380250,42250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, régen ... a cápáktól, most meg mented őket.'::text,'féltél'::text,'félnél'::text,'hozzá voltál szokva, hogy félj'::text,'Nem fogok hazudni, régen féltél a cápáktól, most meg mented őket.'::text),
(380253,42251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er zögerte nicht, den Hai ..., offensichtlich ein entspannter Strandtag.'::text,'zu retten'::text,'zu retten'::text,'retten'::text,'Er zögerte nicht, den Hai zu retten, offensichtlich ein entspannter Strandtag.'::text),
(380257,42251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не вагався ... акулу. Очевидно, розслаблений день на пляжі.'::text,'врятувати'::text,'рятування'::text,'врятувати'::text,'Він не вагався врятувати акулу. Очевидно, розслаблений день на пляжі.'::text),
(380256,42251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No dudó en ... al tiburón. Obviamente, un día de playa relajante.'::text,'rescatar'::text,'rescatar'::text,'rescatar'::text,'No dudó en rescatar al tiburón. Obviamente, un día de playa relajante.'::text),
(380255,42251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''a pas hésité à ... le requin. Évidemment, une journée plage relaxante.'::text,'sauver'::text,'sauver'::text,'sauver'::text,'Il n''a pas hésité à sauver le requin. Évidemment, une journée plage relaxante.'::text),
(380258,42251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekbalığını ... tereddüt etmedi. Belli ki rahatlatıcı bir plaj günü.'::text,'kurtarmakta'::text,'kurtarmakta'::text,'kurtarmak'::text,'Köpekbalığını kurtarmakta tereddüt etmedi. Belli ki rahatlatıcı bir plaj günü.'::text),
(380259,42251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem habozott ... a cápát. Nyilván egy pihentető strandnap.'::text,'megmenteni'::text,'megmenteni'::text,'megmenteni'::text,'Nem habozott megmenteni a cápát. Nyilván egy pihentető strandnap.'::text),
(380262,42252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haie am Schwanz zu retten ist ein ganz normales Hobby, offensichtlich, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Haie am Schwanz zu retten ist ein ganz normales Hobby, offensichtlich, oder?'::text),
(380266,42252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рятувати акул за хвіст — звичайне хобі, очевидно, ...?'::text,'так'::text,'так'::text,'так'::text,'Рятувати акул за хвіст — звичайне хобі, очевидно, так?'::text),
(380265,42252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rescatar tiburones por la cola es una afición normal, obviamente, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Rescatar tiburones por la cola es una afición normal, obviamente, ¿verdad?'::text),
(380264,42252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sauver des requins par la queue, c''est un passe-temps normal, évidemment, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Sauver des requins par la queue, c''est un passe-temps normal, évidemment, n''est-ce pas ?'::text),
(380267,42252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekbalıklarını kuyruğundan kurtarmak normal bir hobi, belli ki, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Köpekbalıklarını kuyruğundan kurtarmak normal bir hobi, belli ki, değil mi?'::text),
(380268,42252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cápákat a farkuknál fogva menteni teljesen normális hobbi, nyilván, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Cápákat a farkuknál fogva menteni teljesen normális hobbi, nyilván, ugye?'::text),
(380271,42253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er ... jeden Sommer Haie an diesem Strand, ohne Witz.'::text,'rettet'::text,'rettet'::text,'hat gerettet'::text,'Digga, er rettet jeden Sommer Haie an diesem Strand, ohne Witz.'::text),
(380275,42253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... акул на цьому пляжі щоліта, без приколів.'::text,'рятує'::text,'рятує'::text,'врятував'::text,'Чувак, він рятує акул на цьому пляжі щоліта, без приколів.'::text),
(380274,42253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... tiburones en esta playa cada verano, en serio.'::text,'rescata'::text,'está rescatando'::text,'ha rescatado'::text,'Tío, él rescata tiburones en esta playa cada verano, en serio.'::text),
(380273,42253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... des requins sur cette plage chaque été, sans mentir.'::text,'sauve'::text,'sauve'::text,'a sauvé'::text,'Mec, il sauve des requins sur cette plage chaque été, sans mentir.'::text),
(380276,42253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o her yaz bu sahilde köpekbalıklarını ..., yemin ederim.'::text,'kurtarıyor'::text,'kurtarıyor'::text,'kurtardı'::text,'Kanka, o her yaz bu sahilde köpekbalıklarını kurtarıyor, yemin ederim.'::text),
(380277,42253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő minden nyáron ... cápákat ezen a strandon, komolyan.'::text,'ment'::text,'ment'::text,'mentett'::text,'Tesó, ő minden nyáron ment cápákat ezen a strandon, komolyan.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
